/**
 * Connects the properties to a master property.
 * @param {DuAEProperty[]|DuList.<DuAEProperty>} props - The child properties
 * @param {Property|DuAEProperty} masterProp - The parent property
 * @param {float} [min=0] - The minimum value
 * @param {float} [max=100] - The maximum value
 * @param {DuAE.Axis} [axis=DuAE.Axis.X] - The axis or channel to connect
 * @param {DuAE.Type} [type=DuAE.Type.VALUE] - The type
 * @param {boolean} [toKeyMorph] By default, the connector will detect Key Morphs to adjust the connection on the weight of the selected keys.<br/>
 * When set to true, it will just connect the weight of the selected key morphs (or all of them if not selected).<br/>
 * When false, it does a standard connection even if some key morphs are selected.
 * @return {PropertyGroup} The controlling effect created
 */
Duik.Constraint.connector = function(props, masterProp, min, max, axis, type, toKeyMorph) {
    min = def(min, 0);
    max = def(max, 100);
    axis = def(axis, DuAE.Axis.X);
    type = def(type, DuAE.Type.VALUE);

    var doKeyMorph = -1;
    if (typeof toKeyMorph !== 'undefined') {
        if (toKeyMorph) doKeyMorph = 1;
        else doKeyMorph = 0;
    }

    masterProp = new DuAEProperty(masterProp);

    // Adjust values
    if (isNaN(min)) min = 0;
    if (isNaN(max)) min = 100;

    var dim = masterProp.dimensions();
    if (dim == 4) {
        var bpc = app.project.bitsPerChannel;
        if (bpc == 8) {
            min /= 255;
            max /= 255;
        } else if (bpc == 16) {
            min /= 32768;
            max /= 32768;
        } else if (bpc == 32) {
            if (min < 0) min = 0;
            else if (min > 1) min = 1;
            if (max < 0) max = 0;
            else if (max > 1) max = 1;
        }
    }

    DuAEComp.setUniqueLayerNames(undefined, masterProp.comp);

    // Get layer
    var masterLayer = masterProp.layer;

    // Try to find an already existing effect
    var effect = null;
    var pe = Duik.PseudoEffect.ONED_CONNECTOR;
    if (dim == 2) pe = Duik.PseudoEffect.TWOD_CONNECTOR;
    else if (dim == 3) pe = Duik.PseudoEffect.THREED_CONNECTOR;
    else if (dim == 4) pe = Duik.PseudoEffect.COLOR_CONNECTOR;

    var modeId = pe.props['Connection mode'].index;
    var minId = pe.props['Minimum'].index
    var maxId = pe.props['Maximum'].index;
    var axisId = 4;
    if (dim > 1 && dim < 4) axisId = pe.props['Axis'].index;
    else if (dim == 4) axisId = pe.props['Channel'].index;

    var connectorEffects = DuAEProperty.getProps(masterLayer.property('ADBE Effect Parade'), pe.matchName, true);

    // Check if there is one with the same settings
    for (var i = 0, num = connectorEffects.length; i < num; i++) {
        var e = connectorEffects[i];
        if (e.prop(minId).value() != min) continue;
        if (e.prop(maxId).value() != max) continue;
        if (e.prop(modeId).value() != type) continue;
        if (dim > 1 && dim < 4) {
            if (e.prop(axisId).value() != axis) continue;
        }
        if (dim == 4) {
            if (e.prop(axisId).value() != axis - 3) continue;
        }
        //if all tests passed, this is the one!
        effect = e;
        break;
    }

    // If not found, create and set values
    if (!effect) {
        effect = pe.apply(masterLayer, i18n._("Connector") + ' ' + masterProp.name);
        effect(minId).setValue(min);
        effect(maxId).setValue(max);
        effect(modeId).setValue(type);
        if (dim == 4) effect(axisId).setValue(axis - 3);
        else if (dim > 1) effect(axisId).setValue(axis);
    }

    var peKeyMorph = Duik.PseudoEffect.KEY_MORPH_K;
    function keyMorphProp( prop ) {
        if (prop.matchName == peKeyMorph.matchName) return new DuAEProperty(prop.getProperty().property(4));
        var p = prop.getProperty().parentProperty;
        if (p.matchName == peKeyMorph.matchName) return prop;
        return null;
    }

    // Prepare the expression

    var colorValFn = 	[ 'function getColorVal(col, axis) {',
        '	if (axis == 1) return col[0];',
        '	if (axis == 2) return col[1];',
        '	if (axis == 3) return col[2];',
        '	if (axis == 4) return col[3];',
        '	var c = rgbToHsl(col);',
        '	if (axis == 5) return c[0];',
        '	if (axis == 6) return c[1];',
        '	if (axis == 4) return c[2];',
        '}',
        ''
    ].join('\n');

    var exp = [
        'var ctrlValue = ctrlLayer' + masterProp.expressionLink(false, false) + ';',
        'var ctrlEffect = ctrlLayer.effect("' + effect.name + '");',
        'var ctrlMin = ctrlEffect(' + minId + ').value;',
        'var ctrlMax = ctrlEffect(' + maxId + ').value;',
        'var ctrlType = ctrlEffect(' + modeId + ').value;',
        'var result = value;',
        'if (numKeys >= 2 && ctrlEffect.active)',
        '{',
        'if (ctrlType == 2) ctrlValue = ctrlValue.speed;',
        'else if (ctrlType == 3) ctrlValue = ctrlValue.velocity;',
        'else ctrlValue = ctrlValue.value;'
    ].join('\n');

    if (masterProp.isAngle()) {
        exp += '\nif (ctrlType == 1) ctrlValue = ctrlValue % 360;\n';
    } else if (dim == 2 || dim == 3) {
        exp += '\nif (ctrlType == 1 || ctrlType == 3) {\nvar axis = ctrlEffect(' + axisId + ').value-1;\nctrlValue = ctrlValue[axis];\n}\n'
    } else if (dim == 4) {
        exp += colorValFn +
            'var axis = ctrlEffect(' + axisId + ').value;\n' +
            'ctrlValue = getColorVal(ctrlValue, axis);\n';
    }
    exp += 'var t = 0;\n' +
        'var beginTime = key(1).time;\n' +
        'var endTime = key(numKeys).time;\n' +
        'if (ctrlMin > ctrlMax)\n' +
        '{\n' +
        't = linear(ctrlValue, ctrlMin, ctrlMax, endTime, beginTime);\n' +
        '}\n' +
        'else\n' +
        '{\n' +
        't = linear(ctrlValue, ctrlMin, ctrlMax, beginTime, endTime);\n' +
        '}\n' +
        'result = valueAtTime(t);\n' +
        '}\n' +
    'result;';

    var kmExp1 = [
        '// Connector effect',
        'var ctrlValue = ctrlLayer' + masterProp.expressionLink(false, false) + ';',
        'var ctrlEffect = ctrlLayer.effect("' + effect.name + '");',
        'var ctrlMin = ctrlEffect(' + minId + ').value;',
        'var ctrlMax = ctrlEffect(' + maxId + ').value;',
        '// Key morph values'
    ].join('\n');

    if (masterProp.isDropdown()) kmExp1 += '\nvar isMenu = true;';
    else kmExp1 += '\nvar isMenu = false;';

    var kmExp2 = [
        DuAEExpression.Library.get([
            'getNextKey',
            'getPrevKey'
        ]),
        'function interpolate()',
        '{',
        '  if (!ctrlEffect.active) return 0;',
        '  if (numMorphs == 0) return 0;',
        '',
        '  numMorphs--;',
        '  var pK = getPrevKey(time, ctrlValue);',
        '  var nK = getNextKey(time, ctrlValue);',
        '',
    ].join('\n');

    if (masterProp.isAngle()) {
        kmExp2 += '\nvar cValue = linear(ctrlValue.value % 360, ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 2 || dim == 3) {
        kmExp2 += '\nvar axis = ctrlEffect(' + axisId + ').value-1;\nvar cValue = linear(ctrlValue.value[axis], ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 4) {
        kmExp2 += colorValFn +
            '\nvar axis = ctrlEffect(' + axisId + ').value;\n' +
            'var cValue = getColorVal(ctrlValue.value, axis);\n' +
            'cValue = linear(cValue, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }
    else {
        kmExp2 += '\nvar cValue = linear(ctrlValue.value, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }

    kmExp2 += '  if (!pK || !nK) {\n' +
        '    if (Math.round(cValue) == thisIndex) return 100;\n' +
        '    else return 0;\n' +
        '  }\n' +
        '	var nValue = 0;\n' +
        '	var pValue = 0;\n' +
    '	if(nK) {';

    if (masterProp.isAngle()) {
        kmExp2 += '  nValue = linear(nK.value % 360, ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 2 || dim == 3) {
        kmExp2 += 'nValue = linear(nK.value[axis], ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 4) {
        kmExp2 += colorValFn +
            'nValue = getColorVal(nK.value, axis);\n' +
            'nValue = linear(nValue, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }
    else {
        kmExp2 += '  nValue = linear(nK.value, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }
    
    kmExp2 += '    nValue = Math.round(nValue);\n' +
        '  }\n' +
    '	if(pK) {';

    if (masterProp.isAngle()) {
        kmExp2 += '  pValue = linear(pK.value % 360, ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 2 || dim == 3) {
        kmExp2 += 'pValue = linear(pK.value[axis], ctrlMin, ctrlMax, 0, numMorphs);\n';
    } else if (dim == 4) {
        kmExp2 += colorValFn +
            'pValue = getColorVal(pK.value, axis);\n' +
            'pValue = linear(pValue, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }
    else {
        kmExp2 += '  pValue = linear(pK.value, ctrlMin, ctrlMax, 0, numMorphs);\n';
    }

    kmExp2 += '    pValue = Math.round(pValue);\n' +
        '  }\n' +
        '\n' +
        'if (isMenu) {\n' +
        '    cValue = easeOut(time, pK.time, nK.time, pValue, nValue);\n' +
        '}\n' +
        '\n' +
        '  if (pValue != thisIndex && nValue != thisIndex) return 0;\n' +
        '  if (pValue == nValue) return 100;\n' +
        '\n' +
        '  if (pValue == thisIndex && pValue < nValue)\n' +
        '      return linear( cValue, nValue, pValue, 100, 0 );\n' +
        '  if (pValue == thisIndex && pValue >= nValue)\n' +
        '       return linear( cValue, pValue, nValue, 0, 100 );\n' +
        '  if (pValue < nValue)\n' +
        '      return linear( cValue, pValue, nValue, 0, 100 );\n' +
        '  return linear( cValue, pValue, nValue, 100, 0 );\n' +
        '}\n' +
        '\n' +
        'var result = value + interpolate();\n' +
        '\n' +
    'result;';

    // Count key morphs
    props = new DuList(props);
    var kmProps = new DuList();
    if (doKeyMorph != 0)
        for (var i = props.length()-1; i >= 0; i--)
        {
            var kmP = keyMorphProp(new DuAEProperty(props.at(i)));
            if (kmP) {
                kmProps.pushUnique(undefined, kmP);
                props.remove(i);
            }
        }
    // Try to find key morphs on the layers
    if (doKeyMorph == 1 && kmProps.length() == 0) {
        var kmLayers = new DuList();
        for (var i = props.length()-1; i >= 0; i--)
        {
            var p = new DuAEProperty(props.at(i));
            var l = p.layer;
            if ( kmLayers.contains(l), function(a, b) { return a.index == b.index; } ) continue;
            for (var f = 1, nf = l.property("ADBE Effect Parade").numProperties; f <= nf; f++) {
                var fx = l.property("ADBE Effect Parade").property(f);
                var kmP = keyMorphProp(new DuAEProperty(fx));
                if (kmP) {
                    kmProps.pushUnique(undefined, kmP);
                }
            }
        }
    }

    kmProps.sort(function(a, b) {
        return a.getProperty().parentProperty.propertyIndex - b.getProperty().parentProperty.propertyIndex;
    });

    // Set to the props
    var masterComp = masterLayer.containingComp;
    var comp = 'thisComp.';

    if (doKeyMorph != 1) props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (!prop.riggable()) return;
        // check if the current comp is the same than the comp containing the masterProperty
        var childComp = prop.comp;
        if (masterComp !== childComp) comp = 'comp("' + masterComp.name + '").';
        else comp = 'thisComp.';
        prop.setExpression(
            DuAEExpression.Id.CONNECTOR + '\n' +
            'var ctrlLayer = ' + comp + 'layer("' + masterLayer.name + '");\n' +
            exp,
            false
        );
        if (prop.matchName == "ADBE Opacity") prop.layer.enabled = true;//*/
    });

    if (doKeyMorph != 0) kmProps.do(function(prop) {
        // check if the current comp is the same than the comp containing the masterProperty
        var childComp = prop.comp;
        if (masterComp !== childComp) comp = 'comp("' + masterComp.name + '").';
        else comp = 'thisComp.';

        prop.setExpression(
            DuAEExpression.Id.CONNECTOR + '\n' +
            'var ctrlLayer = ' + comp + 'layer("' + masterLayer.name + '");\n' +
            kmExp1 +
            '\nvar numMorphs = ' + kmProps.length() + ';\n' + 
            'var thisIndex = ' + kmProps.current + ';\n' + 
            kmExp2,
            false
        );
    });

    return effect;
}

Duik.CmdLib['Constraint']["Connector"] = "Duik.Constraint.quickConnector()";
/**
 * Connects the properties together to a % slider
 * @param {Property[]|DuAEProperty[]} [props] - The properties to connect. The selected properties by default.
 */
Duik.Constraint.quickConnector = function(props) {
    props = def(props, DuAEComp.getSelectedProps());
    if (props.length == 0) return;
    props = new DuList(props);

    DuAE.beginUndoGroup(i18n._("Connector"), false);

    // Create the slider
    var ctrlLayer = props.first().layer;
    var comp = props.first().comp;
    var effect = Duik.PseudoEffect.QUICK_CONNECTOR.apply(ctrlLayer);

    DuAEComp.setUniqueLayerNames(undefined, comp);

    var exp = [ DuAEExpression.Id.CONNECTOR,
        'var ctrlLayer = thisComp.layer("' + ctrlLayer.name + '");',
        'var ctrlEffect = ctrlLayer.effect("' + effect.name + '");',
        'var ctrlValue = ctrlEffect(1);',
        'var ctrlMin = 0;',
        'var ctrlMax = 100;',
        'var result = value;',
        'if (numKeys >= 2 && ctrlEffect.enabled)',
        '{',
        'ctrlValue = ctrlValue.value;',
        'var t = 0;',
        'var beginTime = key(1).time;',
        'var endTime = key(numKeys).time;',
        'if (ctrlMin > ctrlMax)',
        '{',
        't = linear(ctrlValue, ctrlMin, ctrlMax, endTime, beginTime);',
        '}',
        'else',
        '{',
        't = linear(ctrlValue, ctrlMin, ctrlMax, beginTime, endTime);',
        '}',
        'result = valueAtTime(t);',
        '}',
        'result;'
    ].join('\n');

    var firstTime = comp.duration;
    var lastTime = 0;

    props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (!prop.riggable()) return;
        // Set the expression
        prop.setExpression(exp, false);
        // Get first/last time
        var f = prop.firstKeyTime();
        if (f != null) if (f < firstTime) firstTime = f;
        var l = prop.lastKeyTime();
        if (l != null) if (l > lastTime) lastTime = l;
    });

    // Set default keyframes
    effect(1).setValuesAtTimes([firstTime, lastTime], [0,100]);

    DuAE.endUndoGroup(i18n._("Connector"));
}

/**
 * Connects a dropdown menu effect to a list of layers, using their opacities.<br />
 * Note: On After Effects < 17.0.1, the list is not updated to reflect the list of layers.
 * @param {DuAEProperty|Property} dropdown The dropdown menu property.
 * @param {Layer[]|DuList.<Layer>} [layers] The layers to control. The selected layers by default.
 */
Duik.Constraint.linkLayersToDropdown = function(dropdown, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());

    dropdown = new DuAEProperty(dropdown);
    var effect = dropdown.parentProperty();

    var masterComp = dropdown.comp;
    var masterLayer = dropdown.layer;

    var updateDropdown = DuAE.version.atLeast('17.0.1');

    layers = new DuList(layers);
    var layerNames = [];
    layers.do(function(layer) {
        // check if the current comp is the same than the comp containing the masterProperty
        var childComp = layer.containingComp;
        var comp;
        if (masterComp !== childComp) comp = 'comp("' + masterComp.name + '").';
        else comp = 'thisComp.';

        var id = layers.current + 1;

        layer.transform.opacity.expression = [DuAEExpression.Id.CONNECTOR,
            'var ctrlLayer = ' + comp + 'layer("' + masterLayer.name + '");\n' +
            'var fx = ctrlLayer.effect("' + effect.name + '");',
            'var result = 0;',
            'if (fx(1).value == ' + id + ') result = value;',
            'result;'
        ].join('\n');

        if (updateDropdown) layerNames.push(layer.name);
    });

    if (updateDropdown) dropdown.setPropertyParameters(layerNames);
}

/**
 * Prepares a visual audio controller to connect to properties
 * @param {AVLayer} [audioLayer] The layer with the audio to setup. The selected layer by default.
 * @return {DuAEProperty} The value to use with the connector
 */
Duik.Constraint.setupAudioController = function(audioLayer) {
    audioLayer = def(audioLayer, DuAEComp.getActiveLayer());
    if (!audioLayer) return;
    if (!audioLayer.hasAudio) return;

    DuAE.beginUndoGroup(i18n._("Audio connector"), false);

    // Duplicate the layer
    audioLayer.duplicate();
    // Precompose
    var comp = audioLayer.containingComp;
    var index = audioLayer.index;
    var acCompName = DuAEProject.newUniqueCompName('AC.' + i18n._("Settings") + '::' + audioLayer.name);
    var acComp = comp.layers.precompose([index], acCompName);
    // Lock and hide the precomp
    var acCompLayer = comp.layer(index);
    acCompLayer.moveToEnd();
    acCompLayer.enabled = false;
    acCompLayer.audioEnabled = false;
    acCompLayer.guideLayer = true;
    acCompLayer.shy = true;

    // Setup the controllers
    audioLayer = acComp.layer(1);

    // Add the spectrum layer
    var spectrumLayer = acComp.layers.addShape();
    Duik.Layer.setAttributes(
        spectrumLayer,
        Duik.Layer.Type.AUDIO,
        i18n._("Audio spectrum"),
        undefined,
        undefined,
        i18n._("Audio spectrum")
        );
    var solidGroup = spectrumLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    solidGroup.name = 'Solid';
    var solidContent = solidGroup.property("ADBE Vectors Group");
    var solid = solidContent.addProperty("ADBE Vector Shape - Rect");
    solid('ADBE Vector Rect Size').expression = '[thisComp.width, thisComp.height*3];';
    var fill = solidContent.addProperty("ADBE Vector Graphic - Fill");
    fill("ADBE Vector Fill Color").setValue([0,0,0,1]);

    // Add an Ear layer
    var earLayer = Duik.Controller.create(acComp, Duik.Controller.Type.EAR);
    earLayer.transform.position.setValue([acComp.width / 4, acComp.height / 2]);

    // Add the settings layer
    var settingsLayer = Duik.Controller.create(acComp, Duik.Controller.Type.AUDIO);
    Duik.Layer.setGroupName( i18n._("Audio Effector"), settingsLayer);
    // Add effect
    var pe = Duik.PseudoEffect.AUDIO_CONNECTOR;
    var ampId = pe.props['Amplitude'].index;
    var minId = pe.props['Minimum frequency (Hz)'].index;
    var maxId = pe.props['Maximum frequency (Hz)'].index;
    var easeId = pe.props['Ease'].index;
    var timeEaseId = pe.props['Time settings']['Ease (seconds)'].index;
    var offsetId = pe.props['Time settings']['Offset (seconds)'].index;
    var settingsEffect = pe.apply(settingsLayer);

    // Setup the spectrum
    var spectrumEffect = spectrumLayer.property('ADBE Effect Parade').addProperty('ADBE AudSpect');
    spectrumEffect(1).setValue(4); // Audio Layer
    spectrumEffect(2).expression = '[0,thisComp.height]'; // start point
    spectrumEffect(3).expression = '[thisComp.width,thisComp.height]'; // end point
    spectrumEffect(6).expression = 'thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + minId + ')'; // start freq
    spectrumEffect(7).expression = 'thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + maxId + ')'; // end freq
    spectrumEffect(9).expression = 'thisComp.height * thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + ampId + ') / 100;'; // max height
    spectrumEffect(10).expression = '1000*( thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + timeEaseId + ') + thisComp.frameDuration);'; // audio duration
    spectrumEffect(11).expression = '1000*thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + offsetId + ');'; // audio offset
    spectrumEffect(12).expression = 'thisComp.width/thisProperty.propertyGroup()(8)+10;'; // thickness
    spectrumEffect(13).setValue(0); // softness
    spectrumEffect(14).setValue([1,1,1,1]); // inside color
    spectrumEffect(15).expression = 'thisProperty.propertyGroup()(14);'; // outside color
    spectrumEffect(23).setValue(1); // composite on original
    var blurEffect = spectrumLayer.property('ADBE Effect Parade').addProperty('ADBE Motion Blur');
    blurEffect(2).expression = 'thisComp.height*thisComp.layer("' + settingsLayer.name + '").effect("' + settingsEffect.name + '")(' + easeId + ')/100'; // blur length
    spectrumLayer.locked = true;

    // Setup the ear
    var earEffect = earLayer.property('ADBE Effect Parade').addProperty('ADBE Slider Control');
    earEffect.name = i18n._("Audio Effector");
    earEffect(1).expression = [ DuAEExpression.Id.AUDIO_EFFECTOR,
        'var spectrumLayer = thisComp.layer("' + spectrumLayer.name + '");',
        'var smpl = spectrumLayer.sampleImage(thisLayer.position);',
        'smpl[0]*100;'
    ].join('\n');

    DuAE.endUndoGroup(i18n._("Audio connector"));

    // OK!
    return new DuAEProperty( earEffect(1) );
}
// ====== rig.jsx======

/**
 * (Auto)Rigging tools.
 * @namespace
 * @category Duik
 */
Duik.Rig = {};

/**
 * The list of (auto)rigging functions
 * @namespace
 */
Duik.CmdLib['Auto-rig'] = {};


Duik.CmdLib['Auto-rig']['Rig'] = 'Duik.Rig.auto()';
/**
 * The auto-rig for everything
 * @param {Boolean} [bakeBones=true] Whether to bake bones
 * @param {Boolean} [bakeEnvelops=true] Whether to bake envelops
 * @param {Boolean} [bakeNoodles=true] Whether to remove deactivated noodles
 * @param {Duik.Constraint.IKType} [longChainMode=Duik.Constraint.IKType.FK] Set to true if you prefer using Bézier IK than FK with overlap for tails and other chains consisting of more than 3 layers.
 * @param {Duik.Constraint.IKType} [threeLayerMode=Duik.Constraint.IKType.ONE_TWO] The type of IK to use with custom 3-layer chains.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig. All selected layers by default.
 * @param {Boolean} [createMaster=false] Set to true to add a master/root controller which controls all other controllers
 * @return {Layer[]} The controllers which are used in the rig
 */
Duik.Rig.auto = function ( bakeBones, bakeEnvelops, bakeNoodles, longChainMode, threeLayerMode, layers, createMaster )
{
    bakeBones = def( bakeBones, true );
    bakeEnvelops = def( bakeEnvelops, true );
    bakeNoodles = def( bakeNoodles, true );
    threeLayerMode = def( threeLayerMode, Duik.Constraint.IKType.ONE_TWO );
    longChainMode = def( longChainMode , Duik.Constraint.IKType.FK );
    createMaster = def(createMaster, false);

    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return;

    var comp = layers.first().containingComp;

    //check if there are 3D Layers
    for (var i = 0, n = layers.length(); i < n; i++)
    {
        if (layers.at(i).threeDLayer)
        {
            alert( i18n._("Some layers are 3D layers, that's a problem...") +
                '\n' + i18n._("This can't be rigged, sorry."));
            return;
        }
    }

    DuAE.beginUndoGroup( i18n._("Auto-rig"), false );
    DuAEProject.setProgressMode( true );

    // Progress
    DuScriptUI.progressBar.stg( i18n._("Auto-rig"));
    DuScriptUI.progressBar.msg( i18n._("Sorting layers...") );

    // Sort layers
    var bones = [];
    var customControllers = [];
    var otherLayers = [];
    layers.do(function( layer )
    {
        // It's already rigged, ignore
        if (Duik.Bone.isRigged(layer)) return;

        // It's a bone
        if ( Duik.Layer.isType( layer, Duik.Layer.Type.BONE ) )
            bones.push(layer);
        // It's a controller
        else if ( Duik.Layer.isType( layer, Duik.Layer.Type.CONTROLLER ) )
            customControllers.push(layer);
        // It's something else
        else otherLayers.push(layer);
    });

    // No bones, standard IK
    if (bones.length == 0) {
        var ctrl = null;
        if (customControllers.length > 0) ctrl = customControllers[0];
        Duik.Constraint.ik(threeLayerMode, false, otherLayers, ctrl, longChainMode == Duik.Constraint.IKType.BEZIER_FK );
    }

    // Create OCO Doc from bones
    var ocoDoc = OCODoc.fromComp('', comp, bones );

    // Start by baking (improves perf and optionaly keeps envelops)
    Duik.Bone.bake(bakeBones, bakeEnvelops, bakeNoodles, bones, false);
    DuAEComp.unselectLayers();
    
    // Rig all limbs
    DuScriptUI.progressBar.addMax( ocoDoc.numLimbs() * 4 ); // 4 steps per limb
    

    for (var i  = 0, ni = ocoDoc.limbs.length; i < ni; i++ )
        Duik.Rig.limb( ocoDoc.limbs[i], customControllers, longChainMode, threeLayerMode );

    // Try to parent limbs which weren't parented.
    var spine = ocoDoc.getSpine();
    if (spine != null)
    {
        var spineLayers = spine.getLayers();
        if (spineLayers.length > 0)
        {
            for (var i  = 0, ni = ocoDoc.limbs.length; i < ni; i++ )
            {
                var limb = ocoDoc.limbs[i];
                // If it's a spine, ignore
                if (limb.limb == OCO.Limb.SPINE || limb.limb == OCO.Limb.FISH_SPINE)
                    continue;

                if (limb.armature.length == 0)
                    continue;

                // Find the parent bone
                var parentBone = null;
                var rootBone = limb.armature[0];
                if (!rootBone.layer) continue;

                // If it's a leg -> parent to the hips no matter what!
                if (limb.limb == OCO.Limb.LEG)
                    parentBone = spineLayers[0];
                else
                    parentBone = Duik.Rig.getSpineAttach(
                        DuAELayer.getWorldPos(rootBone.layer),
                        spineLayers
                    );

                Duik.Rig.parentLimb(limb, parentBone);
            }
        }
    }

    // TODO Get/Create a master, parent orphan controllers to it
    // Collect controllers
    var ctrls = [];
    var limbs = ocoDoc.getLimbs();
    for (var i  = 0, ni = limbs.length; i < ni; i++ )
    {
        ctrls = ctrls.concat( limbs[i].ctrls );
    }

    var masterCtrl = null;
    if (createMaster)
    {
        for (var i  = 0, ni = ctrls.length; i < ni; i++ )
        {
            var ctrl = ctrls[i];
            if (ctrl.parent) continue;
            if (!masterCtrl) {
                DuAEComp.unselectLayers();
                DuAEComp.selectLayers(ctrls);
                masterCtrl = Duik.Controller.fromLayers( Duik.Controller.Type.NULL, false, true )[0];
                break;
            }
        }
    }

    if (masterCtrl) {
        /* @ts-ignore */
        masterCtrl.transform.position.setValue( [masterCtrl.transform.position.value[0], comp.height - comp.height * .05] );
        Duik.Layer.setName(i18n._("Root"), masterCtrl); /// TRANSLATORS: The name of a controller which controls all other controllers.
        DuAELayer.parent(ctrls, masterCtrl, true, false);
    }
    else {
        // Select the controllers
        DuAEComp.unselectLayers();
        DuAEComp.selectLayers(ctrls);
    }

    // If controllers are nulls, move them to the top of the comp
    if ( OCO.config.get('after effects/controller layer type', Duik.Controller.LayerMode.SHAPE) == Duik.Controller.LayerMode.NULL) {
        for (var i = 0; i < ctrls.length; i++) {
            ctrls[i].moveBefore( comp.layer(1)
        ); };
    };
    

    DuAEProject.setProgressMode( false );
    DuAE.endUndoGroup( i18n._("Auto-rig") );
}

/**
 * Parents a rigged limb (i.e. the bones and controllers) to a bone.<br/>
 * The limb must have been rigged with {@link Duik.Rig.limb}, or must have a <code>.ctrls</code> attribute, which is an array of Layer containing the controllers.
 * @param {OCOLimb} limb The limb to parent
 * @param {OCOBone} bone The parent bone
 */
Duik.Rig.parentLimb = function(limb, parentLayer)
{
    // Parent root bones
    for (var i = 0, ni = limb.armature.length; i < ni; i++)
    {
        var rootBone = limb.armature[i];
        if (rootBone.layer)
        {
            var rootParent = rootBone.layer.parent;
            if (rootParent == null)
                rootBone.layer.parent = parentLayer;
            else if (rootParent.parent == null)
                rootParent.parent = parentLayer;
        }
    }

    // For some limbs, we need to parent controllers too
    if (limb.limb == OCO.Limb.TAIL)
    {
        // Ctrls should follow the parent
        for (var i = 0, ni = limb.ctrls.length; i < ni; i++)
        {
            var ctrl = limb.ctrls[i];
            if (ctrl.parent == null) ctrl.parent = parentLayer;
        }
    }
    else if (limb.limb == OCO.Limb.WING)
    {
        var ctrl = limb.ctrls[0];
        if (ctrl.parent == null) ctrl.parent = parentLayer;
    }
    else if (limb.limb == OCO.Limb.HAIR)
    {
        var ctrl = limb.ctrls[0];
        if (ctrl.parent == null) ctrl.parent = parentLayer;
    }
    else if (limb.limb == OCO.Limb.FIN)
    {
        var ctrl = limb.ctrls[0];
        if (ctrl.parent == null) ctrl.parent = parentLayer;
    }
    else if (limb.limb == OCO.Limb.CUSTOM)
    {
        // Ctrls follow the parent by default (?)
        for (var i = 0, ni = limb.ctrls.length; i < ni; i++)
        {
            var ctrl = limb.ctrls[i];
            if (ctrl.parent == null) ctrl.parent = parentLayer;
        }
    }
}

/**
 * Auto-rigs an OCOLimb if it exists in the comp
 * @param {OCOLimb} limb The limb to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @param {Duik.Constraint.IKType} [longChainMode=Duik.Constraint.IKType.FK] How to rig tails and other chains consisting of more than 3 layers.
 * @param {Duik.Constraint.IKType} [threeLayerMode=Duik.Constraint.IKType.ONE_TWO] How to rig 3-layer chains.
 */
Duik.Rig.limb = function (limb, customControllers, longChainMode, threeLayerMode)
{

    // Bake the armature data in case it's not, to fix reparenting issues with noodles & envelops
    var layers = limb.getLayers();
    Duik.Bone.bakeArmatureData( limb.getLayers() );

    // Check the type of the limb
    if (limb.limb == OCO.Limb.SPINE)
    {
        limb.ctrls = Duik.Rig.spine( layers, customControllers );
    }
    else if (limb.limb == OCO.Limb.ARM)
    {
        limb.ctrls = [ Duik.Rig.arm( layers, customControllers ) ];
    }
    else if (limb.limb == OCO.Limb.LEG)
    {
        limb.ctrls = [ Duik.Rig.leg( layers, customControllers ) ];
    }
    else if (limb.limb == OCO.Limb.TAIL)
    {
        limb.ctrls = Duik.Rig.tail( layers, longChainMode, customControllers );
    }
    else if (limb.limb == OCO.Limb.WING)
    {
        limb.ctrls = [ Duik.Rig.wing( layers, customControllers ) ];
    }
    else if (limb.limb == OCO.Limb.HAIR)
    {
        limb.ctrls = Duik.Rig.hair( layers, customControllers );
    }
    else if (limb.limb == OCO.Limb.SNAKE_SPINE)
    {
        // Not implemented yet
    }
    else if (limb.limb == OCO.Limb.FISH_SPINE)
    {
        limb.ctrls = Duik.Rig.fishSpine( layers, longChainMode, customControllers );
    }
    else if (limb.limb == OCO.Limb.FIN)
    {
        limb.ctrls = [ Duik.Rig.fin( layers, customControllers ) ];
    }
    else if (limb.limb == OCO.Limb.CUSTOM)
    {
        limb.ctrls = Duik.Rig.custom( layers, longChainMode, threeLayerMode, customControllers );
    }

    // Rig child limbs (and parent them)
    function rigChildLimbs(bone)
    {
        for (var j = 0, nj = bone.limbs.length; j < nj; j++)
        {
            var childLimb = bone.limbs[j];
            if (childLimb.armature.length == 0) continue;
            Duik.Rig.limb(childLimb, customControllers, longChainMode, threeLayerMode);
            Duik.Rig.parentLimb(childLimb, bone.layer);
        }
        for (var j = 0, nj = bone.children.length; j < nj; j++)
        {
            rigChildLimbs(bone.children[j]);
        }
    }
    for (var i = 0, ni = limb.armature.length; i < ni; i++)
    {
        var bone = limb.armature[i];
        rigChildLimbs(bone);
    }
}

/**
 * Rigs a spine.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Layer[]} The controllers for the spine.
 */
Duik.Rig.spine = function( layers, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);

    if( layers.isEmpty() ) return [];
    if( layers.length() == 1 ) return [];

    DuScriptUI.progressBar.stg( i18n._("Spine"));
    DuScriptUI.progressBar.hit(1, 'Sorting bones...');

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // Sort

    // a sorter for spine and neck
	function sortBones(a,b)
	{
		return a.i - b.i;
	}

    // expected
    var head = null;
    var hips =  null;
    var spine = [];
    var torso = null;
    var neck = [];
    var tip = null;

    layers.do(function( layer )
    {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );
        var boneIndex = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_INDEX, DuAETag.Type.INT, tag );

        if ( bone == OCO.Bone.HIPS ) hips = layer;
        else if (bone == OCO.Bone.SKULL ) head = layer;
        else if (bone == OCO.Bone.TIP ) tip = layer;
        else if (bone == OCO.Bone.TORSO) torso = layer;
        else if (bone == OCO.Bone.SPINE )
        {
            var b = layer;
            b.i = boneIndex;
            spine.push(b);
        }
        else if (bone == OCO.Bone.NECK )
        {
            var b = layer;
            b.i = boneIndex;
            neck.push(b);
        }

        Duik.Bone.setRigged( layer );
    } );

    spine.sort( sortBones );
    neck.sort( sortBones );

    //find the root
	var spineRoot = null;
	if (hips) spineRoot = hips;
	else if (spine.length > 0) spineRoot = spine[0];
    else if (torso) spineRoot = torso;
	else if (neck.length > 0) spineRoot = neck[0];
	else if (head) spineRoot = head;
	else if (tip) spineRoot = tip;

    // Nothing to do
    if (spineRoot == null) return [];

    // Let's rig!

    DuScriptUI.progressBar.hit(1, 'Creating controllers...');

    // unparent everything, just to be sure
    var spineRootParent = spineRoot.parent;
    spineRoot.parent = null;
    for ( var i = 0, n = spine.length ; i < n; i++ ) spine[i].parent = null;
    if ( torso ) torso.parent = null;
    for ( var i = 0, n = neck.length ; i < n; i++ ) neck[i].parent = null;
    if ( head ) head.parent = null;
    if ( tip ) tip.parent = null;

    // Controllers
    var bodyCtrl = null;
    var hipsCtrl = null;
    var spineCtrl = null;
    var spineCurveCtrl = null;
    var torsoCtrl = null;
    var shoulderCtrl = null;
    var headCtrl = null;

    // Create hips and body controllers
    if (hips)
    {
        bodyCtrl = Duik.Controller.getCreate( hips, Duik.Controller.Type.BODY, customControllers );
        hipsCtrl = Duik.Controller.create(comp, Duik.Controller.Type.HIPS, hips);
        Duik.Layer.setName( i18n._("Hips"), hipsCtrl );
    }
    else if (spine.length > 0) bodyCtrl = Duik.Controller.getCreate( spine[0], Duik.Controller.Type.BODY, customControllers );
    else if (torso) bodyCtrl = Duik.Controller.getCreate( torso, Duik.Controller.Type.BODY, customControllers );
    else if (neck.length > 0) bodyCtrl = Duik.Controller.getCreate( neck[0], Duik.Controller.Type.BODY, customControllers );
    if (bodyCtrl) {
        Duik.Layer.setName( i18n._("Body"), bodyCtrl );
        var peCtrl = Duik.PseudoEffect.CONTROLLER;
        var ctrlEffect = bodyCtrl.effect( peCtrl.matchName );
        if (ctrlEffect) ctrlEffect.property( peCtrl.props['Icon']['Position'].index ).setValue([25, 0]);
    }


    // Spine controller
    if (spine.length > 0)
    {
        spineCtrl = Duik.Controller.getCreate( spine[0], Duik.Controller.Type.VERTEBRAE, customControllers);
        Duik.Layer.setName( i18n._("Spine"), spineCtrl );
    }

    // Torso controller
    if (torso)
    {
        torsoCtrl = Duik.Controller.getCreate( torso, Duik.Controller.Type.TORSO, customControllers);
        Duik.Layer.setName( i18n._("Torso"), torsoCtrl );
    }

    // Shoulders controller
    if (neck.length > 0)
    {
        shoulderCtrl = Duik.Controller.getCreate( neck[0], Duik.Controller.Type.SHOULDERS, customControllers);
        Duik.Layer.setName( i18n._("Shoulders & neck"), shoulderCtrl );
    }
    else if (!head && tip)
    {
        shoulderCtrl = Duik.Controller.getCreate( tip, Duik.Controller.Type.SHOULDERS, customControllers);
    }

    // Head controller
    if (head)
    {
        headCtrl = Duik.Controller.getCreate(head, Duik.Controller.Type.HEAD, customControllers);
        Duik.Layer.setName( i18n._("Head"), headCtrl );
    }

    DuScriptUI.progressBar.hit(1, 'Parenting bones...');

    // Parenting
    // parent bones
    if (hips) hips.parent = hipsCtrl;

    if (tip)
    {
        if (head) tip.parent = head;
        else if (neck.length > 0) tip.parent = neck[neck.length-1];
        else if (torso) tip.parent = torso;
        else if (spine.length > 0) tip.parent = spine[spine.length-1];
        else if (hips) tip.parent = hips;
        else
        {
            hipsCtrl = Duik.Controller.create(comp, Duik.Controller.Type.HIPS, tip);
            tip.parent = hipsCtrl;
        }
    }


    DuScriptUI.progressBar.hit(1, 'Rigging...');

    // hips
    if (hipsCtrl && bodyCtrl) {
        hipsCtrl.parent = bodyCtrl;

    }

    //spine FK
    var goal;
    if (torso) goal = torso;
    else if (neck.length > 0) goal = neck[0];
    else if (head) goal = head;
    else if (tip) goal = tip;
    var ctrl;
    if (torsoCtrl) ctrl = torsoCtrl;
    else if (shoulderCtrl) ctrl = shoulderCtrl
    else if (headCtrl) ctrl = headCtrl;

    if (ctrl || goal)
    {
        if (hips && spine.length == 0)
        {
            var backCtrl = Duik.Constraint.oneLayerIK(hips , goal, ctrl, false);
            if (!ctrl && bodyCtrl) backCtrl.parent = bodyCtrl;
        }
        else if (spine.length == 1)
        {
            var backCtrl = Duik.Constraint.oneLayerIK(spine[0], goal, ctrl, false);
            if (hips) spine[0].parent = hips;
            else spine[0].parent = spineCtrl;
            if (!ctrl && bodyCtrl) backCtrl.parent = bodyCtrl;
        }
        else if (spine.length > 1)
        {
            var ctrls = Duik.Constraint.bezierFK(spine, goal, ctrl, false, spineCtrl);
            if (ctrls.length == 5) {
                ctrls[3].locked = false;
                ctrls[4].locked = false;
                if (hipsCtrl) ctrls[3].parent = hipsCtrl;
                Duik.Layer.setType(Duik.Layer.Type.NULL, ctrls[3]);
                ctrls[3].moveAfter(spineRoot);
                ctrls[4].moveAfter(spineRoot);
                ctrls[3].locked = true;
                ctrls[4].locked = true;
                spineCurveCtrl = ctrls[0];
            }
        }
    }

    // Spine controller
    if (spineCtrl) {
        if (bodyCtrl) spineCtrl.parent = bodyCtrl;
        if (hipsCtrl) DuAEProperty.lock(spineCtrl.transform.position);
    }

    // Torso
    if (torso) {
        var goal;
        if (neck.length > 0) goal = neck[0];
        else if (head) goal = head;
        else if (tip) goal = tip;
        var ctrl;
        if (shoulderCtrl) ctrl = shoulderCtrl;
        else if (headCtrl) ctrl = headCtrl;
        ctrl =  Duik.Constraint.oneLayerIK(torso, goal, ctrl, false);
        // Without spine, we need an orientation constraint on the torso controller (a parent null)
        if (bodyCtrl && hipsCtrl && !spineCtrl) {
            var orientNull = DuAEComp.addNull( comp, undefined, torsoCtrl );
            Duik.Layer.copyAttributes( orientNull, torsoCtrl, Duik.Layer.Type.NULL );
            var orientEffect = Duik.Constraint.orientation( orientNull )[0];
            var pe = Duik.PseudoEffect.ORIENTATION;
            orientEffect( pe.props['Constraint to'].index ).setValue( bodyCtrl.index );
            orientNull.moveBefore( torso );
            
            torsoCtrl.parent = orientNull;
            orientNull.parent = hipsCtrl;

            orientNull.enabled = false;
            orientNull.shy = true;
            orientNull.locked = true;
        }
        else {
            if (spineCtrl) torsoCtrl.parent = spineCtrl;
            else if (hipsCtrl) torsoCtrl.parent = hipsCtrl;
            else if (bodyCtrl) torsoCtrl.parent = bodyCtrl;
        }

        torso.parent = torsoCtrl;
        ctrl.parent = torsoCtrl;
    }


    // Neck IK
    var goal;
    if (head) goal = head;
    else if (tip) goal = tip;
    var ctrl;
    if (headCtrl) ctrl = headCtrl;

    if (ctrl || goal)
    {
        if (neck.length == 1)
        {
            var backCtrl = Duik.Constraint.oneLayerIK(neck[0], goal, ctrl, false);
            neck[0].parent = shoulderCtrl;
            backCtrl.parent = shoulderCtrl;
        }
        else if (neck.length > 1)
        {
            var ctrls = Duik.Constraint.bezierFK(neck, goal, ctrl, false, shoulderCtrl);
            if (ctrls.length == 5) {
                ctrls[3].locked = false;
                ctrls[4].locked = false;
                Duik.Layer.setType(Duik.Layer.Type.NULL, ctrls[3]);
                ctrls[3].moveAfter(neck[0]);
                ctrls[4].moveAfter(neck[0]);
                ctrls[3].locked = true;
                ctrls[4].locked = true;
            }
        }
    }
    if (shoulderCtrl) {
        if (torsoCtrl) shoulderCtrl.parent = torsoCtrl;
        else if (spineCtrl) shoulderCtrl.parent = spineCtrl;
        else if (hipsCtrl)  shoulderCtrl.parent = hipsCtrl;
        else if (bodyCtrl) shoulderCtrl.parent = bodyCtrl;
    }

    //head
    if (head)
    {
        Duik.Constraint.simpleFK(head, headCtrl);
        head.parent = headCtrl;
        if (shoulderCtrl) headCtrl.parent = shoulderCtrl;
        else if (torsoCtrl) headCtrl.parent = torsoCtrl;
        else if (spineCtrl) headCtrl.parent = spineCtrl;
        else if (hipsCtrl)  headCtrl.parent = hipsCtrl;
        else if (bodyCtrl) headCtrl.parent = bodyCtrl;
    }
    
    var ctrls = []
    if ( bodyCtrl ) ctrls.push(bodyCtrl);
    if ( hipsCtrl ) ctrls.push(hipsCtrl);
    if ( spineCtrl ) ctrls.push(spineCtrl);
    if ( spineCurveCtrl ) ctrls.push(spineCurveCtrl);
    if ( torsoCtrl ) ctrls.push(torsoCtrl);
    if ( shoulderCtrl ) ctrls.push(shoulderCtrl);
    if ( headCtrl ) ctrls.push(headCtrl);
    DuAELayer.stack( ctrls );
    return ctrls;
}

/**
 * Rigs a tail.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Duik.Constraint.IKType} [tailMode=Duik.Constraint.IKType.FK] How to rig tails and other chains consisting of more than 3 layers.
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Layer[]} The controller(s) of the tail
 */
Duik.Rig.tail = function ( layers, tailMode, customControllers, isHair )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    isHair = def(isHair, false); // low-level undocumented method: changes the coontrol shape to a hair strand
    tailMode = def(tailMode, Duik.Constraint.IKType.FK);

    DuScriptUI.progressBar.stg( i18n._("Tail"));
    DuScriptUI.progressBar.hit(1, i18n._("Sorting bones..."));

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // expected
    var tail = [];
    var tip = null;

    layers.do(function( layer )
    {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );
        var boneIndex = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_INDEX, DuAETag.Type.INT, tag );

        if ( bone == OCO.Bone.TIP ) tip = layer;
        else
        {
            var b = layer;
            b.i = boneIndex;
            tail.push(b);
        }

        Duik.Bone.setRigged( layer );
    } );

    // Sort
    // a sorter for spine and neck
	function sortBones(a,b)
	{
		return a.i - b.i;
	}

    tail.sort(sortBones);

    DuScriptUI.progressBar.hit(1, 'Creating controllers...');

    //unparent
    for (var i=1, num = tail.length ; i < num ; i++ ) tail[i].parent = null;

    if (!tip && tail.length > 1) tip = tail.pop();
    else if (tail.length == 1)
    {
        var tailCtrl = Duik.Controller.getCreate( tail[0], Duik.Controller.Type.TAIL, customControllers );
        tail[0].parent = tailCtrl;
        return [tailCtrl];
    }

    DuScriptUI.progressBar.hit(1, 'Rigging...');

    var ctrlType = Duik.Controller.Type.TAIL;
    if (isHair) ctrlType = Duik.Controller.Type.PONEYTAIL;

    //ik
    if (tailMode == Duik.Constraint.IKType.BEZIER_IK)
    {
        //controllers
        var tailCtrl = Duik.Controller.getCreate( tip, ctrlType, customControllers);

        if (tail.length > 1)
        {
            var ctrls = Duik.Constraint.bezierIK( tail, tip, tailCtrl, false);
            return ctrls;
        }
        else
        {
            Duik.Constraint.oneLayerIK( tail[0], tip, tailCtrl, false);
            return [tailCtrl];
        }
    }

    //bezier fk
    if (tailMode == Duik.Constraint.IKType.BEZIER_FK)
    {
        if (tail.length > 1)
        {
            var ctrl = Duik.Controller.getCreate( tip, ctrlType, customControllers);
            var ctrl1 = Duik.Controller.getCreate( tail[0], ctrlType, customControllers);
            var ctrls = Duik.Constraint.bezierFK( tail, tip, tailCtrl, false, ctrl1);
            return ctrls;
        }
        else
        {
            var ctrl = Duik.Controller.getCreate( tail[0], ctrlType, customControllers);
            Duik.Constraint.simpleFK( tail, ctrl);
            return [ctrl];
        }
    }

    //fk

    //controllers
    var tailCtrl = Duik.Controller.getCreate( tail[0], ctrlType, customControllers);
    tail.push(tip);

    var tailRoot = tail[0];
    Duik.Constraint.fk( tail.reverse(), tailCtrl);

    return [tailCtrl];
}

/**
 * Rigs a leg.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Layer} The controller leg
 */
Duik.Rig.leg = function ( layers, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    DuScriptUI.progressBar.stg( i18n._("Leg"));
    DuScriptUI.progressBar.hit(1, 'Sorting bones...');

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // expected
    var femur = null;
    var tibia = null;
    var foot = null;
    var toes = null;
    var tip = null;
    var heel = null;

    var side = OCO.Side.NONE;
    var type = OCO.LimbType.CUSTOM;

    // get'em all
    layers.do(function(layer) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );

        if (bone == OCO.Bone.FEMUR) femur = layer;
        else if (bone == OCO.Bone.TIBIA) tibia = layer;
        else if (bone == OCO.Bone.TARSUS) foot = layer;
        else if (bone == OCO.Bone.TOE) toes = layer;
        else if (bone == OCO.Bone.TIP) tip = layer;
        else if (bone == OCO.Bone.HEEL) heel = layer;

        if ( side == OCO.Side.NONE ) side = Duik.Layer.side(layer);
        if ( type == OCO.LimbType.CUSTOM ) type = DuAETag.getValue( layer, DuAETag.Key.DUIK_LIMB_TYPE, DuAETag.Type.STRING, tag );

        Duik.Bone.setRigged( layer );
    });

    //unparent
    if (tibia && femur) tibia.parent = null;
    if (foot && (tibia || femur)) foot.parent = null;
    if (toes  && (foot || tibia || femur)) toes.parent = null;
    if (tip) tip.parent = null;
    if (heel) heel.parent = null;

    //reset transformations
    if (femur) Duik.Bone.resetTransform(femur);
    if (tibia) Duik.Bone.resetTransform(tibia);
    if (foot) Duik.Bone.resetTransform(foot);
    if (toes) Duik.Bone.resetTransform(toes);
    if (tip) Duik.Bone.resetTransform(tip);
    if (heel) Duik.Bone.resetTransform(heel);

    //adjust/fix what we got! We're very friendly...
    /* @ts-ignore */
    if (type == OCO.LimbType.UNGULATE)
    {
        // We need toes (hoof)
        if (!toes)
        {
            if (tip)
            {
                toes = tip;
                tip = null;
            }
            else if (foot)
            {
                toes = foot;
                foot = null;
            }
            else if (tibia)
            {
                toes = tibia;
                tibia = null;
            }
            else if (femur)
            {
                toes = femur;
                femur = null;
            }
        }
        // No foot without both femur and tibia
        if ( (!femur || !tibia) && foot)
        {
            if (femur)
            {
                tibia = foot;
                foot = null;
            }
            else if (tibia)
            {
                femur = tibia;
                tibia = foot;
                foot = null;
            }
            else
            {
                femur = foot;
                foot = null;
            }
        }
        // No tibia without femur
        if ( tibia && !femur )
        {
            femur = tibia;
            tibia = null;
        }
    }

    DuScriptUI.progressBar.hit(1, 'Creating controllers...');

    //add nulls and controllers for the footRoll
    var toesNull, footNull;
    //the foot roll needs all parts
    /* @ts-ignore */
    if ((toes || tip) && foot && tibia && femur && type != OCO.LimbType.UNGULATE)
    {
        if (!toes)
        {
            toes = tip;
            tip = null;
        }

        //claws
        toesNull = DuAEComp.addNull(comp, 20, toes);
        Duik.Layer.copyAttributes( toesNull, toes, Duik.Layer.Type.IK );

        var footSize = toes.transform.position.value[0] - foot.transform.position.value[0];
        //tiptoe
        if (!tip)
        {
            tip = DuAEComp.addNull(comp, 20, toes);
            Duik.Layer.copyAttributes( tip, toes, Duik.Layer.Type.NULL );
            Duik.Layer.setName( Duik.Layer.name(toes) + '_Tip', tip );
            //tip.transform.position.setValue([toesNull.transform.position.value[0] + footSize/2,toesNull.transform.position.value[1]]);

            tip.enabled = false;
            tip.shy = true;
        }

        if (!heel && (type == OCO.LimbType.PLANTIGRADE || type == OCO.LimbType.HOMINOID) )
        {
            heel = DuAEComp.addNull(comp, 20, toes);
            Duik.Layer.copyAttributes( heel, foot, Duik.Layer.Type.NULL );
            Duik.Layer.setName( i18n._("Heel"), heel );
            var footLength = DuAELayer.getDistance( foot, toesNull );
            var tipLocation = DuAELayer.relativeLocation( toesNull, foot );
            if (DuMath.isLocationRight(tipLocation))
                heel.transform.position.setValue([foot.transform.position.value[0] - footLength * .25,toesNull.transform.position.value[1]]);
            else
                heel.transform.position.setValue([foot.transform.position.value[0] + footLength * .25,toesNull.transform.position.value[1]]);

            heel.enabled = false;
            heel.shy = true;
        }

        //foot
        footNull = DuAEComp.addNull(comp, 20, foot);
        Duik.Layer.copyAttributes( footNull, foot, Duik.Layer.Type.IK );
    }

    //Controller for the leg
    var ctrlType = Duik.Controller.Type.FOOT;
    /* @ts-ignore */
    if (type == OCO.LimbType.DIGITIGRADE) ctrlType = Duik.Controller.Type.CLAWS;
    /* @ts-ignore */
    if (type == OCO.LimbType.UNGULATE) ctrlType = Duik.Controller.Type.HOOF;
	
    var ctrl = null;
    /* @ts-ignore */
    if (type == OCO.LimbType.UNGULATE) ctrl = Duik.Controller.getCreate(toes, ctrlType, customControllers);
    /* @ts-ignore */
    else if (type == OCO.LimbType.DIGITIGRADE)
    {
        if (foot && ((femur || tibia) || (!toes && !tip))) ctrl = Duik.Controller.getCreate(toes, ctrlType, customControllers);
        else if (toes && ((femur || tibia) || !tip)) ctrl = Duik.Controller.getCreate(toes, ctrlType, customControllers);
        else if (tip) ctrl = Duik.Controller.getCreate(tip, ctrlType, customControllers);
        else if (heel) ctrl = Duik.Controller.getCreate(heel, ctrlType, customControllers);
        else if (tibia) ctrl = Duik.Controller.getCreate(tibia, ctrlType, customControllers);
        else if (femur) ctrl = Duik.Controller.getCreate(femur, ctrlType, customControllers);
    }
    else
    {
        if (foot && ((femur || tibia) || (!toes && !tip))) ctrl = Duik.Controller.getCreate(foot, ctrlType, customControllers);
        else if (toes && ((femur || tibia) || !tip)) ctrl = Duik.Controller.getCreate(toes, ctrlType, customControllers);
        else if (tip) ctrl = Duik.Controller.getCreate(tip, ctrlType, customControllers);
        else if (heel) ctrl = Duik.Controller.getCreate(heel, ctrlType, customControllers);
        else if (tibia) ctrl = Duik.Controller.getCreate(tibia, ctrlType, customControllers);
        else if (femur) ctrl = Duik.Controller.getCreate(femur, ctrlType, customControllers);
    }

    // Rename controller
    Duik.Layer.setName( i18n._("Leg"), ctrl);

    DuScriptUI.progressBar.hit(1, 'Parenting...');
    
    // parenting
    var spineRoot = null;
    if (toes && !footNull)
    {
        if (foot) toes.parent = foot;
        else if (tibia) toes.parent = tibia;
        else if (femur) toes.parent = femur;
        else if (tip || heel ) toes.parent = spineRoot;
        else
        {
            toes.parent = ctrl;
            ctrl.parent = spineRoot;
        }
    }
    if (foot)
    {
        if (tibia) foot.parent = tibia;
        else if (femur) foot.parent = femur;
        else if (toes || tip || heel ) foot.parent = spineRoot;
        else
        {
            foot.parent = ctrl;
            ctrl.parent = spineRoot;
        }
    }
    if (tibia)
    {
        if (femur) tibia.parent = femur;
        else if (foot || toes || heel) tibia.parent = spineRoot;
        else
        {
            tibia.parent = ctrl;
            ctrl.parent = spineRoot;
        }
    }
    if (femur)
    {
        if (tibia || foot || toes || heel) femur.parent = spineRoot;
        else
        {
            femur.parent = ctrl;
            if (spineRoot) ctrl.parent = spineRoot;
        }
    }
    if (tip)
    {
        if (heel) tip.parent = heel;
        else if (toes) tip.parent = toes;
        else if (foot) tip.parent = foot;
        else if (tibia) tip.parent = tibia;
        else if (femur) tip.parent = femur;
    }
    if (footNull)
    {
        tip.parent = null;
        toes.parent = null;
        toesNull.parent = null;
        footNull.parent = null;
        if(heel) heel.parent = null;
        foot.parent = null;
        toes.parent = tip;
        toesNull.parent = tip;
        footNull.parent = toesNull;
        foot.parent = toesNull;
        if (type == OCO.LimbType.PLANTIGRADE || type == OCO.LimbType.HOMINOID) {
            tip.parent = heel;
            heel.parent = ctrl;
        }
        else if (type == OCO.LimbType.DIGITIGRADE) tip.parent = ctrl;//*/
    }

    // Rig!
    DuScriptUI.progressBar.hit(1, 'Rigging...');

    /* @ts-ignore */
    if (type == OCO.LimbType.UNGULATE)
    {
        if (femur && tibia && foot)
        {
            Duik.Constraint.twoOneLayerIK(femur, tibia, foot, toes, ctrl, false);
            // Rename effects
            var footIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.ONE_LAYER_IK.matchName );
            DuAEProperty.rename( footIK, i18n._("IK") +
                ' | ' + i18n._("Foot"));
            var legIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.TWO_LAYER_IK.matchName );
            DuAEProperty.rename( legIK, i18n._("IK") +
                ' | ' + i18n._("Leg"));
            var hoofAngle = DuAELayer.lastEffect( ctrl, 'ADBE Angle Control' );
            DuAEProperty.rename( hoofAngle, i18n._("Hoof"));
        }
        else if (femur && tibia) Duik.Constraint.twoLayerIK(femur, tibia, toes, ctrl, false);
        else if (femur) Duik.Constraint.oneLayerIK(femur, toes, ctrl, false);
    }
    else if (footNull)
    {
        //leg
        Duik.Constraint.twoLayerIK(femur,tibia,undefined,footNull, false);

        //add an IK effect on the controller
        var pe2 = Duik.PseudoEffect.TWO_LAYER_IK;
        var ikCtrl = pe2.apply(ctrl);
        //the effect on the null of the foot
        var ikEffect = footNull.effect(pe2.matchName);
        ikCtrl.name = ikEffect.name;
        //Set the "side" property and keep its expression
        ikCtrl( pe2.props["Side"].index ).setValue(ikEffect( pe2.props["Side"].index ).value);
        var sideExpression = ikEffect( pe2.props["Side"].index ).expression;
        var ikEffectProp = new DuAEProperty( ikEffect );
        ikEffectProp.linkProperties(ikCtrl,true);
        ikCtrl( pe2.props["Side"].index ).expression = sideExpression;
        //and re-setup the layers & needed data
        ikCtrl( pe2.props["Data"]["Layers"]["Upper"].index ).setValue(ikEffect( pe2.props["Data"]["Layers"]["Upper"].index ).value);
        ikCtrl( pe2.props["Data"]["Layers"]["Lower"].index ).setValue(ikEffect( pe2.props["Data"]["Layers"]["Lower"].index ).value);
        ikCtrl( pe2.props["Data"]["Layers"]["Goal"].index ).setValue(ikEffect( pe2.props["Data"]["Layers"]["Goal"].index ).value);
        var lowerPos = new DuAEProperty( ikCtrl( pe2.props["Data"]["Base values"]["Lower relative position"].index ) );
        lowerPos.pickWhip( ikEffect( pe2.props["Data"]["Base values"]["Lower relative position"].index ));
        var goalPos = new DuAEProperty( ikCtrl( pe2.props["Data"]["Base values"]["Goal relative position"].index ) );
        goalPos.pickWhip( ikEffect( pe2.props["Data"]["Base values"]["Goal relative position"].index ));

        //tiptoe, heel and footroll
        if (type == OCO.LimbType.PLANTIGRADE || type == OCO.LimbType.HOMINOID)
        {
            //detect right or left, depending on the toes position
            var right = false;
            if (toes && foot)
            {
                var toesPos = DuAELayer.getWorldPos(toes);
                var footPos = DuAELayer.getWorldPos(foot);
                right = (toesPos[0] - footPos[0]) > 0;
            }

            var pe = Duik.PseudoEffect.FOOT_ROLL;
            var footCtrl = pe.apply(ctrl);

            // Toes rotation
            toes.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Toes"].index + ").value;";
            // Tiptoe rotation            
            tip.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Tiptoe"].index + ");";
            // Heel rotation
            var op  = right ? "<" : ">";
            heel.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Heel"].index + ");\n" +
                "var roll = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Foot roll"].index + ");\n" +
                "roll " + op + " 0 ? roll+ctrl : ctrl;";
            // Foot roll
            op = right ? ">" : "<";
            toesNull.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Foot roll"].index + ");\n" +
                "ctrl " + op + " 0 ? ctrl : 0;";
        }
        else if (type == OCO.LimbType.DIGITIGRADE)
        {
            var pe = Duik.PseudoEffect.DIGI_FOOT_ROLL;
            var footCtrl = pe.apply(ctrl);
            tip.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(1);";
            toesNull.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(3);\n" +
                "var tiptoe = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(1);\n" +
                "ctrl-tiptoe;";
            // Toes rotation
            toes.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + footCtrl.name + "\")(" + pe.props["Claws"].index + ").value;";
        }

        // hide and lock
        toesNull.enabled = false;
        toesNull.shy = true;
        toesNull.locked = true;
        footNull.enabled = false;
        footNull.shy = true;
        footNull.locked = true;
    }
    else
    {
        if (foot)
        {
            if (femur && tibia) Duik.Constraint.twoLayerIK(femur,tibia,foot,ctrl, false);
            else if (femur) Duik.Constraint.oneLayerIK(femur,foot,ctrl, false);
            else if (tibia) Duik.Constraint.oneLayerIK(tibia,foot,ctrl, false);
            else if (toes) Duik.Constraint.oneLayerIK(foot,toes,ctrl, false);
            else if (tip) Duik.Constraint.oneLayerIK(foot,tip,ctrl, false);
        }
        else if (toes)
        {
            if (femur && tibia) Duik.Constraint.twoLayerIK(femur,tibia,letoes,ctrl, false);
            else if (femur) Duik.Constraint.oneLayerIK(femur,toes,ctrl, false);
            else if (tibia) Duik.Constraint.oneLayerIK(tibia,toes,ctrl, false);
            else if (tip) Duik.Constraint.oneLayerIK(toes,tip,ctrl, false);
        }
        else if (tip)
        {
            if (femur && tibia) Duik.Constraint.twoLayerIK(femur,tibia,tip,ctrl, false);
            else if (femur) Duik.Constraint.oneLayerIK(femur,tip,ctrl, false);
            else if (tibia) Duik.Constraint.oneLayerIK(tibia,tip,ctrl, false);
        }
        else if (heel)
        {
            if (femur && tibia) Duik.Constraint.twoLayerIK(femur,tibia,heel,ctrl, false);
            else if (femur) Duik.Constraint.oneLayerIK(femur,heel,ctrl, false);
            else if (tibia) Duik.Constraint.oneLayerIK(tibia,heel,ctrl, false);
        }
        else if (femur && tibia) Duik.Constraint.oneLayerIK(femur,tibia,ctrl, false);
    }

    return ctrl;
}

/**
 * Rigs a shoulder (an FK and an auto-position effect)
 * @param {Layer} shoulder The shoulder bone
 * @param {Layer} ctrl The controller
 */
Duik.Rig.shoulder = function( shoulder, ctrl )
{
    var rotVal = shoulder.transform.rotation.value;

    Duik.Constraint.oneLayerIK(shoulder, undefined, ctrl, false);
    // Rename effect
    var pe = Duik.PseudoEffect.ONE_LAYER_IK;
    var shoulderIK = DuAELayer.lastEffect( ctrl, pe.matchName );
    DuAEProperty.rename( shoulderIK, i18n._("IK") +
        ' | ' + i18n._("Shoulder"));
    // Adjust values
    shoulderIK( pe.props["Weight"].index ).setValue(20);
    shoulderIK( pe.props["Advanced"]["Parent rotation"].index ).setValue(1);
    shoulderIK( pe.props["FK"].index ).setValue( -shoulder.transform.rotation.value + rotVal*2);

    // Rig position
    var pe = Duik.PseudoEffect.SHOULDER;
    var shoulderCtrl = pe.apply(ctrl);
    // 10 % auto by default
    shoulderCtrl( pe.props["Auto"].index ).setValue(10);

    // Deactivate the arm parent rotation inheritance
    var pe2 = Duik.PseudoEffect.TWO_LAYER_IK;
    var ikEffect = DuAELayer.lastEffect( ctrl, pe2.matchName );
    if(ikEffect) ikEffect( pe2.props["FK"]["Parent rotation"].index).setValue(0);

    // Set position expression
    shoulder.transform.position.expression = DuAEExpression.Id.AUTORIG_SHOULDER + '\n' +
        'var c = thisComp.layer("' + ctrl.name + '");\n' +
        'var fx =  c.effect("' + shoulderCtrl.name + '");\n' +
        'var a = fx(14).value;\n' +
        'if (thisLayer.hasParent) a = thisLayer.parent.fromWorld(a) - thisLayer.parent.fromWorld([0,0]);\n' +
        'var result = value + a;\n' +
        'var cp = c.toWorld(c.anchorPoint);\n' +
        'if (thisLayer.hasParent) cp = thisLayer.parent.fromWorld(cp);\n' +
        'cp0 = c.toWorld(c.anchorPoint,0);\n' +
        'if (thisLayer.hasParent) cp0 = thisLayer.parent.fromWorld(cp0);\n' +
        'cp -= cp0;\n' +
        'result += cp*(fx(9).value/100);\n' +
        'result;';

    Duik.Bone.setRigged( shoulder );
}

/**
 * Returns the bone from the spine bones the closest to the location, where child bones at that location can be attached 
 * @param {float[]} location The location where to attach bones, in comp coordinates
 * @param {Layer[]} spineBones The bones of the spine, sorted from root (hips) to tip
 * @returns {Layer|null} The corresponding spine bone or null if the list of spine bones is empty
 */
Duik.Rig.getSpineAttach = function ( location, spineBones)
{
    spineAttach = null;

    if (spineBones.length == 0) return spineAttach;
    if (spineBones.length == 1) return spineBones[0];

    // The bone needs to be the one just before, no matter the orientation: check the distance between hips & shoulder
    // on the furthest axis
    var rootPos = DuAELayer.getWorldPos( spineBones[0] );
    var endPos = DuAELayer.getWorldPos( spineBones[spineBones.length-1] );
    var x = endPos[0] - rootPos[0];
    var y = endPos[1] - rootPos[1];
    var axis = 1;
    var sign = DuMath.sign( y );
    if ( Math.abs( x ) > Math.abs( y ) )
    {
        axis = 0;
        sign = DuMath.sign( x );
    }

    for (var i = 0, n = spineBones.length; i < n; i++)
    {
        var b = spineBones[i];
        var bPos = DuAELayer.getWorldPos( b );
        var l = location[axis] - bPos[axis];
        if (l == 0) return b;
        var s = DuMath.sign(l);
        // too far, we're ready
        if ( s != sign && i == 0 ) return b;
        if ( s != sign ) return spineAttach;
        spineAttach = b;
    }

    return spineAttach;

}

/**
 * Rigs an arm/front leg.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Layer} The controller of the arm
 */
Duik.Rig.arm = function ( layers, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    DuScriptUI.progressBar.stg( i18n._("Arm"));
    DuScriptUI.progressBar.hit(1, 'Sorting bones...');

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // expected
    var shoulder = null;
    var humerus = null;
    var radius = null;
    var hand = null;
    var claws = null;
    var tip = null;
    var palm = null;

    var side = OCO.Side.NONE;
    var type = OCO.LimbType.CUSTOM;

    // get'em all
    layers.do(function(layer) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );

        if (bone == OCO.Bone.CLAVICLE) shoulder = layer;
        else if (bone == OCO.Bone.HUMERUS) humerus = layer;
        else if (bone == OCO.Bone.RADIUS) radius = layer;
        else if (bone == OCO.Bone.CARPUS) hand = layer;
        else if (bone == OCO.Bone.FINGER) claws = layer;
        else if (bone == OCO.Bone.TIP) tip = layer;
        else if (bone == OCO.Bone.HEEL) palm = layer;

        if ( side == OCO.Side.NONE ) side = Duik.Layer.side(layer);
        if ( type == OCO.LimbType.CUSTOM ) type = DuAETag.getValue( layer, DuAETag.Key.DUIK_LIMB_TYPE, DuAETag.Type.STRING, tag );

        Duik.Bone.setRigged( layer );
    });

    //unparent
    if (humerus && shoulder) humerus.parent = null;
    if (radius && (humerus || shoulder)) radius.parent = null;
    if (hand && (radius || humerus)) hand.parent = null;
    if (claws  && (hand || radius || humerus)) claws.parent = null;
    if (tip) tip.parent = null;
    if (palm) palm.parent = null;

    //reset transformations
    if (humerus) Duik.Bone.resetTransform(humerus);
    if (shoulder) Duik.Bone.resetTransform(shoulder);
    if (radius) Duik.Bone.resetTransform(radius);
    if (hand) Duik.Bone.resetTransform(hand);
    if (claws) Duik.Bone.resetTransform(claws);
    if (tip) Duik.Bone.resetTransform(tip);
    if (palm) Duik.Bone.resetTransform(palm);

    //adjust/fix what we got! We're very friendly...
    // No shoulder without both humerus and radius
    if ( shoulder && (!humerus || !radius) )
    {
        if (humerus)
        {
            radius = humerus;
            humerus = shoulder;
            shoulder = null;
        }
        else if (radius)
        {
            humerus = shoulder;
            shoulder = null;
        }
        else
        {
            humerus = shoulder;
            shoulder = null;
        }
    }
    // Ungulate adjustments
    if (type == OCO.LimbType.UNGULATE || type == OCO.LimbType.ARTHROPOD)
    {
        // We need claws (hoof)
        if (!claws)
        {
            if (tip)
            {
                claws = tip;
                tip = null;
            }
            else if (hand)
            {
                claws = hand;
                hand = null;
            }
            else if (radius)
            {
                claws = radius;
                radius = null;
            }
            else if (humerus)
            {
                claws = humerus;
                humerus = null;
            }
            else if (shoulder)
            {
                claws = shoulder;
                shoulder = null;
            }
        }
        // No hand without both humerus and radius
        if ( hand && (!humerus || !radius) )
        {
            if ( humerus )
            {
                radius = hand;
                hand = null;
            }
            else if ( radius )
            {
                humerus = radius;
                radius = hand;
                hand = null;
            }
            else
            {
                humerus = hand;
                hand = null;
            }
        }
        // No radius without humerus
        if ( radius && !humerus )
        {
            humerus = radius;
            radius = null;
        }
    }

    DuScriptUI.progressBar.hit(1, 'Creating controllers...');

    //add nulls and controllers for the footRoll
    var clawsNull, handNull;
    //the foot roll needs all parts
    if ( (claws || tip) && hand && ((radius && humerus) || (radius && shoulder) || (humerus && shoulder)) && type != OCO.LimbType.UNGULATE && type != OCO.LimbType.ARTHROPOD && type != OCO.LimbType.HOMINOID)
    {
        if (!claws)
        {
            claws = tip;
            tip = null;
        }
        //claws
        clawsNull = DuAEComp.addNull(comp, 20, claws);
        Duik.Layer.copyAttributes( clawsNull, claws, Duik.Layer.Type.IK );

        var handSize = claws.transform.position.value[0] - hand.transform.position.value[0];
        //tiptoe
        if (!tip)
        {
            tip = DuAEComp.addNull(comp, 20, claws);
            Duik.Layer.copyAttributes( tip, claws, Duik.Layer.Type.NULL );
            Duik.Layer.setName( Duik.Layer.name(claws) + '_Tip', tip );
            tip.transform.position.setValue([clawsNull.transform.position.value[0] + handSize/2,clawsNull.transform.position.value[1]]);
        }

        if (!palm && type == OCO.LimbType.PLANTIGRADE)
        {
            palm = DuAEComp.addNull(comp, 20, claws);
            Duik.Layer.copyAttributes( palm, hand, Duik.Layer.Type.NULL );
            Duik.Layer.setName( i18n._("Heel"), palm );
            palm.transform.position.setValue([hand.transform.position.value[0],clawsNull.transform.position.value[1]]);
        }

        //hand
        handNull = DuAEComp.addNull(comp, 20, hand);
        Duik.Layer.copyAttributes( handNull, hand, Duik.Layer.Type.IK );
    }

    //Controller for the arm
    var ctrlType = Duik.Controller.Type.HAND;
    if (handNull && type == OCO.LimbType.PLANTIGRADE) ctrlType = Duik.Controller.Type.FOOT;
    else if (type == OCO.LimbType.DIGITIGRADE) ctrlType = Duik.Controller.Type.CLAWS;
    else if (type == OCO.LimbType.UNGULATE) ctrlType = Duik.Controller.Type.HOOF;
    else if (type == OCO.LimbType.ARTHROPOD) ctrlType = Duik.Controller.Type.PINCER;

    var ctrl = null;
    if (type == OCO.LimbType.UNGULATE || type == OCO.LimbType.ARTHROPOD) ctrl = Duik.Controller.getCreate(claws, ctrlType, customControllers);
    else if (type == OCO.LimbType.DIGITIGRADE)
    {
        if (hand && ((humerus || radius || shoulder) || (!claws && !tip))) {
            ctrl = Duik.Controller.getCreate(claws, ctrlType, customControllers);
        }
        else if (claws && ((humerus || radius || shoulder) || !tip)) {
            ctrl = Duik.Controller.getCreate(claws, ctrlType, customControllers);
        }
        else if (tip) {
            ctrl = Duik.Controller.getCreate(tip, ctrlType, customControllers);
        }
        else if (palm) {
            ctrl = Duik.Controller.getCreate(palm, ctrlType, customControllers);
        }
        else if (radius) {
            ctrl = Duik.Controller.getCreate(radius, ctrlType, customControllers);
        }
        else if (humerus) {
            ctrl = Duik.Controller.getCreate(humerus, ctrlType, customControllers);
        }
        else if (shoulder) {
            ctrl = Duik.Controller.getCreate(shoulder, ctrlType, customControllers);
        }
    }
    else {
        if (hand && ((humerus || radius || shoulder) || (!claws && !tip))) {
            ctrl = Duik.Controller.getCreate(hand, ctrlType, customControllers);
        }
        else if (claws && ((humerus || radius || shoulder) || !tip)) {
            ctrl = Duik.Controller.getCreate(claws, ctrlType, customControllers);
        }
        else if (tip) {
            ctrl = Duik.Controller.getCreate(tip, ctrlType, customControllers);
        }
        else if (palm) {
            ctrl = Duik.Controller.getCreate(palm, ctrlType, customControllers);
        }
        else if (radius) {
            ctrl = Duik.Controller.getCreate(radius, ctrlType, customControllers);
        }
        else if (humerus) {
            ctrl = Duik.Controller.getCreate(humerus, ctrlType, customControllers);
        }
        else if (shoulder) {
            ctrl = Duik.Controller.getCreate(shoulder, ctrlType, customControllers);
        }
    }

    // Rename controller
    if(type == OCO.LimbType.HOMINOID) Duik.Layer.setName( i18n._("Arm"), ctrl);
    else Duik.Layer.setName( i18n._("Front leg"), ctrl);

    DuScriptUI.progressBar.hit(1, 'Parenting...');
    
    // Find the torso for parenting (the closest bone before the shoulder)
    var shoulderPos;
    if (shoulder) shoulderPos = DuAELayer.getWorldPos(shoulder);
    else if (humerus) shoulderPos = DuAELayer.getWorldPos(humerus);
    else if (radius) shoulderPos = DuAELayer.getWorldPos(radius);
    else if (hand) shoulderPos = DuAELayer.getWorldPos(hand);
    else if (claws) shoulderPos = DuAELayer.getWorldPos(claws);
    else if (tip) shoulderPos = DuAELayer.getWorldPos(tip);
    else if (palm) shoulderPos = DuAELayer.getWorldPos(palm);

    var spineTorso = null;

    //parenting
    if (claws)
    {
        if (hand) claws.parent = hand;
        else if (radius) claws.parent = radius;
        else if (humerus) claws.parent = humerus;
        else if (shoulder) claws.parent = shoulder;
        else if (tip || palm) claws.parent = spineTorso;
        else
        {
            claws.parent = ctrl;
            ctrl.parent = spineTorso;
        }
    }
    if (hand)
    {
        if (radius) hand.parent = radius;
        else if (humerus) hand.parent = humerus;
        else if (shoulder) hand.parent = shoulder;
        else if (claws || tip || palm) hand.parent = spineTorso;
        else
        {
            hand.parent = ctrl;
            ctrl.parent = spineTorso;
        }
    }
    if (radius)
    {
        if (humerus) radius.parent = humerus;
        else if (shoulder) radius.parent = shoulder;
        else if (hand || claws || tip || palm) radius.parent = spineTorso;
        else
        {
            radius.parent = ctrl;
            ctrl.parent = spineTorso;
        }
    }
    if (humerus)
    {
        if (shoulder) humerus.parent = shoulder;
        else if (radius || hand || claws || palm || tip) humerus.parent = spineTorso;
        else
        {
            humerus.parent = ctrl;
            if (spineTorso) ctrl.parent = spineTorso;
        }
    }
    if (shoulder)
    {
        if (humerus || radius || hand || claws || palm  || tip) shoulder.parent = spineTorso;
        else
        {
            shoulder.parent = ctrl;
            if (spineTorso) ctrl.parent = spineTorso;
        }
    }
    if (tip)
    {
        if (palm) tip.parent = palm;
        else if (claws) tip.parent = claws;
        else if (hand) tip.parent = hand;
        else if (radius) tip.parent = radius;
        else if (humerus) tip.parent = humerus;
        else if (shoulder) tip.parent = shoulder;
    }
    if (handNull)
    {
        handNull.parent = clawsNull;
        clawsNull.parent = tip;
        if (type == OCO.LimbType.PLANTIGRADE) palm.parent = ctrl;
        else if(type == OCO.LimbType.DIGITIGRADE) tip.parent = ctrl;
    }

    // Rig!
    DuScriptUI.progressBar.hit(1, 'Rigging...');

    if (type == OCO.LimbType.UNGULATE || type == OCO.LimbType.ARTHROPOD)
    {
        if (humerus && radius && hand)
        {
            Duik.Constraint.twoOneLayerIK(humerus, radius, hand, claws, ctrl, false);
            // Rename effects
            var footIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.ONE_LAYER_IK.matchName );
            DuAEProperty.rename( footIK, i18n._("IK") +
                ' | ' + i18n._("Foot"));
            var legIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.TWO_LAYER_IK.matchName );
            DuAEProperty.rename( legIK, i18n._("IK") +
                ' | ' + i18n._("Leg"));
            var hoofAngle = DuAELayer.lastEffect( ctrl, 'ADBE Angle Control' );
            DuAEProperty.rename( hoofAngle, i18n._("Hoof"));
        }
        else if (femur && tibia)
        {
            Duik.Constraint.twoLayerIK(femur, tibia, toes, ctrl, false);
            // Rename effects
            var legIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.TWO_LAYER_IK.matchName );
            DuAEProperty.rename( legIK, i18n._("IK") +
                ' | ' + i18n._("Leg"));
        }
        else if (femur)
        {
            Duik.Constraint.oneLayerIK(femur, toes, ctrl, false);
            // Rename effects
            var legIK = DuAELayer.lastEffect( ctrl, Duik.PseudoEffect.ONE_LAYER_IK.matchName );
            DuAEProperty.rename( legIK, i18n._("IK") +
                ' | ' + i18n._("Leg"));
        }
    }
    else if (handNull)
    {
        //claws
        Duik.Constraint.oneLayerIK( claws, undefined, tip, false);
        //arm
        if (humerus && radius) Duik.Constraint.twoLayerIK(humerus,radius,hand,handNull, false);
        //hand
        Duik.Constraint.oneLayerIK(hand, undefined, clawsNull, false);

        var pe2 = Duik.PseudoEffect.TWO_LAYER_IK;
        var pe1 = Duik.PseudoEffect.ONE_LAYER_IK;

        //add an IK effect on the controller
        var ikCtrl = pe2.apply(ctrl);

        //the effect on the null of the hand
        var ikEffect = handNull.effect( pe2.matchName);
        var ikHand = clawsNull.effect(pe1.matchName);
        var ikToes = tip.effect(pe1.matchName);
        ikCtrl.name = ikEffect.name;

        //link the properties
        ikCtrl( pe2.props["Side"].index ).setValue( ikEffect( pe2.props["Side"].index ).value );
        var ikEffectProp = new DuAEProperty( ikEffect );
        ikEffectProp.linkProperties(ikCtrl);

        //the IK/FK Switches
        var ikHandProp = new DuAEProperty( ikHand(pe1.props["IK"].index ) );
        var ikGoalProp = new DuAEProperty( ikCtrl(pe2.props["FK"]["End"].index ) );
        var ikToesProp = new DuAEProperty( ikToes(pe1.props["IK"].index) );
        ikHandProp.linkProperties( ikCtrl(pe2.props["IK / FK"].index),true);
        var fkExp = 'if (effect("' + ikHand.name + '")(' + pe1.props["IK"].index + ').value) value;\n';
        fkExp += 'else ';
        fkExp += ikGoalProp.expressionLink(true);
        fkExp += ';';
        ikHand( pe1.props["FK"].index ).expression = fkExp;
        ikToesProp.linkProperties( ikCtrl(pe2.props["IK / FK"].index), true );
        //and re-setup the layers & needed data
        ikCtrl( pe2.props["Data"]["Layers"]["Upper"].index ).setValue( ikEffect( pe2.props["Data"]["Layers"]["Upper"].index ).value );
        ikCtrl( pe2.props["Data"]["Layers"]["Lower"].index ).setValue(ikEffect( pe2.props["Data"]["Layers"]["Lower"].index ).value);
        ikCtrl( pe2.props["Data"]["Layers"]["Goal"].index ).setValue(ikEffect( pe2.props["Data"]["Layers"]["Goal"].index ).value);
        var lowerPosProp = new DuAEProperty( ikCtrl( pe2.props["Data"]["Base values"]["Lower relative position"].index  ) );
        var goalPosProp = new DuAEProperty( ikCtrl( pe2.props["Data"]["Base values"]["Goal relative position"].index  ) );  
        lowerPosProp.pickWhip(ikEffect(pe2.props["Data"]["Base values"]["Lower relative position"].index));
        goalPosProp.pickWhip(ikEffect(pe2.props["Data"]["Base values"]["Goal relative position"].index));

        //tiptoe, heel and footroll
        if (type == OCO.LimbType.PLANTIGRADE)
        {
            //detect right or left, depending on the toes position
            var right = false;
            if (claws && hand)
            {
                var clawsPos = DuAELayer.getWorldPos(claws);
                var handPos = DuAELayer.getWorldPos(hand);
                right = (clawsPos[0] - handPos[0]) > 0;
            }
            
            var peFR = Duik.PseudoEffect.FOOT_ROLL;
            var handCtrl = peFR.apply(ctrl);
            tip.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(" + peFR.props["Tiptoe"].index + ");";
            var op  = right ? "<" : ">";
            palm.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(" + peFR.props["Heel"].index + ");\n" +
                "var roll = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(" + peFR.props["Foot roll"].index + ");\n" +
                "roll " + op + " 0 ? roll+ctrl : ctrl;";
            op = right ? ">" : "<";
            clawsNull.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(" + peFR.props["Foot roll"].index + ");\n" +
                "ctrl " + op + " 0 ? ctrl : 0;";
            var ikToesEffect = tip.effect(pe1.matchName);
            ikToesEffect( pe1.props["FK"].index ).expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(" + peFR.props["Toes"].index + ");";
        }
        else if (type == OCO.LimbType.DIGITIGRADE)
        {
            var pe = Duik.PseudoEffect.DIGI_FOOT_ROLL;
            var handCtrl = pe.apply(ctrl);
            tip.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(1);";
            clawsNull.transform.rotation.expression = DuAEExpression.Id.FOOT_ROLL + "\n" +
                "var ctrl = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(3);\n" +
                "var tiptoe = thisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(1);\n" +
                "ctrl-tiptoe;";
            tip.effect(pe1.matchName)( pe1.props["FK"].index ).expression = DuAEExpression.Id.FOOT_ROLL + "\nthisComp.layer(\"" + ctrl.name + "\").effect(\"" + handCtrl.name + "\")(2);";
        }

        //hide and lock
        clawsNull.enabled = false;
        clawsNull.shy = true;
        clawsNull.locked = true;
        handNull.enabled = false;
        handNull.shy = true;
        handNull.locked = true;
    }
    else
    {
        if (hand)
        {
            if (humerus && radius) Duik.Constraint.twoLayerIK(humerus,radius,hand,ctrl, false);
            else if (humerus) Duik.Constraint.oneLayerIK(humerus,hand,ctrl, false);
            else if (radius) Duik.Constraint.oneLayerIK(radius,hand,ctrl, false);
            else if (claws) Duik.Constraint.oneLayerIK(hand,claws,ctrl, false);
            else if (tip) Duik.Constraint.oneLayerIK(hand,tip,ctrl, false);
        }
        else if (claws)
        {
            if (humerus && radius) Duik.Constraint.twoLayerIK(humerus,radius,claws,ctrl, false);
            else if (humerus) Duik.Constraint.oneLayerIK(humerus,claws,ctrl, false);
            else if (radius) Duik.Constraint.oneLayerIK(radius,claws,ctrl, false);
            else if (tip) Duik.Constraint.oneLayerIK(claws,tip,ctrl, false);
        }
        else if (tip)
        {
            if (humerus && radius) Duik.Constraint.twoLayerIK(humerus,radius,tip,ctrl, false);
            else if (humerus) Duik.Constraint.oneLayerIK(humerus,tip,ctrl, false);
            else if (radius) Duik.Constraint.oneLayerIK(radius,tip,ctrl, false);
        }
        else if (palm)
        {
            if (humerus && radius) Duik.Constraint.twoLayerIK(humerus,radius,palm,ctrl, false);
            else if (humerus) Duik.Constraint.oneLayerIK(humerus,palm,ctrl, false);
            else if (radius) Duik.Constraint.oneLayerIK(radius,palm,ctrl, false);
        }
        else if (humerus && radius) Duik.Constraint.oneLayerIK(humerus,radius,ctrl, false);
    }

    // Rig shoulder
    if (shoulder)
    {
        Duik.Rig.shoulder(shoulder, ctrl);
        // If hominoid, no auto-position
        if (type == OCO.LimbType.HOMINOID)
        {
            var pe = Duik.PseudoEffect.SHOULDER;
            var shoulderCtrl = DuAELayer.lastEffect( ctrl, pe.matchName );
            shoulderCtrl( pe.props["Auto"].index ).setValue(0);
        }
    }

    return ctrl;
}

/**
 * Rigs a fin.
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Layer} The controller of the fin
 */
Duik.Rig.fin = function( layers, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    DuScriptUI.progressBar.stg( i18n._("Fin"));
    DuScriptUI.progressBar.hit(1, i18n._("Sorting bones..."));

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // expected
    var arm = null;
    var fins = [];

    var side = OCO.Side.NONE;
    var type = OCO.LimbType.CUSTOM;

    // get'em all
    layers.do(function(layer) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );

        if (bone == OCO.Bone.FIN) arm = layer;
        else if (bone == OCO.Bone.FIN_FISHBONE) fins.push( layer );

        if ( side == OCO.Side.NONE ) side = Duik.Layer.side(layer);
        if ( type == OCO.LimbType.CUSTOM ) type = DuAETag.getValue( layer, DuAETag.Key.DUIK_LIMB_TYPE, DuAETag.Type.STRING, tag );

        Duik.Bone.setRigged( layer );
    });

    var nfins = fins.length;

    // unparent & reset transform
    if (arm)
    {
        arm.parent = null;
        Duik.Bone.resetTransform(arm);
    }
    for (var i = 0; i < nfins; i++)
    {
        var f = fins[i];
        f.parent = null;
        Duik.Bone.resetTransform(f);
    }

    // adjust/fix what we got! We're very friendly...
    // we need an arm
    if (!arm)
    {
        if (fins.length == 1) arm = fins.pop();
        else if (fins.length > 0)
        {
            // Create a null at the average position
            var pos = [0,0];
            for(var i = 0; i<nfins; i++)
            {
                // they've been unparented, just take the position
                pos += fins[i].transform.position;
            }
            pos /= nfins;
            arm = DuAEComp.addNull(comp, 20);
            arm.transform.position.setValue( pos );
            Duik.Layer.copyAttributes( arm, fins[0], Duik.Layer.Type.NULL );
            Duik.Layer.setName( i18n._("Fin"), arm );
        }
    }

    DuScriptUI.progressBar.hit(1, i18n._("Creating controllers"));

    var fkNull = DuAEComp.addNull(comp, 20, arm);
    Duik.Layer.copyAttributes( fkNull, arm, Duik.Layer.Type.NULL );
    var ctrl = Duik.Controller.getCreate(arm, Duik.Controller.Type.FIN, customControllers);

    DuScriptUI.progressBar.hit(1, i18n._("Parenting..."));

    // We also need to get the max distance between a fin and the arm
    var maxFinDistance = 0;
    for(var i = 0; i<nfins; i++)
    {
        var f = fins[i];
        f.parent = arm;
        var d = DuMath.length( [0,0], f.transform.position.value );
        if (d > maxFinDistance) maxFinDistance = d;
    }

    // arm's been unparented, just use the position
    var spineAttach = null;
    arm.parent = ctrl;
    ctrl.parent = spineAttach;
    fkNull.parent = ctrl;

    // Rig!
    DuScriptUI.progressBar.hit(1, 'Rigging...');

    // Add control
    var pe = Duik.PseudoEffect.FIN;
    var ctrlEffect = pe.apply( ctrl );
    var ctrlInfo = new DuAEProperty( ctrlEffect );
    ctrlEffect.name = i18n._("Fin");

    // FK Control for each fin
    var peFK = Duik.PseudoEffect.FK;

    for(var i = 0; i<nfins; i++)
    {
        var f = fins[i];
        Duik.Constraint.fk( [arm, f], fkNull );

        // Remove arm ctrl duplicate
        if (i != nfins-1)
        {
            var armEffect = DuAELayer.lastEffect( fkNull, 'ADBE Angle Control', 1);
            if (armEffect) armEffect.remove();
        }

        // Copy fishbone control
        var boneEffect = DuAELayer.lastEffect( fkNull, 'ADBE Angle Control');
        if (boneEffect)
        {
            var boneCtrl = ctrl('ADBE Effect Parade').addProperty('ADBE Angle Control');
            boneCtrl.name = boneEffect.name;
            // link
            boneEffect(1).expression = [ DuAEExpression.Id.AUTORIG_FIN,
                'thisComp.layer("' + ctrl.name + '").effect("' + boneCtrl.name + '")(1).value;'
            ].join('\n');

            // fix invalid object (another AE workaround)
            ctrlEffect = ctrlInfo.getProperty();
        }

        // Link Resistance
        var fkEffect = DuAELayer.lastEffect( fkNull, peFK.matchName );
        fkEffect( peFK.props["Resistance"].index ).expression = [ DuAEExpression.Id.AUTORIG_FIN,
            'var fx = thisComp.layer("' + ctrl.name + '").effect("' + ctrlEffect.name + '");',
            'var result = fx(' + pe.props["Overlap"]["Resistance"].index + ').value;',
            'var rdm = fx(' + pe.props["Overlap"]["Randomness"].index + ').value;',
            'seedRandom(0, true);',
            DuAEExpression.Library.get(['addNoise']),
            'result = addNoise( result, rdm );',
            'result;'
        ].join('\n');

        // need the layer position for the ratio
        var lpos = f.transform.position.value;

        // Link Curve
        fkEffect( peFK.props["Curve"].index ).expression = [ DuAEExpression.Id.AUTORIG_FIN,
            'var fx = thisComp.layer("' + ctrl.name + '").effect("' + ctrlEffect.name + '");',
            'var curve = fx(' + pe.props["Curve"].index + ').value;',
            'var maxDistance = ' + maxFinDistance + ';',
            'var layerPos = ' + lpos.toSource() + ';',
            'var d = length( [0,0], layerPos);',
            'linear(d, 0, maxDistance, curve*.2, curve);'
        ].join('\n');

        // Link Flexibility
        fkEffect( peFK.props["Flexibility"].index ).expression = [ DuAEExpression.Id.AUTORIG_FIN,
            'var fx = thisComp.layer("' + ctrl.name + '").effect("' + ctrlEffect.name + '");',
            'var flexMax = fx(' + pe.props["Overlap"]["Max. flexibility"].index + ').value;',
            'var flexMin = fx(' + pe.props["Overlap"]["Min. flexibility"].index + ').value;',
            'var rdm = fx(' + pe.props["Overlap"]["Randomness"].index + ').value;',
            'var maxDistance = ' + maxFinDistance + ';',
            'var layerPos = ' + lpos.toSource() + ';',
            'var d = length( [0,0], layerPos);',
            'seedRandom(0, true);',
            DuAEExpression.Library.get(['addNoise']),
            'var result = linear(d, 0, maxDistance, flexMin, flexMax);',
            'result = addNoise( result, rdm );',
            'result;'
        ].join('\n');
    }

    // Link rotation
    var fkRot = new DuAEProperty( fkNull.transform.rotation );
    fkRot.pickWhip( ctrl.transform.rotation );

    return ctrl;
}

/**
 * Rigs the spine of a fish (head + tail).
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Duik.Constraint.IKType} [rigMode=Duik.Constraint.IKType.FK] How to rig tails and other chains consisting of more than 3 layers.
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @returns {Object} An object with two Arrays: bones and controllers.
 */
Duik.Rig.fishSpine = function( layers, rigMode, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];
    fishIK = rigMode != Duik.Constraint.IKType.FK;

    var fs = {};
    fs.bones = [];
    fs.controllers = [];

    DuScriptUI.progressBar.stg( i18n._("Fish spine"));
    DuScriptUI.progressBar.hit(1, 'Sorting bones...');

    customControllers = new DuList(customControllers);

    var comp = layers.first().containingComp;

    // expected
    var head = null;
    var spine = [];
    var tip = null;
    var headTip = null;

    // get'em all
    layers.do(function(layer) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );
        var boneIndex = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_INDEX, DuAETag.Type.INT, tag );

        if (bone == OCO.Bone.SKULL) head = layer;
        else if (bone == OCO.Bone.SKULL_TIP) headTip = layer;
        else if (bone == OCO.Bone.TIP) tip = layer;
        else
        {
            var b = layer;
            b.i = boneIndex;
            spine.push(b);
        }

        Duik.Bone.setRigged( layer );
    });

    // Sort
    // a sorter for spine and neck
	function sortBones(a,b)
	{
		return a.i - b.i;
	}

    spine.sort(sortBones);

    DuScriptUI.progressBar.hit(1, 'Creating controllers...');

    //unparent & reset transform
    for (var i=0, num = spine.length ; i < num ; i++ )
    {
        var s = spine[i];
        s.parent = null;
        Duik.Bone.resetTransform(s);
    }
    if (head)
    {
        head.parent = null;
        Duik.Bone.resetTransform(head);
    }
    if (tip)
    {
        tip.parent = null;
        Duik.Bone.resetTransform(tip);
    }
    if (headTip)
    {
        headTip.parent = null;
        Duik.Bone.resetTransform(headTip);
    }

    // adjust/fix what we got! We're very friendly...
    // we need a head
    if(!head)
    {
        if (spine.length > 0)
        {
            head = DuAEComp.addNull( comp, 20, spine[0] );
            Duik.Layer.copyAttributes( head, spine[0], duik.Layer.Type.NULL );
            Duik.Layer.setName( i18n._("Head"), head );
        }
        else return fs;
    }
    // spine
    if(spine.length == 0 && tip)
    {
        spine = [tip];
        tip = null;
    }

    if (spine.length == 0)
    {
        var ctrl = Duik.Controller.getCreate(head, Duik.Controller.Type.HEAD, customControllers );
        head.parent = ctrl;
        if(headTip) headTip.parent = head;
        return fs;
    }

    var bodyCtrl = Duik.Controller.getCreate(spine[0], Duik.Controller.Type.HIPS, customControllers );
    var headCtrl = Duik.Controller.getCreate(head, Duik.Controller.Type.HEAD, customControllers );

    DuScriptUI.progressBar.hit(1, 'Parenting...');

    headCtrl.parent = bodyCtrl;

    head.parent = spine[0];
    if (headTip) headTip.parent = head;

    spine[0].parent = bodyCtrl;
    for (var i = 1, n = spine.length; i < n; i++)
    {
        spine[i].parent = spine[i-1];
    }
    if( tip ) tip.parent = spine[spine.length-1];

    DuScriptUI.progressBar.hit(1, 'Rigging...');

    // Head FK
    Duik.Constraint.simpleFK( head, headCtrl );

    // Single layer tail
    if (spine.length == 1)
    {
        spine[0].parent = bodyCtrl;
        fs.bones = spine;
        fs.controllers = bodyCtrl;
        return fs;
    }

    // Tail IK
    if (fishIK)
    {
        // we need a tip
        if (!tip) tip = spine.pop();

        var tailCtrl = Duik.Controller.getCreate( tip, Duik.Controller.Type.TAIL, customControllers);

        if (spine.length > 1)
        {
            var ctrls = Duik.Constraint.bezierIK( spine, tip, tailCtrl, false);
            //parent
            ctrls[0].parent = bodyCtrl;
            ctrls[1].parent = bodyCtrl;
            spine[0].parent = bodyCtrl;
            fs.controllers = ctrls;
        }
        else
        {
            Duik.Constraint.oneLayerIK( spine[0], tip, tailCtrl, false);
            //parent
            tailCtrl.parent = bodyCtrl;
            spine[0].parent = bodyCtrl;
        }
        fs.bones = spine;
        fs.controllers.push(tailCtrl);
        return fs;
    }

    // Tail FK
    spine.push(tip);

    var reversedSpine = [];
    for (var i = spine.length -1; i >= 0; i--) reversedSpine.push(spine[i] );

    Duik.Constraint.fk( reversedSpine, bodyCtrl );
    //parent
    spine[0].parent = bodyCtrl;
    // disable parent rotation inheritance
    var pe = Duik.PseudoEffect.FK;
    bodyCtrl.effect( pe.matchName )( pe.props["Parent rotation"].index).setValue(0);

    fs.bones = spine;
    fs.controllers.push(bodyCtrl);
    return fs;
}

/**
 * Rigs a wing with feathers
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @return {Layer} The controller of the wing
 */
Duik.Rig.wing = function( layers, customControllers )
{
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    customControllers = new DuList(customControllers);

    DuScriptUI.progressBar.stg( i18n._("Wing"));
    DuScriptUI.progressBar.hit(1, i18n._("Sorting bones..."));

    var comp = layers.first().containingComp;

    // expected
    var arm = null;
    var forearm = null;
    var hand = null;
    var handTip = null;
    var feathers = [];

    var side = OCO.Side.NONE;
    var type = OCO.LimbType.CUSTOM;

    // get'em all
    layers.do(function(layer) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );

        if (bone == OCO.Bone.HUMERUS) arm = layer;
        else if (bone == OCO.Bone.RADIUS) forearm = layer;
        else if (bone == OCO.Bone.CARPUS) hand = layer;
        else if (bone == OCO.Bone.FEATHER) feathers.push( layer );

        if ( side == OCO.Side.NONE ) side = Duik.Layer.side(layer);
        if ( type == OCO.LimbType.CUSTOM ) type = DuAETag.getValue( layer, DuAETag.Key.DUIK_LIMB_TYPE, DuAETag.Type.STRING, tag );

        Duik.Bone.setRigged( layer );
    });

    // unparent & reset transform
    if (arm)
    {
        arm.parent = null;
        Duik.Bone.resetTransform(arm);
    }
    if (forearm)
    {
        forearm.parent = null;
        Duik.Bone.resetTransform(forearm);
    }
    if (hand)
    {
        hand.parent = null;
        Duik.Bone.resetTransform(hand);
    }
    for (var i = 0; i < feathers.length; i++)
    {
        var f = feathers[i];
        var parent = f.parent;
        f.parent = null;
        Duik.Bone.resetTransform(f);
        f.parent = parent;
    }

    // adjust/fix what we got! We're very friendly...
    // we need a hand and a root
    if (!hand && !forearm && !arm) {
        // Sorry, can't do anything!
        return;
    }
    if (!hand) {
        hand = forearm;
        forearm = null;
    }
    if (!hand) {
        hand = arm;
        arm = null;
    }
    if (!forearm) {
        forearm = arm;
        arm = null;
    }
    var root = null;
    if (arm) root = arm;
    else if (forearm) root = forearm;
    else root = hand;

    // Find the hand tip
    var layer;
    while( layer = layers.next() ) {
        var tag = DuAETag.get( layer );
        var bone = DuAETag.getValue( layer, DuAETag.Key.DUIK_BONE_TYPE, DuAETag.Type.STRING, tag );

        if (bone == OCO.Bone.TIP) {
            if (layer.parent == hand) {
                handTip = layer;
                break;
            }
        }
    };

    DuScriptUI.progressBar.hit(1, i18n._("Creating controllers"));

    var ctrl = Duik.Controller.getCreate(root, Duik.Controller.Type.WING, customControllers);

    DuScriptUI.progressBar.hit(1, i18n._("Parenting..."));

    // arm's been unparented, just use the position
    var spineAttach = null;
    forearm.parent = arm;
    hand.parent = forearm;
    root.parent = ctrl;
    ctrl.parent = spineAttach;

    // Rig!
    DuScriptUI.progressBar.hit(1, i18n._("Rigging..."));

    // Add effect
    var pe = Duik.PseudoEffect.WING;
    var ctrlEffect = pe.apply( ctrl );
    var ctrlInfo = new DuAEProperty(ctrlEffect);
    ctrlEffect.name = i18n._("Wing");

    // Set effect
    var peLayers = pe.props['Data']['Layers'];
    var peLengths = pe.props['Data']['Lengths'];
    if (arm) ctrlEffect(peLayers['Arm'].index).setValue(arm.index);
    if (forearm) ctrlEffect(peLayers['Forearm'].index).setValue(forearm.index);
    if (hand) ctrlEffect(peLayers['Hand'].index).setValue(hand.index);
    if (handTip) ctrlEffect(peLayers['Tip'].index).setValue(handTip.index);

    // Add expressions
    ctrlEffect(peLengths['Arm'].index).expression = [ DuAEExpression.Id.WING,
        'var fx = thisProperty.propertyGroup();',
        'var forearm = null;',
        'try { forearm = fx(' + peLayers['Forearm'].index + '); } catch(e) {}',
        'if (forearm) length(forearm.position);',
        'else 0;'
	].join('\n');

    ctrlEffect(peLengths['Forearm'].index).expression = [ DuAEExpression.Id.WING,
        'var fx = thisProperty.propertyGroup();',
        'var hand = null;',
        'try { hand = fx(' + peLayers['Hand'].index + '); } catch(e) {}',
        'if (hand) length(hand.position);',
        'else 0;'
	].join('\n');

    ctrlEffect(peLengths['Hand'].index).expression = [ DuAEExpression.Id.WING,
        'var fx = thisProperty.propertyGroup();',
        'var tip = null;',
        'var hand = null;',
        'try { tip = fx(' + peLayers['Tip'].index + '); } catch(e) {}',
        'try { hand = fx(' + peLayers['Hand'].index + '); } catch(e) {}',
        'if (tip) length(tip.position);',
        'else if (hand) length(hand.position) * .8;',
        'else 0;'
	].join('\n');

    if (hand) {
        var linkEffectName = DuAELayer.newUniqueEffectName( i18n._("Wing"), hand );
        var linkEffect = hand.property('ADBE Effect Parade').addProperty('ADBE Layer Control');
        linkEffect.name = linkEffectName;
        linkEffect(1).setValue(ctrl.index);
        hand.transform.rotation.expression = [ DuAEExpression.Id.WING,
            'var controller = null;',
            'var fkFx =  effect("' + linkEffect.name + '");',
            'var result = value;',
            'try { controller = fkFx(1); } catch (e) {}',
            'if ( controller !=null )',
            '{',
            '   var fx = controller.effect("' + ctrlEffect.name + '");',
            '	var flapProperty = controller.rotation;',
            '	var flex = fx(' + pe.props['General parameters']['Wing flexibility'].index + ').value;',
            '	var overlap = fx(' + pe.props['General parameters']['Air resistance'].index + ').value;',
            '	var follow = fx(' + pe.props['General parameters']['Forearm orientation'].index + ').value;',
            '	var fk = fx(' + pe.props['Hand rotation'].index + ').value;',
            '	var foldProperty = fx(' + pe.props['Fold wing'].index + ');',
            '	var arm = null;',
            '	',
            '	// adjust values',
            '	overlap /= 100;',
            '	overlap *= .1; // hand multiplicator',
            '	flex /= 100;',
            '	',
            '	// flap and fold delay',
            '	var flap = flapProperty.valueAtTime(time - overlap);',
            '	var fold = -3*foldProperty.valueAtTime(time - overlap); // hand folding ',
            '',
            '	// remove current values (it is in the flap value)',
            '	result -= flapProperty.value*flex;',
            '	// add flap and fold',
            '	result += flap*flex;',
            '	result += fold;',
            '	// Flexibility based on control velocity',
            '	result -= flapProperty.velocityAtTime(time-overlap/2) * overlap;',
            '	result -= foldProperty.velocityAtTime(time-overlap/2) * overlap;',
            '',
            '	// FK control',
            '    result += fk;',
            '}',
            'result;'
        ].join('\n');
    }

    if (forearm) {
        var linkEffectName = DuAELayer.newUniqueEffectName( i18n._("Wing"), forearm );
        var linkEffect = forearm.property('ADBE Effect Parade').addProperty('ADBE Layer Control');
        linkEffect.name = linkEffectName;
        linkEffect(1).setValue(ctrl.index);
        forearm.transform.rotation.expression = [ DuAEExpression.Id.WING,
            'var controller = null;',
            'var fkFx =  effect("' + linkEffect.name + '");',
            'var result = value;',
            'try { controller = fkFx(1); } catch (e) {}',
            'if ( controller !=null )',
            '{',
            '   var fx = controller.effect("' + ctrlEffect.name + '");',
            '	var flapProperty = controller.rotation;',
            '	var flex = fx(' + pe.props['General parameters']['Wing flexibility'].index + ').value;',
            '	var overlap = fx(' + pe.props['General parameters']['Air resistance'].index + ').value;',
            '	var follow = fx(' + pe.props['General parameters']['Forearm orientation'].index + ').value;',
            '	var fk = fx(' + pe.props['Forearm rotation'].index + ').value;',
            '	var foldProperty = fx(' + pe.props['Fold wing'].index + ');',
            '	var arm = null;',
            '	try { arm = fx(' + peLayers['Arm'].index + ') } catch(e) {}',
            '	if (arm) {',
            '		var armFK = fx(' + pe.props['Arm rotation'].index + ').value;',
            '		if (!follow) result -= armFK;',
            '	}',
            '	',
            '	// adjust values',
            '	overlap /= 100;',
            '	overlap *= .05; // forearm multiplicator',
            '	flex /= 100;',
            '	',
            '	// flap and fold delay',
            '	var flap = flapProperty.valueAtTime(time - overlap);',
            '	var fold = 2*foldProperty.valueAtTime(time - overlap); // forearm folding ',
            '',
            '	// remove current values (it is in the flap value)',
            '	result -= flapProperty.value*flex;',
            '	// add flap and fold',
            '	result += flap*flex;',
            '	result += fold;',
            '	// Flexibility based on control velocity',
            '	result -= flapProperty.velocityAtTime(time-overlap/2) * overlap;',
            '	result -= foldProperty.velocityAtTime(time-overlap/2) * overlap;',
            '',
            '	// FK control',
            '    result += fk;',
            '}',
            'result;'
        ].join('\n');
    }

    if (arm) {
        var linkEffectName = DuAELayer.newUniqueEffectName( i18n._("Wing"), arm );
        var linkEffect = arm.property('ADBE Effect Parade').addProperty('ADBE Layer Control');
        linkEffect.name = linkEffectName;
        linkEffect(1).setValue(ctrl.index);
        arm.transform.rotation.expression = [ DuAEExpression.Id.WING,
            'var controller = null;',
            'var fkFx =  effect("' + linkEffect.name + '");',
            'var result = value;',
            'try { controller = fkFx(1); } catch (e) {}',
            'if ( controller !=null )',
            '{',
            '   var fx = controller.effect("' + ctrlEffect.name + '");',
            '	var fk = fx(' + pe.props['Arm rotation'].index + ').value;',
            '	var fold = -fx(' + pe.props['Fold wing'].index + ').value;',
            '	var flap = controller.rotation.value;',
            '   result += fk + fold;',
            '	if (!hasParent) result += flap ;',
            '	else if (parent != controller) result += flap;',
            '}',
            'result;'
        ].join('\n');
    }

    for (var i = 0; i < feathers.length; i++) {
        var feather = feathers[i];
        var linkEffectName = DuAELayer.newUniqueEffectName( i18n._("Wing"), feather );
        var linkEffect = feather.property('ADBE Effect Parade').addProperty('ADBE Layer Control');
        linkEffect.name = linkEffectName;
        linkEffect(1).setValue(ctrl.index);

        // Add the feather control
        var peFK = Duik.PseudoEffect.FEATHER;
        var fkEffect = peFK.apply(ctrl);
        // The ctrlEffect is now invalid, get it back
        var ctrlEffect = ctrlInfo.getProperty();

        feather.transform.rotation.expression = [ DuAEExpression.Id.WING,
            'var controller = null;',
            'try { controller = effect("' + linkEffect.name + '")(1); } catch (e) {}',
            'var fx = controller.effect("' + ctrlEffect.name + '");',
            'var fFx = controller.effect("' + fkEffect.name + '");',
            'var r = fFx(' + peFK.props['Rotation'].index + ').value;',
            'var foldedAngle = fFx(' + peFK.props['Settings']['Folded angle'].index + ').value;',
            'var overlap = fx(' + pe.props['General parameters']['Air resistance'].index + ').value;',
            'var handCustomInfluence = fx(' + pe.props['Feather parameters']['Hand rotation multiplicator'].index + ').value;',
            'var armLength = fx(' + peLengths['Arm'].index + ').value;',
            'var forearmLength = fx(' + peLengths['Forearm'].index + ').value;',
            'var handLength = fx(' + peLengths['Hand'].index + ').value;',
            'var fold = fx(' + pe.props['Fold wing'].index + ').value;',
            'var arm = null;',
            'var forearm = null;',
            'var hand = null;',
            'try { arm = fx(' + peLayers['Arm'].index + '); } catch(e) {}',
            'try { forearm = fx(' + peLayers['Forearm'].index + '); } catch(e) {}',
            'try { hand = fx(' + peLayers['Hand'].index + '); } catch(e) {}',
            DuAEExpression.Library.get([
                'getOrientation',
                'dishineritRotation',
                'getLayerDistance',
                'linearExtrapolation',
                'normalizeWeights'
            ]),
            '',
            'function featherOrientation() {',
            '  if (!hasParent) return value; // Stupid rig.',
            '	',
            '	// Prepare values',
            '	overlap /= 100;',
            '	overlap *= 0.1;',
            '	var t = time - overlap;',
            '	var armInfluence = 1;',
            '	var forearmInfluence = 1;',
            '	var handInfluence = 1;',
            '	handCustomInfluence -= 1;',
            '	',
            '  // The orientations we\'re getting from each part.',
            '  var armOrientation = 0;',
            '  var forearmOrientation = 0;',
            '  var handOrientation = 0;',
            '  ',
            '  // Adjust the layers we\'ve got...',
            '  if (!hand && !forearm && !arm) {',
            '    hand = parent;',
            '  }',
            '  else {',
            '    if (!hand) {',
            '      hand = forearm;',
            '      handLength = forearmLength;',
            '      forearm = null;',
            '    }',
            '    if (!hand) {',
            '      hand = arm;',
            '      handLength = armLength;',
            '      arm = null;',
            '    }',
            '    if (!forearm) {',
            '      forearm = arm;',
            '      forearmLength = armLength;',
            '      arm = null;',
            '    }',
            '  }',
            '',
            '  // Check where the feather is attached',
            '  var handFeather = parent == hand;',
            '  var forearmFeather = false;',
            '  if (forearm) forearmFeather = parent == forearm;',
            '  var armFeather = false;',
            '  if (arm) armFeather = parent == arm;',
            '  ',
            '  // Get distances',
            '  var handDistance = getLayerDistance(hand);',
            '  var forearmDistance = -1;',
            '  if (forearm) forearmDistance = getLayerDistance(forearm);',
            '  var armDistance = -1;',
            '  if (arm) armDistance = getLayerDistance(arm);',
            '  ',
            '    // Check if we\'re folded ',
            '    var armExtension = getLayerDistance(hand, arm);',
            '    var limbLength = armLength + forearmLength;',
            '    var folded = linear(armExtension, 0, limbLength, 1, 0);',
            '    folded *= linear(Math.abs(fold), 0, 30, 0, 1);',
            '    foldedAngle *= folded;',
            '',
            '  // Get orientations',
            '',
            '  if (armFeather) {',
            '    // Influences',
            '    forearmInfluence = linear(armDistance,',
            '      armLength*.66, armLength + forearmLength * .2,',
            '      0, forearmInfluence',
            '    );',
            '    armInfluence = linear(armDistance,',
            '      armLength*.66, armLength + forearmLength * .2,',
            '      armInfluence, 0',
            '    );',
            '    var w = normalizeWeights([armInfluence, forearmInfluence]);',
            '    // Arm orientation',
            '    armOrientation += getOrientation(arm, t);',
            '    armOrientation *= w[0];',
            '    // Forearm orientation ',
            '    forearmOrientation += getOrientation(forearm, t);',
            '    forearmOrientation *= w[1];',
            '    ',
            '    return dishineritRotation() + armOrientation + forearmOrientation + foldedAngle;',
            '  }',
            '  ',
            '  if (forearmFeather) {',
            '    // Hand influence',
            '    handInfluence = linear(forearmDistance,',
            '      forearmLength*.5, forearmLength + handLength,',
            '      0, handInfluence',
            '    );',
            '    // Hand orientation',
            '    handOrientation = getOrientation(hand, t);',
            '    ',
            '    if (!arm) {',
            '      // Forearm Influence',
            '      forearmInfluence = linear(forearmDistance,',
            '        forearmLength*.5, forearmLength + handLength*.5,',
            '        forearmInfluence, 0',
            '      );',
            '      var w = normalizeWeights([forearmInfluence, handInfluence]);',
            '      ',
            '      handOrientation *= w[1];',
            '      forearmOrientation = getOrientation(forearm, t);',
            '      forearmOrientation *= w[0];',
            '      ',
            '      return dishineritRotation() + handOrientation + forearmOrientation + foldedAngle;',
            '    }',
            '    ',
            '    // Influence of the arm',
            '    armInfluence = linear(armDistance,',
            '      armLength*.66, armLength + forearmLength * .2,',
            '      armInfluence, 0',
            '    );',
            '    // Influence of the forearm',
            '    forearmInfluence = linear( forearmDistance,',
            '      forearmLength*.5,  forearmLength + handLength,',
            '      forearmInfluence, 0',
            '    );',
            '    var w = normalizeWeights([armInfluence, forearmInfluence, handInfluence]);',
            '    armOrientation = getOrientation(arm, t);',
            '    armOrientation *= w[0];',
            '    forearmOrientation = getOrientation(forearm, t);',
            '    forearmOrientation *= w[1];',
            '    handOrientation *= w[2];',
            '    return dishineritRotation() + handOrientation + forearmOrientation + armOrientation + foldedAngle;',
            '  }',
            '',
            '  var handRotation = hand.rotation.valueAtTime(t) - hand.rotation.valueAtTime(0);',
            '  handRotation *= linearExtrapolation( handDistance,',
            '    0, handLength,',
            '    0, handCustomInfluence',
            '  );',
            '  ',
            '  if (!forearm) return value + handRotation;',
            '  // Influences',
            '  handInfluence = linear( handDistance,',
            '    0, handLength,',
            '    handInfluence*.5, handInfluence',
            '  );',
            '  forearmInfluence = linear( handDistance,',
            '    0, handLength,',
            '    forearmInfluence/2, 0',
            '  );',
            '  forearmInfluence += linear( forearmDistance,',
            '    0, forearmLength,',
            '    .4, 0',
            '  );',
            '',
            '  var w = normalizeWeights([forearmInfluence, handInfluence]);',
            '  forearmOrientation = getOrientation(forearm, t);',
            '  forearmOrientation *= w[0];',
            '  handOrientation = getOrientation(hand, t);',
            '  handOrientation *= w[1];',
            '  return dishineritRotation() + forearmOrientation + handOrientation + handRotation + foldedAngle;',
            '',
            '}',
            '',
            'var result = featherOrientation() + r;',
            'result;',
            ''
        ].join('\n');
    }

    return ctrl;
}

/**
 * Rigs hair strands
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @return {Layer[]} The controllers for the hair
 */
Duik.Rig.hair = function( layers, customControllers )
{
    // Hair are tails :-)
    var hairCtrls = Duik.Rig.tail(layers, false, customControllers, true);
    if (hairCtrls.length == 0) return [];

    // Just set the FK control to no follow
    var pe = Duik.PseudoEffect.FK;
    var fx = hairCtrls[0].property('ADBE Effect Parade').property(pe.matchName);
    if (!fx) return;
    fx(pe.props['Parent rotation'].index).setValue(0);

    return hairCtrls;
}

/**
 * Rigs custom chains
 * @param {Layer[]|DuList.<Layer>} [layers] - The layers to rig
 * @param {Duik.Constraint.IKType} [tailMode=Duik.Constraint.IKType.FK] How to rig tails and other chains consisting of more than 3 layers.
 * @param {Duik.Constraint.IKType} [threeLayerMode=Duik.Constraint.IKType.ONE_TWO] How to rig tails and other chains consisting of more than 3 layers.
 * @param {Layer[]|DuList.<Layer>} [customControllers] - Existing custom controllers to use
 * @return {Layer[]} The controllers
 */
Duik.Rig.custom = function( layers, tailMode, threeLayerMode, customControllers ) {
    layers = def(layers, DuAEComp.unselectLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return [];

    Duik.Bone.setRigged( layers );
    
    tailMode = def(tailMode, Duik.Constraint.IKType.FK);
    threeLayerMode = def(threeLayerMode, Duik.Constraint.IKType.ONE_TWO);

    customControllers = new DuList(customControllers);

    DuScriptUI.progressBar.stg( i18n._("Custom bones"));
    DuScriptUI.progressBar.hit(1, i18n._("Sorting bones..."));

    var comp = layers.first().containingComp;

    // Sort
    // a sorter for spine and neck
	function sortBones(a,b)
	{
        var ai = DuAETag.getValue( a, DuAETag.Key.DUIK_BONE_INDEX, DuAETag.Type.INT );
        var bi = DuAETag.getValue( b, DuAETag.Key.DUIK_BONE_INDEX, DuAETag.Type.INT );
		return ai - bi;
	}

    layers.sort(sortBones);
    
    var numLayers = layers.length();

    DuScriptUI.progressBar.hit(1, i18n._("Rigging..."));

    // Rig
    if (numLayers == 1) {
        var ctrl = Duik.Controller.getCreate( layers.first(), Duik.Controller.Type.TRANSFORM, customControllers );
        Duik.Constraint.simpleFK( layers, ctrl );
        return  [ctrl];
    }
    else if (numLayers == 2) {
        var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
        Duik.Constraint.oneLayerIK( layers.first(), layers.last(), ctrl );
        return  [ctrl];
    }
    else if (numLayers == 3) {
        var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
        Duik.Constraint.twoLayerIK( layers.first(), layers.at(1), layers.last(), ctrl );
        return  [ctrl];
    }
    else if (numLayers == 4) {
        if (threeLayerMode == Duik.Constraint.IKType.FK) {
            var ctrl = Duik.Controller.getCreate( layers.first(), Duik.Controller.Type.TRANSFORM, customControllers );
            Duik.Constraint.fk(layers, ctrl);
            return  [ctrl];
        }
        else if (threeLayerMode == Duik.Constraint.IKType.ONE_TWO) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            Duik.Constraint.oneTwoLayerIK(layers.at(0), layers.at(1), layers.at(2), layers.last(), ctrl);
            return  [ctrl];
        }
        else if (threeLayerMode == Duik.Constraint.IKType.TWO_ONE) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            Duik.Constraint.twoOneLayerIK(layers.at(0), layers.at(1), layers.at(2), layers.last(), ctrl);
            return  [ctrl];
        }
        else if (threeLayerMode == Duik.Constraint.IKType.BEZIER_IK) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            var tip = layers.pop();
            return Duik.Constraint.bezierIK(layers, tip, ctrl);
        }
        else if (threeLayerMode == Duik.Constraint.IKType.BEZIER_FK) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            var ctrl1 = Duik.Controller.getCreate( layers.first(), Duik.Controller.Type.TRANSFORM, customControllers );
            var tip = layers.pop();
            return Duik.Constraint.bezierFK(layers, tip, ctrl, undefined, ctrl1);
        }
    }
    else {
        if (tailMode == Duik.Constraint.IKType.FK) {
            var ctrl = Duik.Controller.getCreate( layers.first(), Duik.Controller.Type.TRANSFORM, customControllers );
            Duik.Constraint.fk(layers, ctrl);
            return [ctrl];
        }
        else if (tailMode == Duik.Constraint.IKType.BEZIER_IK) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            var tip = layers.pop();
            return Duik.Constraint.bezierIK(layers, tip, ctrl);
        }
        else if (tailMode == Duik.Constraint.IKType.BEZIER_FK) {
            var ctrl = Duik.Controller.getCreate( layers.last(), Duik.Controller.Type.TRANSFORM, customControllers );
            var ctrl1 = Duik.Controller.getCreate( layers.first(), Duik.Controller.Type.TRANSFORM, customControllers );
            var tip = layers.pop();
            return Duik.Constraint.bezierFK(layers, tip, ctrl, undefined, ctrl1);
        }
    }
}
// ====== automation.jsx======

/**
 * The lazy animator's toolkit.
 * @namespace
 * @category Duik
 */
Duik.Automation = {};

/**
 * The types of the comps in an NLA
 * @enum {number}
 * @readonly
 * @ts-ignore */
Duik.Automation.NLACompType = {
    NONE: 0,
    ORIGINAL: 1,
    RENDER: 2,
    CLIP: 3,
    EDIT: 4
}

/**
 * The prefixes for the NLA comp & folder names.<br />
 * These may be localized, don't use the actual strings!
 * @enum {string}
 * @readonly
 * @ts-ignore */
Duik.Automation.NLAPrefixes = {
    FOLDER: "NLA" + '::',
    ORIGINAL: "NLA" + '.Original::',
    RENDER: "NLA" + '.Render::',
    CLIP: "NLA" + '.Clip::',
    EDIT: "NLA" + '.Edit::'
}

/**
 * Checks if the given comp is part of an NLA
 * @return {Duik.Automation.NLACompType} The type of the comp; Duik.Automation.NLACompType.NONE if it's not part of an NLA.
 */
Duik.Automation.NLAType = function(comp) {
    // It must be in an NLA folder
    var nlaFolder = comp.parentFolder;
    if (nlaFolder.name.indexOf(Duik.Automation.NLAPrefixes.FOLDER) != 0) return Duik.Automation.NLACompType.NONE;

    var name = comp.name;
    if (name.indexOf(Duik.Automation.NLAPrefixes.ORIGINAL) == 0) return Duik.Automation.NLACompType.ORIGINAL;
    if (name.indexOf(Duik.Automation.NLAPrefixes.RENDER) == 0) return Duik.Automation.NLACompType.RENDER;
    if (name.indexOf(Duik.Automation.NLAPrefixes.CLIP) == 0) return Duik.Automation.NLACompType.CLIP;
    if (name.indexOf(Duik.Automation.NLAPrefixes.EDIT) == 0) return Duik.Automation.NLACompType.EDIT;
    return Duik.Automation.NLACompType.NONE;
}

/**
 * Gets the folder containing the NLA Compositions like the given comp.
 * @param {CompItem} comp The comp
 * @return {FolderItem|null} The folder or null if the comp is not part of an NLA
 */
Duik.Automation.getNLAFolder = function(comp) {
    var nlaFolder = comp.parentFolder;
    if (nlaFolder.name.indexOf(Duik.Automation.NLAPrefixes.FOLDER) != 0) return null;
    return nlaFolder;
}

/**
 * Gets the render, original and edit comps for this NLA
 * @param {FolderItem} nlaFolder The NLA Folder
 * @return {CompItem[]} The compositions in this order: [Original, Edit, Render]. Note that if one is not found, null is returned.
 */
Duik.Automation.getNLAComps = function(nlaFolder) {
    var originalComp = null;
    var editComp = null;
    var renderComp = null;
    for (var i = 1, n = nlaFolder.numItems; i <= n; i++) {
        var c = nlaFolder.item(i);
        if (!(c instanceof CompItem)) continue;
        if (c.name.indexOf(Duik.Automation.NLAPrefixes.ORIGINAL) == 0) {
            originalComp = c;
        }
        if (c.name.indexOf(Duik.Automation.NLAPrefixes.EDIT) == 0) {
            editComp = c;
        }
        if (c.name.indexOf(Duik.Automation.NLAPrefixes.RENDER) == 0) {
            renderComp = c;
        }
        // Got'em all
        if (originalComp && editComp && renderComp) break;
    }
    return [originalComp, editComp, renderComp];
}

/**
 * The list of automation functions
 * @namespace
 */
Duik.CmdLib['Automation'] = {};

Duik.CmdLib['Automation']["NLA"] = "Duik.Automation.setupNLA()";
/**
 * Sets up a non-linear animation comp.
 * @param {CompItem} [comp] The composition to set up. The active composition if omitted.
 * @param {Boolean} [selectedProps=true] Use only currently selected properties if true, all properties (according to the other options) if false.
 * @param {Boolean} [transformProps] If true, filters only properties in the transform group of the layers. Ignored if selectedProps is true.
 * @param {Boolean} [effectProps] If true, filters only properties in effects. Ignored if selectedProps is true.
 * @param {Duik.Layer.Type[]} [layerTypes=[Duik.Layer.Type.CONTROLLER]] The types of layer to setup if there's no selected layer; if empty, will setup all layers.
 * @param {PropertyBase[]|DuList|DuAEProperty[]} [props] A list of properties to set up. In case this parameter is provided, all other parameters are ignored.
 */
Duik.Automation.setupNLA = function(comp, selectedProps, transformProps, effectProps, layerTypes, props) {
    comp = def(comp, DuAEProject.getActiveComp());

    DuAE.beginUndoGroup( i18n._("Non-linear animation"), false);

    DuAEComp.setUniqueLayerNames(comp.layers, comp);

    var doGroups = false;

    if (typeof props === 'undefined') {
        selectedProps = def(selectedProps, true);
        transformProps = def(transformProps, true);
        effectProps = def(effectProps, false);
        layerTypes = def(layerTypes, [Duik.Layer.Type.CONTROLLER]);

        // List properties according to the filters

        if (selectedProps) {
            props = DuAEComp.getSelectedProps();
            if (props.length == 0) selectedProps = false;
        }

        if (!selectedProps) {
            // Get the layers
            var layers = [];
            props = [];
            var selectedLayers = comp.selectedLayers;
            if (layerTypes.length > 0 && selectedLayers.length == 0) {
                for (var i = 1, n = comp.numLayers; i <= n; i++) {
                    var l = comp.layer(i);
                    for (var j = 0, nt = layerTypes.length; j < nt; j++) {
                        if (Duik.Layer.isType(l, layerTypes[j])) {
                            layers.push(l);
                            break;
                        }
                    }
                }
            }
            else layers = selectedLayers;
            if (layers.length == 0) layers = comp.layers;

            doGroups = true;

            layers = new DuList(layers);
            layers.do(function(layer) {
                if (transformProps) props.push(new DuAEProperty(layer.transform));
                var isCtrl = Duik.Layer.isType(layer, Duik.Layer.Type.CONTROLLER);
                //if (typeof effectProps === 'undefined' && isCtrl) props.push(new DuAEProperty(layer.property('ADBE Effect Parade')));
                if (effectProps) props.push(new DuAEProperty(layer.property('ADBE Effect Parade')));
            });
        }
    }

    props = new DuList(props);

    if (props.length() == 0) {
        DuAE.endUndoGroup( i18n._("Non-linear animation"));
        return;
    }

    DuAEProject.setProgressMode(true);
    DuScriptUI.progressBar.setMax(props.length() + 6);

    var compName = comp.name;
    var editComp;

    // Check if it's already an NLA; in this case don't create, just add the properties.
    DuScriptUI.progressBar.hit(1, "Checking if we're updating an existing NLA...");
    var create = true;
    if (Duik.Automation.NLAType(comp) != Duik.Automation.NLACompType.NONE) {
        var nlaFolder = Duik.Automation.getNLAFolder(comp);
        if (nlaFolder) {
            create = false;
            var nlaComps = Duik.Automation.getNLAComps(nlaFolder);
            var renderComp = nlaComps[2];
            editComp = nlaComps[1];
            // Find the same properties in the render comp
            if (renderComp) {
                DuScriptUI.progressBar.addMax(props.length());
                DuScriptUI.progressBar.hit(1, "Preparing properties to be added...");
                var renderProps = [];
                props.do(function(prop) {
                    DuScriptUI.progressBar.hit();
                    renderProp = prop.findInComp(renderComp);
                    if (renderProp) renderProps.push(renderProp);
                });
                // Replace props with the ones from the render comp
                props = new DuList(renderProps);
                DuScriptUI.progressBar.hit(4);
            }
        }
    }

    clipPrecomp = null;
    weightEffectName = "NLA::" + i18n._("Weight"); /// TRANSLATORS: weight as the multiplicator of a value, a % or a ratio.

    if (create) {
        // Create folderitem NLA::compName
        DuScriptUI.progressBar.hit(1, "Creating NLA Folder...");
        var parentFolder = comp.parentFolder;
        var nlaFolder = app.project.items.addFolder(Duik.Automation.NLAPrefixes.FOLDER + compName);
        nlaFolder.parentFolder = parentFolder;
        comp.parentFolder = nlaFolder;
        var renderComp = comp;

        // Duplicate comp twice
        // One will be NLA.Render::compName
        DuScriptUI.progressBar.hit(1, "Saving original composition...");
        var oComp = renderComp.duplicate();
        oComp.name = Duik.Automation.NLAPrefixes.ORIGINAL + compName;
        // Other NLA.Clip::compName
        DuScriptUI.progressBar.hit(1, "Creating the first clip...");
        var clipComp = renderComp.duplicate();
        clipComp.name = Duik.Automation.NLAPrefixes.CLIP + compName;
        // and keep NLA.Original::compName
        DuScriptUI.progressBar.hit(1, "Creating the render composition...");
        var originalCompName = renderComp.name;
        renderComp.name = Duik.Automation.NLAPrefixes.RENDER + compName;
        // Create NLA.Edit::compName
        DuScriptUI.progressBar.hit(1, "Creating the edit composition...");
        var editComp = nlaFolder.items.addComp(
            Duik.Automation.NLAPrefixes.EDIT + compName,
            renderComp.width, renderComp.height, renderComp.pixelAspect, renderComp.duration, renderComp.frameRate
        );

        // Add NLA.Clip
        var clipPrecomp = editComp.layers.add(clipComp);
        clipPrecomp.enabled = false;
        clipPrecomp.guideLayer = false;

        // Add a weight slider
        var weightEffect = clipPrecomp.property('ADBE Effect Parade').addProperty('ADBE Slider Control');
        weightEffect.name = weightEffectName;
        weightEffect(1).setValue(100);

        // Add NLA.Render
        editComp.layers.add(comp);

        // Fix expressions (the comp name has changed)
        app.project.autoFixExpressions(originalCompName, renderComp.name);
    }

    DuScriptUI.progressBar.hit(1, "Adding expressions...");

    // Setup properties in NLA.Render

    var exp = [DuAEExpression.Id.NLA,
        'var editComp = comp("' + editComp.name + '");',
        '',
        'var result = value;',
        'var weights = 0;',
        '',
        DuAEExpression.Library.get(['getSameProp', 'isZero']),
        '',
        'for (var i = 1, n = editComp.numLayers; i <= n; i++)',
        '{',
        '	var l = editComp.layer(i);',
        '	if (l.name == thisComp.name) continue;',
        '   if (l.name.indexOf("' + Duik.Automation.NLAPrefixes.CLIP + '") != 0) continue;',
        '	if (time >= l.inPoint && time < l.outPoint)',
        '	{',
        '	    var precomp = l.source;',
        '	    try { var c = precomp.layer(thisLayer.name); }',
        '        catch(e) { continue; }',
        '        var weight = l.opacity.value/100;',
        '        try { weight *= l.effect("' + weightEffectName + '")(1).value/100; }',
        '        catch(e) {}',
        '        var t = time;',
        '        try { t = l.timeRemap.value; }',
        '        catch(e) { t = time - l.startTime; }',
        '        var dif = getSameProp(c).valueAtTime(t) - value;',
        '        if (isZero(dif)) continue;',
        '        weights += weight;',
        '        result += dif * weight;',
        '	}',
        '}',
        'result;'
    ].join('\n');

    props.do(function(prop) {
        if (prop.isGroup() && !doGroups) return;
        DuScriptUI.progressBar.hit();
        prop.setExpression(exp, false);
    });

    // Open edit comp
    DuScriptUI.progressBar.hit(undefined, "Ready!");
    editComp.openInViewer();

    // Open clip comp
    if (clipPrecomp) clipPrecomp.openInViewer();

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Non-linear animation"));

}

Duik.CmdLib['Automation']["NLA Clip"] = "Duik.Automation.addNLAClip()";
/**
 * Creates a clip and adds it to the NLA
 * @param {CompItem} [nlaComp] A comp belonging to an NLA, the active comp if omitted.
 * @returns {int} Success code: 1 if the clip could be created, 0 if the original comp is not found, -1 if the NLA is invalid/not found
 */
Duik.Automation.addNLAClip = function(nlaComp) {
    nlaComp = def(nlaComp, DuAEProject.getActiveComp());
    if (!nlaComp) return -1;

    var nlaFolder = Duik.Automation.getNLAFolder(nlaComp);
    if (!nlaFolder) return -1;

    var nlaName = nlaFolder.name.replace('NLA::', '');

    // Get the original comp
    var nlaComps = Duik.Automation.getNLAComps(nlaFolder);
    var originalComp = nlaComps[0];
    var editComp = nlaComps[1];

    if (!originalComp) return 0;

    // Duplicate
    var newClip = originalComp.duplicate();

    // Rename
    newClip.name = originalComp.name.replace('NLA.Original', 'NLA.Clip') + '-newClip';

    // Add to edit
    if (editComp) {
        var clipLayer = editComp.layers.add(newClip);
        clipLayer.enabled = false;
        if (editComp.numLayers >= 2) clipLayer.moveAfter(editComp.layer(2));

        // Add a weight slider
        var weightEffect = clipLayer.property('ADBE Effect Parade').addProperty('ADBE Slider Control');
        weightEffect.name = "NLA::" + i18n._("Weight"); /// TRANSLATORS: weight as the multiplicator of a value, a % or a ratio.
        weightEffect(1).setValue(100);
    }

    // Open clip
    newClip.openInViewer();

    return 1;
}

Duik.CmdLib['Automation']["Looper"] = "Duik.Automation.looper()";
/**
 * Adds a loop expression and pseudo effect with more options than the loopOut and loopIn expressions.
 * @param {PropertyBase[]|DuList.<PropertyBase>|PropertyBase} [props] The properties to loop. The selected properties in the active comp if omitted.
 * @param {PropertyGroup} [effect] The pseudo effect to use if it already exists.
 * @returns {PropertyGroup} The pseudo-effect
 */
Duik.Automation.looper = function(props, effect) {
    effect = Duik.Animation.interpolator(props, effect);
    if (!effect) return null;

    DuAE.beginUndoGroup( i18n._("Looper"), false);

    var i = Duik.PseudoEffect.INTERPOLATOR.props;

    // Set interpolation to none
    effect(i['Type'].index).setValue(1);
    // Set extrapolation to 100%
    effect(i['Extrapolation'].index).setValue(100);
    // Set cycles
    effect(i['In Extrapolation and loop']['Type'].index).setValue(4);
    effect(i['Out Extrapolation and loop']['Type'].index).setValue(4);
    // Activate
    effect(i['In Extrapolation and loop']['Before keys'].index).setValue(1);
    effect(i['Out Extrapolation and loop']['After keys'].index).setValue(1);

    return effect;
}

Duik.Automation.copiedExpression = '';
Duik.CmdLib['Automation']["Copy Expression"] = "Duik.Automation.copyExpression()";
/**
 * Copies the expression from the property, which can be pasted in multiple properties with {@link Duik.Automation.pasteExpression}.
 * @param {Property|DuAEProperty} [prop] The property, the selected/active property if omitted.
 * @returns {string} The expression.
 */
Duik.Automation.copyExpression = function(prop) {
    if (typeof prop === 'undefined') {
        var props = DuAEComp.getSelectedProps();
        if (props.length == 0) return Duik.Automation.copiedExpression;
        prop = props.pop();
    }

    prop = new DuAEProperty(prop);
    if (prop.riggable()) {
        prop = prop.getProperty();
        Duik.Automation.copiedExpression = prop.expression;
    }

    return Duik.Automation.copiedExpression;
}

Duik.CmdLib['Automation']["Paste Expression"] = "Duik.Automation.pasteExpression()";
/**
 * Pastes the expression previously copied with {@link Duik.Automation.copyExpression}.
 * @param {Property[]|DuAEProperty[]} [props] The properties where to paste the expression, the selecte properties if omitted.
 * @param {string} [expression] A specific expression to paste.
 */
Duik.Automation.pasteExpression = function(props, expression) {
    props = def(props, DuAEComp.getSelectedProps());
    if (props.length == 0) return;
    expression = def(expression, Duik.Automation.copiedExpression);

    DuAE.beginUndoGroup( i18n._("Paste expression"), false);

    var i = new DuList(props);
    i.do(function(prop) {
        prop = new DuAEProperty(prop);
        // Only for true props and not groups
        if (prop.riggable())
            prop.setExpression( expression, false );
    });

    DuAE.endUndoGroup( i18n._("Paste expression"));
}

Duik.CmdLib['Automation']["Remove Expressions"] = "Duik.Automation.removeExpressions()";
/**
 * Removes the expressions from the properties.
 * @param {Boolean} [keepPostExpressionValue=true]  Set to false to just remove the expressions and get back the pre expression value.
 * @param {Property[]|DuAEProperty[]} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.removeExpressions = function(keepPostExpressionValue, props) {
    keepPostExpressionValue = def(keepPostExpressionValue, true);
    props = def(props, DuAEComp.getSelectedProps());
    if (props.length == 0) props = DuAEComp.getSelectedLayers();
    if (props.length == 0) return;

    DuAE.beginUndoGroup( i18n._("Remove expressions"), false);

    for (var i = 0, num = props.length; i < num; i++) {
        var p = new DuAEProperty(props[i]);
        // Only for true props and not groups
        if (p.riggable())
            p.removeExpressions(undefined, keepPostExpressionValue);
    }

    DuAE.endUndoGroup( i18n._("Remove expressions"));

}

Duik.CmdLib['Automation']["Disable Expressions"] = "Duik.Automation.disableExpressions()";
/**
 * Disables the expressions from the properties.
 * @param {Property[]|DuAEProperty[]} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.toggleExpressions = function(props) {
    props = def(props, DuAEComp.getSelectedProps());
    if (props.length == 0) props = DuAEComp.getSelectedLayers();
    if (props.length == 0) return;

    DuAE.beginUndoGroup( i18n._("Toggle expressions"), false);

    var enabled = null;
    for (var i = 0, num = props.length; i < num; i++) {
        var p = new DuAEProperty(props[i]);
        // Only for true props and not groups
        if (p.riggable()) {
            if (enabled === null) {
                enabled = !p.expressionEnabled();
            }
            p.enableExpressions(enabled);
        }
    }

    DuAE.endUndoGroup( i18n._("Toggle expressions"));

}

Duik.CmdLib['Automation']["Bake Expressions"] = "Duik.Automation.bakeExpressions()";
/**
 * Bakes the expressions to keyframes
 * @param {DuAEExpression.BakeAlgorithm} [mode=DuAEExpression.BakeAlgorithm.SMART] The algorithm to use for baking the expressions.
 * @param {float} [frameStep=1.0] By default, checks one value per keyframe. A lower value increases the precision and allows for sub-frame sampling. A higher value is faster but less precise.
 * @param {Duik.SelectionMode} [selectionMode=DuAE.SelectionMode.SELECTED_PROPERTIES] The expressions to bake
 */
Duik.Automation.bakeExpressions = function(mode, frameStep, selectionMode) {
    // Defaults
    mode = def(mode, DuAEExpression.BakeAlgorithm.SMART);
    frameStep = def(frameStep, 1);
    selectionMode = def(selectionMode, DuAE.SelectionMode.SELECTED_PROPERTIES);

    DuAE.beginUndoGroup( i18n._("Bake expressions"), false);
    DuAEProject.setProgressMode(true, false); // For some reason the progress bar keeps poping up...

    //DuScriptUI.progressBar.stg("Baking expressions to keyframes");

    if (selectionMode == DuAE.SelectionMode.ALL_COMPOSITIONS) DuAEProject.bakeExpressions(mode, frameStep);
    else if (selectionMode == DuAE.SelectionMode.SELECTED_COMPOSITIONS) {
        var comps = DuAEProject.getSelectedComps();
        for (var i = 0, n = comps.length; i < n; i++) {
            DuAEComp.bakeExpressions(mode, frameStep, comp);
        }
    } else if (selectionMode == DuAE.SelectionMode.ACTIVE_COMPOSITION) DuAEComp.bakeExpressions(mode, frameStep);
    else if (selectionMode == DuAE.SelectionMode.SELECTED_LAYERS) {
        var layers = DuAEComp.getSelectedLayers();
        for (var i = 0, n = layers.length; i < n; i++) {
            var p = new DuAEProperty(layers[i]);
            p.bakeExpressions(mode, frameStep);
        }
    } else {
        var props = DuAEComp.getSelectedProps();
        for (var i = 0, n = props.length; i < n; i++) {
            var p = new DuAEProperty(props[i]);
            p.bakeExpressions(mode, frameStep);
        }
    }

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Bake expressions"));
}

Duik.CmdLib['Automation']["Bake Composition"] = "Duik.Automation.bakeComposition()";
/**
 * Bakes the expressions to keyframes, and remove all non-renderable layers
 * @param {DuAEExpression.BakeAlgorithm} [mode=DuAEExpression.BakeAlgorithm.SMART] The algorithm to use for baking the expressions.
 * @param {float} [frameStep=1.0] By default, checks one value per keyframe. A lower value increases the precision and allows for sub-frame sampling. A higher value is faster but less precise.
 */
Duik.Automation.bakeComposition = function(mode, frameStep, selectionMode) {
    // Defaults
    mode = def(mode, DuAEExpression.BakeAlgorithm.SMART);
    frameStep = def(frameStep, 1);

    DuAE.beginUndoGroup( i18n._("Bake composition"), false);
    DuAEProject.setProgressMode(true, false); // For some reason the progress bar keeps poping up...

    //DuScriptUI.progressBar.stg("Baking expressions to keyframes");

    if (selectionMode == DuAE.SelectionMode.ALL_COMPOSITIONS) DuAEProject.bakeCompositions(mode, frameStep);
    else if (selectionMode == DuAE.SelectionMode.SELECTED_COMPOSITIONS) {
        var comps = DuAEProject.getSelectedComps();
        for (var i = 0, n = comps.length; i < n; i++) {
            DuAEComp.bake(mode, frameStep, comp);
        }
    } else if (selectionMode == DuAE.SelectionMode.ACTIVE_COMPOSITION) DuAEComp.bake(mode, frameStep);
    else {
        var layers = DuAEComp.getSelectedLayers();
        for (var i = 0, n = layers.length; i < n; i++) {
            DuAELayer.bake( mode, frameStep, layers[i] );
        }
    } 

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Bake composition"));
}

Duik.CmdLib['Automation']["Effector"] = "Duik.Automation.effector()";
/**
 * Creates a spatial effector to control the selected properties.
 * @param {CompItem} [comp] The composition containing the effector. The active composition by default.
 */
Duik.Automation.effector = function(comp) {
    comp = def(comp, DuAEProject.getActiveComp());
    if (!comp) return;

    DuAE.beginUndoGroup( i18n._("Effector"), false);

    var props = DuAEComp.getSelectedProps();
    var layers = DuAEComp.getSelectedLayers();

    DuAEComp.setUniqueLayerNames(undefined, comp);

    // Create the effector layer and effect
    var ctrlLayer = comp.layers.addShape();
    Duik.Layer.setAttributes(ctrlLayer, Duik.Layer.Type.EFFECTOR, i18n._("Effector"));
    //effect
    var pe = Duik.PseudoEffect.EFFECTOR;
    var innerId = pe.props['Inner limit'].index;
    var outerId = pe.props['Outer limit'].index;
    var modeId = pe.props['Mode'].index;
    var typeId = pe.props['Interpolation']['Type'].index;
    var reverseId = pe.props['Interpolation']['Reverse'].index;
    var effect = pe.apply(ctrlLayer);
    //content
    var customPathGroup = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    customPathGroup.name = "Custom Shape";
    var customPathContent = customPathGroup.property("ADBE Vectors Group");
    var customPathPath = customPathContent.addProperty("ADBE Vector Shape - Group");
    customPathPath.name = "Path";
    var customPathShape = new Shape();
    customPathShape.closed = true;
    customPathShape.vertices = [ [-100,100], [100,100], [100,-100], [-100,-100]];
    customPathPath(2).setValue( customPathShape );
    var stroke = customPathContent.addProperty("ADBE Vector Graphic - Stroke");
    stroke("ADBE Vector Stroke Color").setValue(DuColor.Color.RAINBOX_RED.floatRGBA());
    var customPathSubGroup = customPathContent.addProperty("ADBE Vector Group");
    var customPathSubContent = customPathSubGroup.property("ADBE Vectors Group");
    var customPathSubPath = customPathSubContent.addProperty("ADBE Vector Shape - Group");
    customPathSubPath(2).expression = DuAEExpression.Id.EFFECTOR + '\ncontent("Custom Shape").content("Path").path';
    var customPathOffset = customPathSubContent.addProperty("ADBE Vector Filter - Offset");
    customPathOffset(1).expression = DuAEExpression.Id.EFFECTOR + '\neffect("' + effect.name + '")(' + innerId + ').value ';
    customPathOffset(2).setValue(2);
    stroke = customPathSubContent.addProperty("ADBE Vector Graphic - Stroke");
    stroke("ADBE Vector Stroke Color").setValue(DuColor.Color.GREEN.floatRGBA());
    customPathSubGroup.transform.position.expression = '[0,0];';
    customPathGroup.transform.opacity.expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 3) 100; else 0;';

    var centerGroup = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    centerGroup.name = "Center";
    var centerContent = centerGroup.property("ADBE Vectors Group");
    var centerCircle = centerContent.addProperty("ADBE Vector Shape - Ellipse");
    centerCircle("ADBE Vector Ellipse Size").setValue([4, 4]);
    var centerFill = centerContent.addProperty("ADBE Vector Graphic - Fill");
    centerFill("ADBE Vector Fill Color").setValue(DuColor.Color.BLACK.floatRGBA());
    centerFill("ADBE Vector Fill Opacity").setValue(50);

    var innerGroup = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    innerGroup.name = "Inner (Circle)";
    var innerContent = innerGroup.property("ADBE Vectors Group");
    var innerCircle = innerContent.addProperty("ADBE Vector Shape - Ellipse");
    innerCircle("ADBE Vector Ellipse Size").expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 1)\n' +
        '{\n' +
        'var inner = effect("' + effect.name + '")(' + innerId + ')*2;\n' +
        '[inner,inner];\n' +
        '}\n' +
        'else [0,0];';
    var innerStroke = innerContent.addProperty("ADBE Vector Graphic - Stroke");
    innerStroke("ADBE Vector Stroke Color").setValue(DuColor.Color.GREEN.floatRGBA());
    innerGroup.property('ADBE Vector Transform Group').property('ADBE Vector Group Opacity').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 1) 100; else 0;';

    var outerGroup = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    outerGroup.name = "Outer (Circle)";
    var outerContent = outerGroup.property("ADBE Vectors Group");
    var outerCircle = outerContent.addProperty("ADBE Vector Shape - Ellipse");
    outerCircle("ADBE Vector Ellipse Size").expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 1)\n' +
        '{\n' +
        'var inner = effect("' + effect.name + '")(' + outerId + ')*2;\n' +
        '[inner,inner];\n' +
        '}\n' +
        'else [0,0];';
    var outerStroke = outerContent.addProperty("ADBE Vector Graphic - Stroke");
    outerStroke("ADBE Vector Stroke Color").setValue(DuColor.Color.RAINBOX_RED.floatRGBA());
    outerGroup.property('ADBE Vector Transform Group').property('ADBE Vector Group Opacity').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 1) 100; else 0;';

    var innerGroupLinear = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    innerGroupLinear.name = "Inner (Line)";
    var innerContentLinear = innerGroupLinear.property("ADBE Vectors Group");
    var innerRect = innerContentLinear.addProperty("ADBE Vector Shape - Rect");
    innerRect("ADBE Vector Rect Size").expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 2)\n' +
        '[effect("' + effect.name + '")(' + innerId + '),thisComp.height];\n' +
        'else [0,0];';
    var innerTrim = innerContentLinear.addProperty('ADBE Vector Filter - Trim');
    innerTrim('ADBE Vector Trim Start').setValue(50);
    innerTrim('ADBE Vector Trim End').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'var w = effect("' + effect.name + '")(' + innerId + ');\n' +
        'var h = thisComp.height;\n' +
        'var l = 2*w+2*h;\n' +
        '100-w/l*100;';
    var innerStroke = innerContentLinear.addProperty("ADBE Vector Graphic - Stroke");
    innerStroke("ADBE Vector Stroke Color").setValue(DuColor.Color.GREEN.floatRGBA());
    innerGroupLinear.property('ADBE Vector Transform Group').property('ADBE Vector Group Opacity').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 2) 100; else 0;';

    var outerGroupLinear = ctrlLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    outerGroupLinear.name = "Outer (Line)";
    var outerContentLinear = outerGroupLinear.property("ADBE Vectors Group");
    var outerRect = outerContentLinear.addProperty("ADBE Vector Shape - Rect");
    outerRect("ADBE Vector Rect Size").expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 2)\n' +
        '[effect("' + effect.name + '")(' + innerId + '),thisComp.height];\n' +
        'else [0,0];';
    var outerTrim = outerContentLinear.addProperty('ADBE Vector Filter - Trim');
    outerTrim('ADBE Vector Trim Start').setValue(0);
    outerTrim('ADBE Vector Trim End').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'var w = effect("' + effect.name + '")(' + innerId + ');\n' +
        'var h = thisComp.height;\n' +
        'var l = 2*w+2*h;\n' +
        '100-(h+2*w)/l*100;';
    var outerStroke = outerContentLinear.addProperty("ADBE Vector Graphic - Stroke");
    outerStroke("ADBE Vector Stroke Color").setValue(DuColor.Color.RAINBOX_RED.floatRGBA());
    outerGroupLinear.property('ADBE Vector Transform Group').property('ADBE Vector Group Opacity').expression = DuAEExpression.Id.EFFECTOR + '\n' +
        'if (effect("' + effect.name + '")(' + modeId + ').value == 2) 100; else 0;';

    // Set defaults
    // Get half the maximum distance between layers
    var distance = DuAELayer.getMaxDistance(layers) / 2;
    effect(innerId).setValue(distance * .25);
    effect(outerId).setValue(distance * .75);

    // Setup Properties
    if (props.length != 0) {
        // Setup properties
        var ctrlLink;
        var exp = [ DuAEExpression.Id.EFFECTOR,
            'var fx = null;',
            'var result = value;',
            '',
            'try',
            '{',
            '    var ctrl = effect( "{#}" )( 1 );',
            '    fx = ctrl.effect( "' + effect.name + '" );',
            '}',
            'catch ( e )',
            '{}',
            '',
            DuAEExpression.Library.get(['getScale', 'shapePointsToLayer', 'inside', 'pointsToWorld', 'getLayerWorldPos', 'distanceToLine']),
            '',
            'function effector ()',
            '{',
            '    var min = fx( ' + innerId + ' ).value;',
            '    var max = fx( ' + outerId + ' ).value;',
            '    var mode = fx( ' + modeId + ' ).value;',
            '    var type = fx( ' + typeId + ' ).value;',
            '    var reverse = fx( ' + reverseId + ' ).value;',
            '',
            '    if ( mode == 2) //line',
            '    {',
            '        max = min;',
            '        min = 0;',
            '        reverse = !reverse;',
            '    }',
            '    else if (mode == 3) // custom shape',
            '    {',
            '        max = min;',
            '        min = 0;',
            '    }',
            '',
            ' 	// Get scale values',
            '	min = min * (getScale(ctrl)[0] / 100);',
            '	max = max * (getScale(ctrl)[0] / 100);',
            '',
            '   var distance = effectorDistance( max, mode );',
            '',
            '   return effectorValue( distance, min, max, type, reverse );',
            '}',
            '',
            'function effectorDistance ( max, mode )',
            '{',
            '    var worldPos = getLayerWorldPos( );',
            '',
            '    // circle',
            '    if ( mode == 1 ) return length( worldPos, getLayerWorldPos( time, ctrl ) );',
            '    //custom shape',
            '    if ( mode == 3 )',
            '    {',
            '        var polygon = ctrl.content("Custom Shape").content("Path").path;',
            '        polygon = shapePointsToLayer( polygon );',
            '        polygon = pointsToWorld( polygon, ctrl );',
            '        var r = inside( worldPos, polygon );',
            '        if (r.inside) return 0;',
            '        if (max == 0) return 1;',
            '        var closest = r.closestVertex;',
            '        var distance1, distance2;',
            '        if ( closest == 0 ) {',
            '            distance1 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ polygon.length - 1 ] ] );',
            '            distance2 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ closest + 1 ] ] );',
            '        } else if ( ( closest + 1 ) == polygon.length ) {',
            '            distance1 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ closest - 1 ] ] );',
            '            distance2 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ 0 ] ] );',
            '        } else {',
            '            distance1 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ closest - 1 ] ] );',
            '            distance2 = distanceToLine( worldPos, [ polygon[ closest ], polygon[ closest + 1 ] ] );',
            '        }',
            '',
            '',
            '        if ( distance1 < distance2 ) {',
            '            return distance1;',
            '        } else {',
            '            return distance2;',
            '        }',
            '    }',
            '    //line',
            '    if ( mode == 2 ) ',
            '    {',
            '        var coords = ctrl.fromWorld( worldPos );',
            '        return -coords[ 0 ] + max / 2;',
            '    }',
            '',
            '    return 0;',
            '}',
            '',
            'function effectorValue ( distance, min, max, type, reverse )',
            '{',
            '    var t = 0;',
            '    var beginTime = key( 1 ).time;',
            '    var endTime = key( numKeys ).time;',
            '',
            '    if ( type == 1 )',
            '    {',
            '        if ( !reverse ) t = linear( distance, min, max, endTime, beginTime );',
            '        else t = linear( distance, min, max, beginTime, endTime );',
            '    }',
            '    else',
            '    {',
            '        var mid = ( min + max ) / 2;',
            '        if ( !reverse )',
            '        {',
            '            if ( distance > mid ) t = linear( distance, mid, max, endTime, beginTime );',
            '            else t = linear( distance, min, mid, beginTime, endTime );',
            '        }',
            '        else',
            '        {',
            '            if ( distance > mid ) t = linear( distance, mid, max, beginTime, endTime );',
            '            else t = linear( distance, min, mid, endTime, beginTime );',
            '        }',
            '    }',
            '    return valueAtTime( t );',
            '}',
            '',
            'result = ( fx && numKeys >= 2 ) ? effector() : result;',
            ''
		].join('\n');
        for(var i = 0, n = props.length; i < n; i++) {
            var prop = props [i];
            // Only for true props and not groups
            if (prop.riggable())
            {
                var layer = prop.layer;
                var linkEffect = DuAELayer.getCreateLayerEffect(layer, ctrlLayer, i18n._("Effector"));
                prop.setExpression( DuString.args(exp, linkEffect.name), false );
            }
        }
    }

    DuAE.endUndoGroup( i18n._("Effector"), false);

    return ctrlLayer;
}

/**
 * Creates a map (texture) effector to control the selected properties.
 * @param {AVLayer} mapLayer The layer to use as a texture/map.
 * @param {Property[]|DuAEProperty[]} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.effectorMap = function( mapLayer, props ) {

    // Create effect
    var pe = Duik.PseudoEffect.EFFECTOR_MAP;
    var channelId = pe.props['Channel'].index;
    var minId = pe.props['Minimum'].index;
    var maxId = pe.props['Maximum'].index;
    var reverseId = pe.props['Reverse'].index;

    var effect = pe.apply(mapLayer);

    // Setup properties
    props = new DuList(props);
    if (props.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Effector map"), false);

    DuAEComp.setUniqueLayerNames(undefined, props.first().comp);

    // Setup properties
    var ctrlLink;
    var exp = [DuAEExpression.Id.EFFECTOR_MAP,
		'var fx = null;',
		'var ctrl = null;',
		'var result = value;',
		'',
		'try',
		'{',
		'    ctrl = effect("{#}")(1);',
		'    fx = ctrl.effect( "' + effect.name + '" );',
		'}',
		'catch ( e )',
		'{}',
        '',
        DuAEExpression.Library.get(["isShapeLayer"]),
		'',
		'// Get layer world position',
		'function p ( l )',
		'{',
		'    return l.toWorld( l.anchorPoint )',
		'}',
		'',
		'function effector ()',
		'{',
		'    var min = fx( ' + minId + ' ).value;',
		'    var max = fx( ' + maxId + ' ).value;',
		'    var reverse = fx( ' + reverseId + ' ).value;',
		'    var channel = fx( ' + channelId + ' ).value;',
		'',
		'    min = min / 100;',
		'    max = max / 100;',
		'',
		'    var distance = effectorDistance( channel );',
		'    return effectorValue( distance, min, max, reverse );',
		'',
		'}',
		'',
		'function effectorDistance ( channel )',
		'{',
		'    var distance = 0;',
		'',
		'    var colorPoint = p( thisLayer );',
		'',
		'    if ( typeof channel === "undefined" ) channel = 5;',
		'    if (!isShapeLayer(ctrl)) colorPoint = ctrl.fromWorld( colorPoint );',
		'    var color = ctrl.sampleImage( colorPoint );',
		'    if ( channel <= 3 ) distance = color[ channel-1 ];',
		'	else if (channel <= 6)',
		'	{',
		'		color = rgbToHsl(color);',
		'		distance = color[ channel - 4 ];',
		'	}',
		'    else distance = color[ 3 ];',
		'',
		'    return distance;',
		'}',
		'',
		'function effectorValue ( distance, min, max, reverse )',
		'{',
		'    var t = 0;',
		'    var beginTime = key( 1 ).time;',
		'    var endTime = key( numKeys ).time;',
		'',
		'    if ( !reverse ) t = linear( distance, min, max, beginTime, endTime );',
		'    else t = linear( distance, min, max, endTime, beginTime );',
		'',
		'    return valueAtTime( t );',
		'}',
		'',
		'result = ( fx && numKeys >= 2 ) ? effector() : result;',
		''
	].join('\n');
    props.do(function(prop) {
        // Only for true props and not groups
        prop = new DuAEProperty(prop)
        if (prop.riggable())
        {
            var layer = prop.layer;
            var linkEffect = DuAELayer.getCreateLayerEffect(layer, mapLayer, i18n._("Effector map"));
            prop.setExpression( DuString.args(exp, linkEffect.name), false);
        }
        
    });

    // Select the map only
    DuAEComp.unselectLayers();
    mapLayer.selected = true;

    DuAE.endUndoGroup( i18n._("Effector map"), false );
}

Duik.CmdLib['Automation']["Kleaner"] = "Duik.Automation.kleaner()";
/**
 * Adds the <i>Kleaner</i> effect and expression to the properties.
 * The <i>Kleaner</i> (Keyframe Cleaner) makes it quick and easy to interpolate, add anticipation, overlap and follow through to any animation.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 * @param {PropertyGroup} [effect] The pseudo effect to use if it already exists.
 * @return {PropertyGroup|null} The Kleaner effect (or null if there's no property to setup).
 */
Duik.Automation.kleaner = function(props, effect) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return null;

    var p = props.at(0);
    p = new DuAEProperty(p);
    var ctrlLayer = p.layer;

    DuAE.beginUndoGroup("_" + i18n._("Kleaner"), false);

    DuAEComp.setUniqueLayerNames(undefined, ctrlLayer.containingComp);

    // Add the effect
    if (!effect)
    {
        effect = Duik.PseudoEffect.KLEANER.apply( ctrlLayer, i18n._("Kleaner") + ' | ' + p.name );
    }

    // Indices
    var i = Duik.PseudoEffect.KLEANER.props;

    // Setup the expressions in the Data
    
    var fuzzyLib = DuAEExpression.Library.get(["FuzzyVeracity", "linearExtrapolation"]);

    var interpolationRateExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var weight = fx(' + i['Weight'].index + ').value;',
        'var strength = fx(' + i['Strength'].index + ').value;',
        'var will = fx(' + i['Will'].index + ').value;',
        'var friction = fx(' + i['Friction'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = -.187;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  weight = new FuzzyVeracity( weight / 1000 );',
        '  strength = new FuzzyVeracity( strength / 1000 );',
        '  will = new FuzzyVeracity( will / 1000 );',
        '  friction = new FuzzyVeracity( friction / 1000 );',
        '  ',
        '  // Compute ratio',
        '  var inertia = weight.OR( strength.NEGATE() );',
        '  var resistance = friction.OR( will.NEGATE() );',
        '  var rate = resistance.OR( inertia );',
        '',
        '  result = linearExtrapolation(rate.veracity, 0.3, 1, -.8, 0);',
        '}',
        'result;'
	].join('\n');

    effect(i['Data']['Interpolation rate'].index).expression = interpolationRateExp;

    var overlapExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var weight = fx(' + i['Weight'].index + ').value;',
        'var strength = fx(' + i['Strength'].index + ').value;',
        'var will = fx(' + i['Will'].index + ').value;',
        'var flexibility = fx(' + i['Flexibility'].index + ').value;',
        'var friction = fx(' + i['Friction'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.1;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  weight = new FuzzyVeracity( weight / 1000 );',
        '  strength = new FuzzyVeracity( strength / 1000 );',
        '  will = new FuzzyVeracity( will / 1000 );',
        '  flexibility = new FuzzyVeracity( flexibility / 1000 );',
        '  friction = new FuzzyVeracity( friction / 1000 );',
        '  ',
        '  flexibility.factor = 2;',
        '  friction.factor = 2;',
        '',
        '  // Compute ratio',
        '  var inertia = weight.OR( strength.NEGATE() );',
        '  var resistance = flexibility.AND( friction );',
        '  resistance.factor = 2;',
        '  resistance = resistance.OR( will.NEGATE() );',
        '  var overlap = resistance.OR(inertia);',
        '',
        '  result = linearExtrapolation(overlap.veracity, 0.72, 1, 0, 1);',
        '}',
        'result;'
	].join('\n');

    effect(i['Data']['Overlap'].index).expression = overlapExp;

    var anticipationQuantityExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var will = fx(' + i['Will'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.15;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  result = linearExtrapolation(will, 0, 100, 0, result);',
        '}',
        'result;'
	].join('\n');

    effect(i['Data']['Anticipation quantity'].index).expression = anticipationQuantityExp;

    var anticipationDurationExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var size = fx(' + i['Size'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.395;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  result = linearExtrapolation(size, 0, 100, 0, .2 );',
        '  result = Math.min(result, 1.2);',
        '}',
        'result;',
        ''
	].join('\n');

    effect(i['Data']['Anticipation duration'].index).expression = anticipationDurationExp;

    var followThroughFlexibilityExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var size = fx(' + i['Size'].index + ').value;',
        'var flexibility = fx(' + i['Flexibility'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.70;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  size = new FuzzyVeracity( size / 1000 );',
        '  flexibility = new FuzzyVeracity( flexibility / 1000 );',
        '  ',
        '  flexibility.factor = 2;',
        '  ',
        '  var flex = flexibility.AND( size );',
        '  result = linearExtrapolation(flex.veracity, 0, 0.03, 0, 2);',
        '}',
        'result;',
        ''
	].join('\n');

    effect(i['Data']['Follow through flexibility'].index).expression = followThroughFlexibilityExp;

    var followThroughDurationExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var weight = fx(' + i['Weight'].index + ').value;',
        'var strength = fx(' + i['Strength'].index + ').value;',
        'var will = fx(' + i['Will'].index + ').value;',
        'var friction = fx(' + i['Friction'].index + ').value;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.388;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic) {',
        '  weight = new FuzzyVeracity( weight / 1000 );',
        '  strength = new FuzzyVeracity( strength / 1000 );',
        '  will = new FuzzyVeracity( will / 1000 );',
        '  friction = new FuzzyVeracity( friction / 1000 );',
        '  ',
        '  // Compute ratio',
        '  var damping = weight.OR( strength );',
        '  var resistance = friction.OR( will );',
        '  damping = resistance.OR( damping );',
        '  var duration = damping.NEGATE();',
        '',
        '  result = linearExtrapolation(duration.veracity, 0.55, 1, 0, 1);',
        '}',
        'result;'
	].join('\n');

    effect(i['Data']['Follow through duration'].index).expression = followThroughDurationExp;
    
    var slowDownRatioExp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== MAIN PARAMETERS ===>',
        '',
        'var fx = thisProperty.propertyGroup();',
        'var weight = fx(' + i['Weight'].index + ').value;',
        'var strength = fx(' + i['Strength'].index + ').value;',
        'var will = fx(' + i['Will'].index + ').value;',
        'var flexibility = fx(' + i['Flexibility'].index + ').value;',
        'var friction = fx(' + i['Friction'].index + ').value;',
        'var bounce = fx(' + i['Follow through']['Bounce'].index  +').value == 1;',
        'var useFuzzyLogic = fx(' + i['Performance']['Disable general parameters'].index + ').value == 0;',
        '',
        'var result = 0.60;',
        '',
        '// <=== FUNCTIONS ===>',
        '',
        fuzzyLib,
        '',
        '// <=== DO IT ===>',
        '',
        'if (useFuzzyLogic && !bounce) {',
        '  weight = new FuzzyVeracity( weight / 1000 );',
        '  strength = new FuzzyVeracity( strength / 1000 );',
        '  will = new FuzzyVeracity( will / 1000 );',
        '  friction = new FuzzyVeracity( friction / 1000 );',
        '  flexibility = new FuzzyVeracity(flexibility / 1000);',
        '  ',
        '  friction.factor = 2;',
        '   will.factor = 2;',
        '   flexibility.factor = 3;',
        '  ',
        '  var strong = strength.AND( will );',
        '  var slowDown = strong.OR( friction );',
        '  slowDown = slowDown.AND( weight );',
        '  slowDown = slowDown.AND( flexibility );',
        '',
        '  result = linearExtrapolation(slowDown.veracity, 0, 1, 0, 65);',
        '}',
        'else if (bounce) result = 0;',
        'result;'
	].join('\n');

    effect(i['Data']['Slow down ratio'].index).expression = slowDownRatioExp;

    var linearizeExp = [DuAEExpression.Id.KLEANER,
        'var weight = thisProperty.propertyGroup()(' + i['Weight'].index + ').value;',
	    '(100-weight)/100;'
	].join('\n');

    effect(i['Data']['Linearize'].index).expression = linearizeExp;

    // Setup the main expression

    var exp = [DuAEExpression.Id.KLEANER,
        '',
        '// <=== ADVANCED PARAMETERS ===>',
        '',
        'var fx = thisComp.layer("' + ctrlLayer.name + '").effect("' + effect.name + '");',
        'var anticipationCustomQuantity = fx(' + i['Anticipation']['Anticipation'].index + ').value;',
        'var anticipationCustomDuration = fx(' + i['Anticipation']['Duration'].index + ').value;',
        'var motionInterpolationRatio = fx(' + i['Motion interpolation']['Motion interpolation'].index + ').value;',
        'var motionUseAETrajectory = fx(' + i['Motion interpolation']['Use Ae spatial trajectory'].index + ').value;',
        'var customOverlap = fx(' + i['Overlap']['Overlap'].index + ').value;',
        'var fThroughCustomFlexibility = fx(' + i['Follow through']['Flexibility'].index + ').value;',
        'var fThroughCustomDuration = fx(' + i['Follow through']['Duration'].index + ').value;',
        'var bounce = fx(' + i['Follow through']['Bounce'].index + ').value;',
        'var fThroughAmplification = fx(' + i['Follow through']['Amplification'].index + ').value;',
        'var customSoftBody = fx(' + i['Soft body']['Flexibility'].index + ').value;',
        'var randomness = fx(' + i['Randomness']['Randomness'].index + ').value;',
        'var disableSimulation = fx(' + i['Performance']['Always disable simulations'].index + ').value;',
        'var timePrecision = fx(' + i['Performance']['Time precision'].index + ').value;',
        'var valuePrecision = fx(' + i['Performance']['Value precision'].index + ').value;',
        'var useMinLimit = fx(' + i['Limits']['Use minimum limit'].index + ').value;',
        'var useMaxLimit = fx(' + i['Limits']['Use maximum limit'].index + ').value;',
        'var minLimit = fx(' + i['Limits']['Minimum limit'].index + ').value;',
        'var maxLimit = fx(' + i['Limits']['Maximum limit'].index + ').value;',
        'var limitSoftness = fx(' + i['Limits']['Limit softness'].index + ').value;',
        '',
        '// <=== VALUES ===>',
        '',
        'var zeroVal = zero();',
        'var result = value;',
        'var interpolationRate = 0.725;',
        '',
        '// <=== GENERAL FUNCTIONS ===>',
        '',
        DuAEExpression.Library.get([
            "cbrt",
            "zero",
            "addNoise",
            "isAfterLastKey",
            "getNextKey",
            "getPrevKey",
            "getNextStopKey",
            "getPrevStartKey",
            "isStill",
            "isSpatial",
            "isKeyTop",
            "getPropWorldSpeed",
            "getPropWorldVelocity",
            "getPropWorldValue",
            "getLayerWorldPos",
            "gaussianInterpolation",
            "bezierInterpolation",
            "gaussianRateToBezierPoints",
            "limit"
        ]),
        '',
        '// <=== BEHAVIOR FUNCTIONS ===>',
        '',
        'function weightedInterpolation(t, tMin, tMax, value1, value2, gaussianRate, bezierRate) {',
        '  if (bezierRate >= 1) return linear(t, tMin, tMax, value1, value2);',
        '  ',
        '  var g = gaussianInterpolation(t, tMin, tMax, value1, value2, gaussianRate );',
        '  if (bezierRate <= 0) return g; ',
        '  ',
        '  var b = bezierInterpolation( t, tMin, tMax, value1, value2, [1-bezierRate, 0, bezierRate, 1]);',
        '  return linear(linearRate, 0, 1, g, b);',
        '}',
        '',
        'function mainMotion(t, gaussianRate, bezierRate, slowDown, useAETrajectory) {',
        '  if (numKeys < 2) return zeroVal;',
        '  var nKey = getNextKey(t, thisProperty);',
        '  if (!nKey) return zeroVal;',
        '  var pKey = getPrevKey(t, thisProperty);',
        '  if (!pKey) return zeroVal;',
        '',
        '  if (useAETrajectory && isSpatial()) return mainTrajectoryInterpolation(t, gaussianRate, bezierRate, slowDown);',
        '  ',
        '  return mainValueInterpolation(t, gaussianRate, bezierRate, slowDown);',
        '}',
        '',
        'function mainValueInterpolation(t, gaussianRate, bezierRate, slowDown) {',
        '  ',
        '  var nKey = getNextKey(t, thisProperty);',
        '  var pKey = getPrevKey(t, thisProperty);',
        '  ',
        '  // For each axis',
        '  var r = value;',
        '  var m = r instanceof Array;',
        '  if (!m) r = [r];',
        '  ',
        '  for ( var axis = 0; axis < r.length; axis++ ) {',
        '    ',
        '    // Values',
        '    var currentValue = value;',
        '    var nValue = nKey.value;',
        '    var pValue = pKey.value;',
        '    if (m) {',
        '      currentValue = currentValue[axis];',
        '      nValue = nValue[axis];',
        '      pValue = pValue[axis];',
        '    }',
        '    ',
        '    // Times',
        '    var nTime = nKey.time;',
        '    var pTime = pKey.time;',
        '    ',
        '    // 4 cases : both keys are a summit, or each one is, or none.',
        '    var pKeyTop = isKeyTop(pKey, axis);',
        '    var nKeyTop = isKeyTop(nKey, axis);',
        '    ',
        '    // Check if we can stop (we\'re still moving after the next key)',
        '    // i.e. there\'s no follow through later',
        '    var stop = slowDown >= 1;',
        '    if (!stop) stop = nKey.index < numKeys && !isStill(nKey.time + thisComp.frameDuration, threshold = .01, axis);',
        '',
        '    if (stop && nKeyTop && pKeyTop) {',
        '      r[axis] = weightedInterpolation(t, pTime, nTime, pValue, nValue, gaussianRate, bezierRate) - currentValue;',
        '      continue;',
        '    }',
        '    ',
        '    // Prepare bezier values for continuous keyframes',
        '    // Try to be as close as possible to the gaussian interpolation',
        '    var bPoints = gaussianRateToBezierPoints( gaussianRate );',
        '    var sO = bPoints[0];',
        '  	var sOV = bPoints[1];',
        '    var sI = bPoints[2];',
        '  	var sIV = bPoints[3];',
        '  	if (!pKeyTop) {',
        '  	  var prevKey = key(pKey.index - 1);',
        '  		var prevVal = prevKey.value;',
        '  		if (m) prevVal = prevVal[axis];',
        '  		sOV = (pValue - prevVal) / (nValue - prevVal);',
        '  		sO = .33;',
        '  	}',
        '  	if (!nKeyTop) {',
        '  	  var nextKey = key(nKey.index + 1);',
        '  		var nextVal = nextKey.value;',
        '  		if (m) nextVal = nextVal[axis];',
        '  		sIV = (nValue - nValue) / (nextVal - nValue);',
        '  		sI = .66;',
        '  	}',
        '  	else if (!stop) {',
        '  	  // end speed',
        '  	  sIV = slowDown/2+.5;',
        '  	}',
        '  	r[axis] = bezierInterpolation(t, pTime, nTime, pValue, nValue, [sO, sOV, sI, sIV]) - currentValue;',
        '  }',
        '',
        '  if (m) return r;',
        '  else return r[0];',
        '}',
        '',
        'function mainTrajectoryInterpolation(t, gaussianRate, bezierRate, slowDown) {',
        '  if (isStill(t)) return zeroVal;',
        '  ',
        '  var sKey = getPrevStartKey(t);',
        '  var eKey = getNextStopKey(t);',
        '  ',
        '  var stop = slowDown >= 1;',
        '  ',
        '  if (stop) return valueAtTime(',
        '    weightedInterpolation(t, sKey.time, eKey.time, sKey.time, eKey.time, gaussianRate, bezierRate)',
        '    ) - value;',
        '    ',
        '  // Try to be as close as possible to the gaussian interpolation',
        '  var bPoints = gaussianRateToBezierPoints( gaussianRate );',
        '  bPoints[3] = slowDown/2+.5;',
        '  return valueAtTime(',
        '    bezierInterpolation(t, sKey.time, eKey.time, sKey.time, eKey.time, bPoints)',
        '    ) - value;',
        '}',
        '',
        'function anticipation(duration, quantity, rate, linearRate) {',
        '  var anticipation = zeroVal;',
        '  // Check values',
        '  if (duration == 0) return anticipation;',
        '  if (quantity == 0) return anticipation;',
        '  // We need at least two keyframes, and can\'t be after the last one',
        '	if (isAfterLastKey()) return anticipation;',
        '	if (numKeys < 2) return anticipation;',
        '',
        '  // Check if an anticipation is needed',
        '	var nextKey = getNextKey(time, thisProperty);',
        '	var anticipationKey = nextKey;',
        '	if (!isStill(anticipationKey.time - 0.1, valuePrecision)) {',
        '		anticipationKey = getPrevKey(time, thisProperty);',
        '		if (!isStill(anticipationKey.time - 0.1, valuePrecision)) return anticipation;',
        '	}',
        '	if (anticipationKey.index == numKeys) return anticipation;',
        '',
        '	var anticipationMiddle = anticipationKey.time;',
        '	var anticipationStart = anticipationMiddle - anticipationDuration;',
        '	var anticipationEnd = key(anticipationKey.index + 1).time;',
        '	var startValue = anticipation;',
        '	var midValue = (-valueAtTime(anticipationMiddle + anticipationDuration) + anticipationKey.value) * anticipationQuantity / 2;',
        '	var endValue = anticipation;',
        '',
        '	if (time < anticipationStart) {',
        '		return anticipation;',
        '	} else if (time < anticipationMiddle) {',
        '		if (value instanceof Array) {',
        '			for (var i = 0; i < value.length; i++) {',
        '				anticipation[i] = weightedInterpolation(time, anticipationStart, anticipationMiddle, startValue[i], midValue[i], rate, linearRate);',
        '			}',
        '			return anticipation;',
        '		} else {',
        '			return weightedInterpolation(time, anticipationStart, anticipationMiddle, startValue, midValue, rate, linearRate);',
        '		}',
        '	} else if (time <= anticipationEnd) {',
        '		if (value instanceof Array) {',
        '			for (var i = 0; i < value.length; i++) {',
        '				anticipation[i] = weightedInterpolation(time, anticipationMiddle, anticipationEnd, midValue[i], endValue[i], rate, linearRate);',
        '			}',
        '			return anticipation;',
        '		} else {',
        '			return weightedInterpolation(time, anticipationMiddle, anticipationEnd, midValue, endValue, rate, linearRate);',
        '		}',
        '	} else {',
        '		return anticipation;',
        '	}',
        '}',
        '',
        'function followThrough(flexibility, duration, slowDown, bounce, simulate, overlapDuration, anticipationDuration) {',
        '  ',
        '  var propSpeed = length(velocity);',
        '  if (simulate) propSpeed = getPropWorldSpeed(time - overlapDuration, thisProperty);',
        '	if (propSpeed < .001) return followThroughAtTime(time - overlapDuration, flexibility, duration, slowDown, bounce, simulate);',
        '	',
        '	//need to get back in time get the last follow-through value to fade it',
        '	var fThrough = zeroVal;',
        '',
        '	var t = time;',
        '	while (t > 0) {',
        '		t = t - thisComp.frameDuration;',
        '		if (simulate) propSpeed = getPropWorldSpeed(t - overlapDuration, thisProperty);',
        '		else propSpeed = length(velocityAtTime(t));',
        '		if (propSpeed < .001) {',
        '			fThrough = followThroughAtTime(t - overlapDuration, flexibility, duration, slowDown, bounce, simulate);',
        '			break;',
        '		}',
        '	}',
        '',
        '	return easeIn(time, t, t + anticipationDuration * 2, fThrough, zeroVal);',
        '}',
        '',
        'function followThroughAtTime(t, flexibility, duration, slowDown, bounce, simulate) {',
        '	var fThrough = zeroVal;',
        '',
        '	//checks',
        '	if (flexibility == 0) return fThrough;',
        '	var elasticity = 1/flexibility;',
        '	if (duration == 0) return fThrough;',
        '	var damping = 1/duration;',
        '	if (slowDown == 1) return fThrough;',
        '	',
        '	var propSpeed;',
        '	',
        '	if (!simulate) {',
        '		if (numKeys < 2) return fThrough;',
        '		if (nearestKey(t).index == 1) return fThrough;',
        '		propSpeed = length(velocityAtTime(t));',
        '		if (propSpeed >= .001) return fThrough;',
        '	} else {',
        '		propSpeed = getPropWorldSpeed(t, thisProperty);',
        '		if (propSpeed >= .001) return fThrough;',
        '	}',
        '',
        '	//check state and time',
        '	var fThroughStart = 0;',
        '	var fThroughTime = 0;',
        '',
        '	if (simulate) {',
        '		var speedI = getPropWorldSpeed(t, thisProperty);',
        '		var i = t;',
        '		//search for the time when the layer last moved',
        '		while (speedI < valuePrecision && i > 0) {',
        '			i = i - thisComp.frameDuration / timePrecision;',
        '			speedI = getPropWorldSpeed(i, thisProperty);',
        '		}',
        '		fThroughStart = i;',
        '	} else {',
        '		//follow through starts at previous key',
        '		var fThroughKey = getPrevKey(t, thisProperty);',
        '		fThroughStart = fThroughKey.time;',
        '	}',
        '',
        '	if (fThroughStart == 0) return fThrough;',
        '',
        '	fThroughTime = t - fThroughStart;',
        '',
        '	//from velocity',
        '	if (simulate) fThrough = getPropWorldVelocity(fThroughStart - thisComp.frameDuration, thisProperty ) / 2;',
        '	else {',
        '	  ',
        '	  fThrough = velocityAtTime(fThroughStart - thisComp.frameDuration);',
        '	  fThrough *= 1-Math.cbrt(slowDown);',
        '	}',
        '',
        '',
        '	if (bounce) {',
        '		var cycleDamp = Math.exp(fThroughTime * damping * .1);',
        '		var damp = Math.exp(fThroughTime * damping) / (elasticity / 2);',
        '		var cycleDuration = 1 / (elasticity * 2);',
        '		//round to whole frames for better animation',
        '		cycleDuration = Math.round(timeToFrames(cycleDuration));',
        '		cycleDuration = framesToTime(cycleDuration);',
        '		var midDuration = cycleDuration / 2;',
        '		var maxValue = fThrough * midDuration;',
        '		//check which cycle it is and cycvarime',
        '		var cycvarime = fThroughTime;',
        '		// the number of cycles where we "cheat" which are rounded to two frames',
        '		var numEndCycles = 1;',
        '		while (cycvarime > cycleDuration) {',
        '			cycvarime = cycvarime - cycleDuration;',
        '			cycleDuration = cycleDuration / cycleDamp;',
        '			//round everything to whole frames for better animation',
        '			cycleDuration = Math.round(timeToFrames(cycleDuration));',
        '			//this is where we cheat to continue to bounce on cycles < 2 frames',
        '			if (cycleDuration < 2) {',
        '				cycleDuration = 2;',
        '				numEndCycles++;',
        '			}',
        '			cycleDuration = framesToTime(cycleDuration);',
        '			midDuration = cycleDuration / 2;',
        '			maxValue = fThrough * midDuration / damp;',
        '			if (numEndCycles > 100 / damping && maxValue < valuePrecision) return zeroVal;',
        '		}',
        '',
        '		if (cycvarime < midDuration) fThrough = bezierInterpolation(cycvarime, 0, midDuration, 0, maxValue, [0, .1, .33, 1]);',
        '		else fThrough = bezierInterpolation(cycvarime, midDuration, cycleDuration, maxValue, 0, [1 - .33, 0, 1, .9]);',
        '	} else {',
        '		// damping ratio',
        '		var damp = Math.exp(fThroughTime * damping);',
        '		// sinus evolution ',
        '		var sinus = elasticity * fThroughTime * 2 * Math.PI;',
        '		//sinus',
        '		sinus = Math.sin(sinus);',
        '		// elasticity',
        '		sinus = .3 / elasticity * sinus;',
        '		// damping',
        '		sinus = sinus / damp;',
        '		if (Math.abs(sinus) < .001 / 100) return 0;',
        '		// result',
        '		fThrough = fThrough * sinus;',
        '',
        '		if (.001 > 0) {',
        '			fThrough = fThrough * (1 - propSpeed / valuePrecision);',
        '		}',
        '	}',
        '',
        '	if (bounce) {',
        '		var prevValue = valueAtTime(fThroughStart - thisComp.frameDuration);',
        '		var startValue = valueAtTime(fThroughStart);',
        '		if (value instanceof Array) {',
        '			for (var i = 0; i < prevValue.length; i++) {',
        '				if (prevValue[i] > startValue[i]) fThrough[i] = Math.abs(fThrough[i]);',
        '				if (prevValue[i] < startValue[i]) fThrough[i] = -Math.abs(fThrough[i]);',
        '			}',
        '		} else {',
        '			if (prevValue > startValue) fThrough = Math.abs(fThrough);',
        '			if (prevValue < startValue) fThrough = -Math.abs(fThrough);',
        '		}',
        '	}',
        '',
        '	if (simulate) {',
        '		if (thisProperty !== position) {',
        '			fThrough = fThrough + getLayerWorldPos(time, thisLayer);',
        '			fThrough = thisLayer.fromWorld(fThrough) - thisLayer.anchorPoint;',
        '		} else if (thisLayer.hasParent) {',
        '			fThrough = fThrough + getLayerWorldPos(time, thisLayer.parent);',
        '			fThrough = thisLayer.parent.fromWorld(fThrough) - thisLayer.parent.anchorPoint;',
        '		}',
        '	}',
        '',
        '	return fThrough;',
        '}',
        '',
        'function overlap(overlapDuration, flexibility, t) {',
        '',
        '	var isThisPosition = thisProperty === position;',
        '	',
        '	if (isThisPosition && !hasParent) return zeroVal;',
        '	',
        '	if (typeof t === \'undefined\') t = time;',
        '	',
        '	// The position before overlapDuration',
        '	var ol = getPropWorldValue(t - overlapDuration, thisProperty);',
        '	',
        '	// A ratio : velocity of the motion / distance between parent',
        '	var motionRatio = 1;',
        '	var originalDistance = length(valueAtTime(0));',
        '	var motionVelocity = length(getPropWorldValue(t-thisComp.frameDuration/timePrecision, thisProperty), getPropWorldValue(t, thisProperty));',
        '	motionRatio = ease(motionVelocity, 0, originalDistance, 1, 1-flexibility);',
        '',
        '	//pull towards the anchor position (or the parent for the position)',
        '  if (isThisPosition) {',
        '  	var prevParentWorldPos = getLayerWorldPos(t - overlapDuration, parent);',
        '  	ol = (ol - prevParentWorldPos) * motionRatio + prevParentWorldPos;',
        '  }',
        '	else {',
        '	  var prevAnchorWorldPos = getPropWorldValue(t - overlapDuration, anchorPoint);',
        '	  ol = (ol - prevAnchorWorldPos) * motionRatio + prevAnchorWorldPos;',
        '	}',
        '	',
        '	',
        '	// Convert back to local coordinates',
        '	if (isThisPosition) ol = parent.fromWorld(ol);',
        '	else ol = thisLayer.fromWorld(ol);',
        '',
        '	return ol - value;',
        '}',
        '',
        '// Logic results',
        '',
        'var interpolationRate = fx(' + i['Data']['Interpolation rate'].index + ').value;',
        'var overlapDuration = fx(' + i['Data']['Overlap'].index + ').value;',
        'var anticipationQuantity = fx(' + i['Data']['Anticipation quantity'].index + ').value;',
        'var anticipationDuration = fx(' + i['Data']['Anticipation duration'].index + ').value;',
        'var fThroughFlexibility = fx(' + i['Data']['Follow through flexibility'].index + ').value;',
        'var fThroughDuration = fx(' + i['Data']['Follow through duration'].index + ').value;',
        'var slowDown = fx(' + i['Data']['Slow down ratio'].index + ').value;',
        'var linearRate = fx(' + i['Data']['Linearize'].index + ').value;',
        'var softBodyFexibility = fThroughFlexibility;',
        '',
        '// ADJUSTMENTS',
        '',
        '// random!',
        'seedRandom(0, true);',
        '',
        '// anticipation',
        'anticipationDuration *= anticipationCustomDuration/100;',
        'anticipationQuantity *= anticipationCustomQuantity/100;',
        'motionInterpolationRatio /= 100;',
        'motionUseAETrajectory = motionUseAETrajectory == 1;',
        'fThroughFlexibility *= fThroughCustomFlexibility/100;',
        'fThroughFlexibility = addNoise( fThroughFlexibility, randomness );',
        'fThroughDuration *= fThroughCustomDuration/100;',
        'fThroughDuration = addNoise( fThroughDuration, randomness );',
        'if (fThroughFlexibility < .01) fThroughFlexibility = 0;',
        'if (fThroughDuration < .01) fThroughDuration = 0;',
        'var doFollowThrough = fThroughFlexibility != 0 && fThroughDuration != 0;',
        'if (!doFollowThrough) slowDown = 1;',
        'bounce = bounce == 1;',
        'fThroughAmplification /= 100;',
        'softBodyFexibility *= customSoftBody/100;',
        'var simulate = disableSimulation == 0;',
        'if (simulate)',
        '{',
        '  // Check if simulation is possible, and needed',
        '  // disable if :',
        '  // - prop is not spatial, or position has keyframes',
        '  if (!isSpatial()) simulate = false;',
        '  else if (thisProperty === position && thisProperty.numKeys > 0) simulate = false;',
        '  // - custom soft body and custom overlap are 0',
        '  else if (customSoftBody == 0 && customOverlap == 0) simulate = false;',
        '  // - overlap is 0 and (!doFollowThrough)',
        '  else if (overlapDuration == 0 && !doFollowThrough) simulate = false;',
        '  // - No parent = no simulation on the position',
        '  else if (thisProperty === position && !thisLayer.hasParent) simulate = false;',
        '  ',
        '  // Adjust the flexibility and other parameters in case of simulation',
        '  //adjust elasticity based on flexibility',
        '  if (simulate) {',
        '    ',
        '    if (thisProperty === position) overlapDuration *= customOverlap/100;',
        '    else overlapDuration *= softBodyFexibility;',
        '    ',
        '  	//get the distance from anchor ratio',
        '  	var distanceRatio = 1;',
        '  	if (thisProperty !== position)',
        '  	{',
        '  	  distanceRatio = length(valueAtTime(0), anchorPoint) / (thisLayer.width / 2);',
        '  	  //adjust with soft-body flexibility',
        '  	  distanceRatio *= softBodyFexibility;',
        '  	}',
        '  ',
        '	  fThroughFlexibility = fThroughFlexibility * distanceRatio;',
        '	  fThroughDuration = fThroughDuration * distanceRatio;',
        '	  overlapDuration = overlapDuration * distanceRatio;',
        '	  ',
        '	  overlapDuration = addNoise( overlapDuration, randomness );',
        '  }',
        '}',
        '// Disable overlap without simulation',
        'if (!simulate) overlapDuration = 0;',
        '',
        'if (motionInterpolationRatio > 0)',
        '{',
        '  result += mainMotion(time, interpolationRate, linearRate, slowDown, motionUseAETrajectory) * motionInterpolationRatio;',
        '}',
        'result += anticipation(anticipationDuration, anticipationQuantity, interpolationRate, linearRate);',
        'if (overlapDuration > 0)',
        '{',
        '  result += overlap(overlapDuration, fThroughFlexibility);',
        '}',
        'if (doFollowThrough)',
        '{',
        '    var ft = followThrough(fThroughFlexibility, fThroughDuration, slowDown, bounce, simulate, overlapDuration, anticipationDuration);',
        '    ft *= linear(motionInterpolationRatio, 0, 1, 1, 0.5);',
        '    ft *= fThroughAmplification;',
        '    result += ft;',
        '}',
        'if (!useMinLimit) minLimit = null;',
        'if (!useMaxLimit) maxLimit = null;',
        'result = limit(result, minLimit, maxLimit, limitSoftness);',
        'result;',//*/
        ''
	].join('\n');

    // Clean keyframes and Add expressions
    props.do(function (prop)
    {
        prop = new DuAEProperty(prop);
        if (prop.isProperty())
        {
            // Fix spatial interpolations
            prop.fixSpatialInterpolation();
            // Set Linear
            prop.setInterpolation(KeyframeInterpolationType.LINEAR);
            // Clean keyframes
            prop.cleanKeyframes();
            // Set auto roving
            prop.setRoving();
            // Set expression
            if (prop.riggable())
                prop.setExpression( exp, false );
        }
        
    });

    DuAE.endUndoGroup("_" + i18n._("Kleaner"));

    return effect;
}

Duik.CmdLib['Automation']["Swink"] = "Duik.Automation.swink()";
Duik.CmdLib['Automation']["Swing"] = "Duik.Automation.swink()";
Duik.CmdLib['Automation']["Blink"] = "Duik.Automation.swink(undefined, true)";
/**
 * Adds the <i>Swink</i> effect and expression to the properties.
 * The <i>Swink</i> (Swing and Blink) makes the property swing between two values, with optional controls on the interpolation.
 * @param {PropertyBase[]|DuAEProperty[]|DuList|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 * @param {boolean} [blink=false] Set to true to set the interpolation to hold by default.
 * @return {DuAEProperty[]} The Swink effects.
 */
Duik.Automation.swink = function(props, blink) {
    blink = def(blink, false);
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return [];

    DuAE.beginUndoGroup( i18n._("Swink"), false);

    DuAEComp.setUniqueLayerNames(undefined, props.first().comp );

    // Apply
    var effects = [];
    var swinkName = ' | ' + i18n._("Swink");

    props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;
        var layer = prop.layer;

        // Add effect
        var d = prop.dimensions();
        
        var pe = null;
        if (d == 1) pe = Duik.PseudoEffect.ONED_SWINK;
        else if (d == 2) pe = Duik.PseudoEffect.TWOD_SWINK;
        else if (d == 3) pe = Duik.PseudoEffect.THREED_SWINK;
        else if (d == 4) pe = Duik.PseudoEffect.COLOR_SWINK;
        else return;

        // The indices
        var effect = pe.apply(layer, prop.name + swinkName);
        var i = pe.props;

        // The expression
        var exp = [ 
            'var AValue = fx(' + i['A'].index + ').value;',
            'var BValue = fx(' + i['B'].index + ').value;',
            'var frequencyProp = fx(' + i['Frequency'].index + ');',
            'var interpolationValue = fx(' + i['Interpolation']['Mode'].index + ').value;',
            'var rateValue = fx(' + i['Interpolation']['Rate'].index + ').value;',
            'var offsetValue = fx(' + i['Cycle offset'].index + ').value;',
            'var ratioValue = fx(' + i['A/B Ratio'].index + ').value;',
            'var plateauValue = fx(' + i['Plateau'].index + ').value;'
        ].join('\n');

        if (d == 4) exp += [
            'var colorMode = fx(' + i['Color Mode'].index + ').value;',
            'var colorspace = fx(' + i['Interpolation']['Colorspace'].index + ').value'
        ].join('\n');

        exp += [
            '',
            'var result = value;',
            'var frequencyValue = frequencyProp.value;',
            '',
            DuAEExpression.Library.get([
                'bezierInterpolation',
                'gaussianInterpolation',
                'logInterpolation',
                'expInterpolation',
                'integrateLinearKeys',
                'interpolateColor',
                'multSets'
            ]),
            '',
            'function blink( A, B, frequency, offset, ratio, t ) {',
            '  if (typeof frequency === \'undefined\') frequency = 1.0;',
            '  if (typeof offset === \'undefined\') offset = 0.0;',
            '  if (typeof ratio === \'undefined\') ratio = 0.5;',
            '  if (typeof t === \'undefined\') t = time;',
            '',
            '  var phase = 1/frequency;',
            '  ',
            '  var currentTime = (t+offset)%phase;',
            '  var ADuration = phase*ratio;',
            '  ',
            '	if (currentTime > ADuration) return B;',
            '	return A;',
            '}',
            '',
            'function swing( A, B, frequency, offset, ratio, plateau, interpolationMethod, t ) {',
            '  if (typeof frequency === \'undefined\') frequency = 1.0;',
            '  if (typeof offset === \'undefined\') offset = 0.0;',
            '  if (typeof ratio === \'undefined\') ratio = 0.5;',
            '  if (typeof plateau === \'undefined\') plateau = 0.0;',
            '  if (typeof interpolationMethod === \'undefined\') interpolationMethod = ease;',
            '  if (typeof t === \'undefined\') t = time;',
            '  ',
            '  var phase = 1/frequency;',
            '  ',
            '  var currentTime = (t+offset)%phase;',
            '  var ADuration = phase*ratio;',
            '  var APlateau = ADuration*plateau;',
            '  var BDuration = phase*(1-ratio);',
            '  var BPlateau = BDuration*plateau;',
            '  ',
            '  // A to B',
            '  if (currentTime < ADuration-APlateau) return interpolationMethod(currentTime, 0, ADuration-APlateau, A, B);',
            '  // B plateau',
            '  if (currentTime >= ADuration-APlateau && currentTime < ADuration) return B;',
            '  // B to A',
            '  if (currentTime >= ADuration && currentTime < phase-BPlateau) return interpolationMethod(currentTime, ADuration, phase-BPlateau, B, A);',
            '  // A plateau ',
            '  return A;',
            '}',
            '',
            'if (frequencyValue > 0) {'
        ].join('\n');

        if (d == 4) exp += [
            '// Adjust color values',
            'result = [0,0,0,0];',
            'if (colorMode == 2) {',
            'AValue += value;',
            'BValue += value;',
            '}',
            'else if (colorMode == 3) {',
            'AValue = multSets(AValue, value);',
            'BValue = multSets(BValue, value);',
            '}',
            'else if (colorMode == 4) {',
            'AValue = multSets(AValue, value);',
            'BValue += value;',
            '}'
        ].join('\n');

        exp += [
            '  offsetValue = offsetValue/100/frequencyValue;',
            '  ratioValue /= 100;',
            '  plateauValue /= 100;',
            '  var t = integrateLinearKeys( frequencyProp );',
            '  // Hold (Blink)',
            '  if (interpolationValue == 1) result += blink( AValue, BValue, 1, offsetValue, ratioValue, t);',
            '  else {',
            '    var i = linear;',
            '    // Smooth',
            '    if (interpolationValue == 3) i = function (t, tMin, tMax, value1, value2) { return bezierInterpolation(t, tMin, tMax, value1, value2, [rateValue/10.0, 0.0, 1-rateValue/10.0, 1.0]); };',
            '    // Natural',
            '    if (interpolationValue == 4) i = function (t, tMin, tMax, value1, value2) { return gaussianInterpolation(t, tMin, tMax, value1, value2, linear(rateValue, 0, 10, -1, 1)); };',
            '    // Slow Down',
            '    if (interpolationValue == 5) i = function (t, tMin, tMax, value1, value2) { return logInterpolation(t, tMin, tMax, value1, value2, rateValue*50*frequencyValue); };',
            '    // Speed up',
            '    if (interpolationValue == 6) i = function (t, tMin, tMax, value1, value2) { return expInterpolation(t, tMin, tMax, value1, value2, rateValue*frequencyValue); };',
        ].join('\n');

        if (d== 4) exp += [
            'var interpolator = function(t, tMin, tMax, value1, value2) {',
            '	return interpolateColor(t, colorspace-1, tMin, tMax, value1, value2, i);',
            '}'
        ].join('\n');
        else exp += 'var interpolator = i;';


        exp += [
            '',
            '  result += swing( AValue, BValue, 1, offsetValue, ratioValue, plateauValue, interpolator, t);',
            '  }',
            '}',
            '',
            'result;'
        ].join('\n');

        prop.setExpression(
            DuAEExpression.Id.SWINK + '\nvar fx = effect("' + effect.name + '");\n' + exp,
            false
        );

        // Set values
        if (blink) effect(i['Interpolation']['Mode'].index).setValue(1);
        if (d != 4) {
            var v = prop.value( true )/4;
            effect(i['A'].index).setValue( - v );
            effect(i['B'].index).setValue( v );
        }
        else {
            var v = prop.value( true );
            effect(i['A'].index).setValue( v );
            effect(i['B'].index).setValue( v );
            effect(i['Color Mode'].index).setValue( 4 );
        }
       

        effects.push(new DuAEProperty(effect));
    });

    DuAE.endUndoGroup( i18n._("Swink"));

    return effects;
}

Duik.CmdLib['Automation']["Wiggle"] = "Duik.Automation.wiggle()";
/**
 * Adds a random but smooth animation to the selected properties.
 * @param {Bool} [separateDimensions=false] Use one value for each dimension/channel.
 * @param {Bool} [individualControls=false] Use one control for each of the properties.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.wiggle = function(separateDimensions, individualControls, props) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return [];

    separateDimensions = def ( separateDimensions, false );
    individualControls = def ( individualControls, false );

    DuAE.beginUndoGroup( i18n._("Wiggle"), false);

    DuAEComp.setUniqueLayerNames(undefined, props.first().comp );

    var effect = null;
    var pe = null;
    var i = null;

    var layers = DuAEComp.unselectLayers();
    props.do(function(prop)
    {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;
        var layer = prop.layer;
        var dimensions = prop.dimensions();
        var comp = prop.comp;

        // Create effect
        if (effect == null || individualControls)
        {
            var effectName = i18n._("Wiggle");
            if (individualControls || props.length() == 1) effectName = prop.name + " | " + effectName;

            if (!separateDimensions && dimensions > 1) pe = Duik.PseudoEffect.MULTI_WIGGLE;
            else if (dimensions == 1) pe = Duik.PseudoEffect.ONED_WIGGLE;
            else if (dimensions == 2) pe = Duik.PseudoEffect.TWOD_WIGGLE;
            else if (dimensions == 3) pe = Duik.PseudoEffect.THREED_WIGGLE;
            else if (dimensions == 4) pe = Duik.PseudoEffect.COLOR_WIGGLE;
            else return;

            effect = pe.apply(layer, effectName);
            effect = new DuAEProperty(effect);

            // Set default values
            i = pe.props;
            effect.prop( i['Loop duration (s)'].index ).setValue( comp.duration );
            effect.prop( i['Details']['Random Seed'].index ).setValue( DuMath.random(0,9999) + layer.index );
        }

        // Check the comp link
        var sameComp = effect.comp.name == comp.name;

        var effectLink = "var fx = " + effect.expressionLink(sameComp);
        if (!separateDimensions && dimensions > 1)
	    {
            prop.getProperty().expression = DuAEExpression.Id.WIGGLE + '\n' + effectLink + '\n' +
				'var freq = fx(' + i['Frequency'].index + ');\n' +
				'var amp = fx(' + i['Amplitude'].index + ').value;\n' +
				'var linked = fx(' + i['Link dimensions'].index + ').value;\n' +
				'var loop = fx(' + i['Loop duration (s)'].index + ').value;\n' +
				'var complexity = fx(' + i['Details']['Complexity (octaves)'].index + ').value;\n' +
				'var multiplier = fx(' + i['Details']['Multiplier'].index + ').value;\n' +
				'var seed = fx(' + i['Details']['Random Seed'].index + ').value;\n' +
                'var layerSeed = fx(' + i['Details']['One seed per layer'].index + ').value;\n' + 
                '\n' +
                DuAEExpression.Library.get(['integrateLinearKeys']) + '\n' + 
                '\n' +
                'var result = value;\n' +
                'if (fx.active) {\n' + 
                'if (layerSeed) seed += index;\n' + 
                'seedRandom(seed);\n' + 
                'var doLoop = freq.numKeys < 2;\n' + 
                'if (loop == 0) loop = thisComp.duration;\n' + 
                'var t = time;\n' + 
                'var f = 1;\n' + 
                'if (doLoop) {\n' + 
                '    t = (time % loop)-loop;\n' + 
                '    f = freq.value;\n' + 
                '}\n' + 
                'else {\n' + 
                '    t = integrateLinearKeys( freq );\n' + 
                '}\n' + 
				'var w1 = wiggle(f, amp, complexity, multiplier, t);\n' +
				'var w2 = wiggle(f, amp, complexity, multiplier, t - loop);\n' +
				'var w = w1;\n' +
                'if (doLoop) w = ease(t, -loop,  0, w1, w2);\n' +
				'result = [];\n' +
				'if(linked) while (result.length < value.length) result.push(w[0]);\n' +
				'else result = w;\n' +
				'result += value - valueAtTime(0);\n' +
                '}\n' +
                'result;';
        }
        else if (dimensions == 4)
        {
            prop.getProperty().expression = DuAEExpression.Id.WIGGLE + '\n' + effectLink + '\n' +
				'var freq = fx(' + i['Frequency'].index + ');\n' +
				'var amp = fx(' + i['Amplitude'].index + ').value;\n' +
				'var loop = fx(' + i['Loop duration (s)'].index + ').value;\n' +
				'var complexity = fx(' + i['Details']['Complexity (octaves)'].index + ').value;\n' +
				'var multiplier = fx(' + i['Details']['Multiplier'].index + ').value;\n' +
				'var seed = fx(' + i['Details']['Random Seed'].index + ').value;\n' +
                'var layerSeed = fx(' + i['Details']['One seed per layer'].index + ').value;\n' +
                'var channel = fx(' + i['Channel'].index + ').value;\n' +
                '\n' +
                DuAEExpression.Library.get(['integrateLinearKeys']) + '\n' + 
                '\n' +
                'var result = value;\n' +
                'if (fx.active) {\n' + 
                'if (layerSeed) seed += index;\n' + 
                'seedRandom(seed);\n' + 
                'var doLoop = freq.numKeys < 2;\n' + 
                'if (loop == 0) loop = thisComp.duration;\n' + 
                'var t = time;\n' + 
                'var f = 1;\n' + 
                'if (doLoop) {\n' + 
                '    t = (time % loop)-loop;\n' + 
                '    f = freq.value;\n' + 
                '}\n' + 
                'else {\n' + 
                '    t = integrateLinearKeys( freq );\n' + 
                '}\n' + 
				'var w1 = wiggle(f, amp, complexity, multiplier, t);\n' +
				'var w2 = wiggle(f, amp, complexity, multiplier, t - loop);\n' +
				'var w = w1;\n' +
                'if (doLoop) w = ease(t, -loop,  0, w1, w2);\n' +
				'result = value;\n' +
				'if (channel >= 5) {\n' +
                '    result = rgbToHsl(result);\n' +
                '    w = rgbToHsl(w);\n' +
                '}\n' +
                '// R\n' +
                'if (channel == 1) result = [w[0], result[1], result[2], result[3]];\n' +
                '// G\n' +
                'else if (channel == 2) result = [result[0], w[1], result[2], result[3]];\n' +
                '// B\n' +
                'else if (channel == 3) result = [result[0], result[1], w[2], result[3]];\n' +
                '// A\n' +
                'else if (channel == 4) result = [result[0], result[1], result[2], w[3]];\n' +
                '// H\n' +
                'else if (channel == 5) result = [w[0], result[1], result[2], result[3]];\n' +
                '// S\n' +
                'else if (channel == 6) result = [result[0], w[1], result[2], result[3]];\n' +
                '// L\n' +
                'else if (channel == 7) result = [result[0], result[1], w[2], result[3]];\n' +
                'if (channel >= 5) {\n' +
                '    result = hslToRgb(result);\n' +
                '    w = hslToRgb(w);\n' +
                '}\n' +
				'result += value - valueAtTime(0);\n' +
                '}\n' +
                'result;';
        }
        else if (dimensions == 3)
        {
            prop.getProperty().expression = DuAEExpression.Id.WIGGLE + '\n' + effectLink + '\n' +
                    'var Xfreq = fx(' + i['X']['Frequency'].index + ');\n' +
                    'var Yfreq = fx(' + i['Y']['Frequency'].index + ');\n' +
                    'var Zfreq = fx(' + i['Z']['Frequency'].index + ');\n' +
                    'var Xamp = fx(' + i['X']['Amplitude'].index + ').value;\n' +
                    'var Yamp = fx(' + i['Y']['Amplitude'].index + ').value;\n' +
                    'var Zamp = fx(' + i['Z']['Amplitude'].index + ').value;\n' +
                    'var loop = fx(' + i['Loop duration (s)'].index + ').value;\n' +
                    'var complexity = fx(' + i['Details']['Complexity (octaves)'].index + ').value;\n' +
                    'var multiplier = fx(' + i['Details']['Multiplier'].index + ').value;\n' +
                    'var seed = fx(' + i['Details']['Random Seed'].index + ').value;\n' +
                    'var layerSeed = fx(' + i['Details']['One seed per layer'].index + ').value;\n' + 
                    '\n' +
                    DuAEExpression.Library.get(['integrateLinearKeys']) + '\n' + 
                    '\n' +
                    'var result = value;\n' +
                    'if (fx.active) {\n' + 
                    'if (layerSeed) seed += index;\n' +
                    'seedRandom(seed);\n' +
                    'var doLoop = Xfreq.numKeys < 2 && Yfreq.numKeys < 2 && Zfreq.numKeys < 2;\n' + 
                    'if (loop == 0) loop = thisComp.duration;\n' + 
                    'var tX = time;\n' + 
                    'var tY = time;\n' + 
                    'var tZ = time;\n' + 
                    'var fX = 1;\n' + 
                    'var fY = 1;\n' + 
                    'var fZ = 1;\n' + 
                    'if (doLoop) {\n' + 
                    '    tX = tY = tZ = (time % loop)-loop;\n' + 
                    '    fX = Xfreq.value;\n' + 
                    '    fY = Yfreq.value;\n' + 
                    '    fZ = Zfreq.value;\n' + 
                    '}\n' + 
                    'else {\n' + 
                    '    tX = integrateLinearKeys( Xfreq );\n' + 
                    '    tY = integrateLinearKeys( Yfreq );\n' + 
                    '    tZ = integrateLinearKeys( Zfreq );\n' + 
                    '}\n' + 
                    'var X1 = wiggle(fX,Xamp, complexity, multiplier, tX);\n' +
                    'var Y1 = wiggle(fY,Yamp, complexity, multiplier, tY);\n' +
                    'var Z1 = wiggle(fZ,Zamp, complexity, multiplier, tZ);\n' +
                    'var w1 = [X1[0],Y1[1],Z1[2]];\n' +
                    'var Y2 = wiggle(fX,Yamp, complexity, multiplier, tX - loop);\n' +
                    'var X2 = wiggle(fY,Xamp, complexity, multiplier, tY - loop);\n' +
                    'var Z2 = wiggle(fZ,Zamp, complexity, multiplier, tZ - loop);\n' +
                    'var w2 = [X2[0],Y2[1],Z2[2]];\n' +
                    'var w = w1;\n' +
                    'if (doLoop)  w = ease(tX, -loop,  0, w1, w2);\n' +
                    'result = w + value - valueAtTime(0);\n' +
                    '}\n' +
                    'result;';
        }
        else if (dimensions == 2)
        {
            prop.getProperty().expression = DuAEExpression.Id.WIGGLE + '\n' + effectLink + '\n' +
                    'var Xfreq = fx(' + i['X']['Frequency'].index + ');\n' +
                    'var Yfreq = fx(' + i['Y']['Frequency'].index + ');\n' +
                    'var Xamp = fx(' + i['X']['Amplitude'].index + ').value;\n' +
                    'var Yamp = fx(' + i['Y']['Amplitude'].index + ').value;\n' +
                    'var loop = fx(' + i['Loop duration (s)'].index + ').value;\n' +
                    'var complexity = fx(' + i['Details']['Complexity (octaves)'].index + ').value;\n' +
                    'var multiplier = fx(' + i['Details']['Multiplier'].index + ').value;\n' +
                    'var seed = fx(' + i['Details']['Random Seed'].index + ').value;\n' +
                    'var layerSeed = fx(' + i['Details']['One seed per layer'].index + ').value;\n' + 
                    '\n' +
                    DuAEExpression.Library.get(['integrateLinearKeys']) + '\n' + 
                    '\n' +
                    'var result = value;\n' +
                    'if (fx.active) {\n' + 
                    'if (layerSeed) seed += index;\n' +
                    'seedRandom(seed);\n' +
                    'var doLoop = Xfreq.numKeys < 2 && Yfreq.numKeys < 2;\n' + 
                    'if (loop == 0) loop = thisComp.duration;\n' + 
                    'var tX = time;\n' + 
                    'var tY = time;\n' + 
                    'var fX = 1;\n' + 
                    'var fY = 1;\n' + 
                    'if (doLoop) {\n' + 
                    '    tX = tY = (time % loop)-loop;\n' + 
                    '    fX = Xfreq.value;\n' + 
                    '    fY = Yfreq.value;\n' + 
                    '}\n' + 
                    'else {\n' + 
                    '    tX = integrateLinearKeys( Xfreq );\n' + 
                    '    tY = integrateLinearKeys( Yfreq );\n' + 
                    '}\n' + 
                    'var X1 = wiggle(fX,Xamp, complexity, multiplier, tX);\n' +
                    'var Y1 = wiggle(fY,Yamp, complexity, multiplier, tY);\n' +
                    'var w1 = [X1[0],Y1[1]];\n' +
                    'var X2 = wiggle(fX,Xamp, complexity, multiplier, tX - loop);\n' +
                    'var Y2 = wiggle(fY,Yamp, complexity, multiplier, tY - loop);\n' +
                    'var w2 = [X2[0],Y2[1]];\n' +
                    'var w = w1;\n' +
                    'if (doLoop)  w = ease(tX, -loop,  0, w1, w2);\n' +
                    'result = w + value - valueAtTime(0);\n' +
                    '}\n' +
                    'result;';
        }
        else if (dimensions == 1)
        {
            prop.getProperty().expression = DuAEExpression.Id.WIGGLE + '\n' + effectLink + '\n' +
                    'var freq = fx(' + i['Frequency'].index + ');\n' +
                    'var amp = fx(' + i['Amplitude'].index + ').value;\n' +
                    'var loop = fx(' + i['Loop duration (s)'].index + ').value;\n' +
                    'var complexity = fx(' + i['Details']['Complexity (octaves)'].index + ').value;\n' +
                    'var multiplier = fx(' + i['Details']['Multiplier'].index + ').value;\n' +
                    'var seed = fx(' + i['Details']['Random Seed'].index + ').value;\n' +
                    'var layerSeed = fx(' + i['Details']['One seed per layer'].index + ').value;\n' + 
                    '\n' +
                    DuAEExpression.Library.get(['integrateLinearKeys']) + '\n' + 
                    '\n' +
                    'var result = value;\n' +
                    'if (fx.active) {\n' + 
                    '   if (layerSeed) seed += index;\n' + 
                    '   seedRandom(seed);\n' + 
                    '   var doLoop = freq.numKeys < 2;\n' + 
                    '   if (loop == 0) loop = thisComp.duration;\n' + 
                    '   var t = time;\n' + 
                    '   var f = 1;\n' + 
                    '   if (doLoop) {\n' + 
                    '       t = (time % loop)-loop;\n' + 
                    '       f = freq.value;\n' + 
                    '   }\n' + 
                    '   else {\n' + 
                    '       t = integrateLinearKeys( freq );\n' + 
                    '   }\n' + 
                    '   var w1 = wiggle(f, amp, complexity, multiplier, t);\n' + 
                    '   var w2 = wiggle(f, amp, complexity, multiplier, t - loop);\n' + 
                    '   var w = w1;\n' + 
                    '   if (doLoop) w = ease(t, -loop,  0, w1, w2);\n' + 
                    '   result = w + value - valueAtTime(0);\n' +
                    '}\n' +
                    'result;';
        }
    });
    DuAEComp.selectLayers(layers);
    
    DuAE.endUndoGroup( i18n._("Wiggle"));
}

Duik.CmdLib['Automation']["Random"] = "Duik.Automation.random()";
/**
 * Adds a completely random animation to the selected properties.
 * @param {Bool} [separateDimensions=false] Use one value for each dimension/channel.
 * @param {Bool} [individualControls=false] Use one control for each of the properties.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.random = function(separateDimensions, individualControls, props) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return [];

    separateDimensions = def ( separateDimensions, false );
    individualControls = def ( individualControls, false );

    DuAE.beginUndoGroup( i18n._("Random motion"), false);

    DuAEComp.setUniqueLayerNames(undefined, props.first().comp );

    var effect = null;
    var pe = null;
    var i = null;

    var layers = DuAEComp.unselectLayers();
    props.do(function(prop)
    {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;
        var layer = prop.layer;
        var dimensions = prop.dimensions();
        var comp = prop.comp;

        // Create effect
        if (effect == null || individualControls)
        {
            var effectName = i18n._("Random");
            if (individualControls) effectName = prop.name + " | " + effectName;

            if (!separateDimensions && dimensions > 1) pe = Duik.PseudoEffect.MULTI_RANDOM;
            else if (dimensions == 1) pe = Duik.PseudoEffect.ONED_RANDOM;
            else if (dimensions == 2) pe = Duik.PseudoEffect.TWOD_RANDOM;
            else if (dimensions == 3) pe = Duik.PseudoEffect.THREED_RANDOM;
            else return;

            effect = pe.apply(layer, effectName);
            effect = new DuAEProperty(effect);

            // Set default values
            i = pe.props;
            effect.prop( i['Details']['Random seed'].index ).setValue( DuMath.random(0,9999) + layer.index );
        }

        // Check the comp link
        var sameComp = effect.comp.name == comp.name;

        var effectLink = "var fx = " + effect.expressionLink(sameComp);
        if (!separateDimensions && dimensions > 1)
	    {
            prop.getProperty().expression = [ DuAEExpression.Id.RANDOM,
                effectLink + '\n',
                'var amp = fx(' + i['Amplitude'].index + ').value;',
                'var freq = fx(' + i['Frequency'].index + ').value;',
                'var animated = fx(' + i['Animated'].index + ').value;',
                'var linked = fx(' + i['Link dimensions'].index + ').value;',
                'var randomMode = fx(' + i['Details']['Mode'].index + ').value;',
                'var seed = fx(' + i['Details']['Random seed'].index + ').value;',
                'posterizeTime(freq);',
                '',
                'var result = value;',
                '',
                'if (fx.active) {',
                '',
                '   seedRandom(seed, !animated);',
                '',
                '   var rnd = 0;',
                '   amp = amp/2;',
                '',
                '	if (randomMode == 1) rnd = gaussRandom(-amp, amp);',
                '	else rnd = random(-amp, amp);',
                '	if (value instanceof Array) {',
                '		var v = [rnd];',
                '		while (v.length < value.length)',
                '		{',
                '			if (!linked)',
                '			{',
                '				if (randomMode == 1) a = gaussRandom(-amp, amp);',
                '				else a = random(-amp, amp);',
                '				v.push( a );',
                '			}',
                '			else {',
                '				v.push(rnd);',
                '			}',
                '		}',
                '		rnd = v;',
                '	}',
                '	result += rnd;',
                '}',
                '',
                'result;',
                ''
            ].join('\n');
        }
        else
        {
            prop.getProperty().expression = [ DuAEExpression.Id.RANDOM,
                effectLink + '\n',
                'var amp = fx(' + i['Amplitude'].index + ').value;',
                'var freq = fx(' + i['Frequency'].index + ').value;',
                'var animated = fx(' + i['Animated'].index + ').value;',
                'var randomMode = fx(' + i['Details']['Mode'].index + ').value;',
                'var seed = fx(' + i['Details']['Random seed'].index + ').value;',
                'posterizeTime(freq);',
                '',
                'var result = value;',
                '',
                'if (fx.active) {',
                '',
                '   seedRandom(seed, !animated);',
                '',
                '   var rnd = 0;',
                '   amp = amp/2;',
                '',
                '	if (randomMode == 1) result += gaussRandom(-amp, amp);',
                '	else result += random(-amp, amp);',
                '}',
                '',
                'result;',
                ''
            ].join('\n');
        }
    });
    DuAEComp.selectLayers(layers);
    
    DuAE.endUndoGroup( i18n._("Random motion"));
}

Duik.CmdLib['Automation']["Wheel"] = "Duik.Automation.wheel()";
/**
 * Automates the rotation of layers as wheels
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.wheel = function( layers ) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Wheel"), false);

    DuAEComp.setUniqueLayerNames(undefined, layers.first().containingComp );

    var pe = Duik.PseudoEffect.WHEEL;
    var i = pe.props;

    layers.do(function(layer) {
        var r = DuAELayer.width(layer) / 2;

        var rotProp = layer.transform.rotation;
	    if (layer.threeDLayer) rotProp = layer.transform.zRotation;

        var effect = pe.apply(layer);
        
        effect( i['Radius'].index ).setValue( r );

        rotProp.expression = [ DuAEExpression.Id.WHEEL,
            'var fx = effect("' + effect.name + '");',
            'var wheelRadius = fx(' + i['Radius'].index +  ').value;',
            'var reversed = fx(' + i['Reverse'].index +  ').value;',
            'var trajectory = fx(' + i['Trajectory'].index +  ').value;',
            'var moBlurPrecision = fx(' + i['Motion Blur Precision'].index +  ').value;',
            '',
            'var result = value;',
            '',
            'function wheel(r, type, precision) {',
            '  ',
            '  if (r == 0) return 0;',
            '  ',
            '  function p(t) {',
            '      return thisLayer.toWorld(thisLayer.anchorPoint, t);',
            '  }',
            '  ',
            '  var distance = 0;',
            '    // curved',
            '    if (type == 3) {',
            '        var start = thisLayer.inPoint > thisComp.displayStartTime ? thisLayer.inPoint : thisComp.displayStartTime;',
            '        var end = time < thisLayer.outPoint ? time : thisLayer.outPoint;',
            '        var step = framesToTime(1)/precision;',
            '        var currentTime = start;',
            '        while (currentTime <= end)',
            '        {',
            '            if (p(currentTime+step)[0] - p(step)[0] > 0) distance += length(p(currentTime+step), p(currentTime));',
            '            else distance -= length(p(currentTime+step), p(currentTime));',
            '            currentTime += step;',
            '        }',
            '    } else if (type == 2) {',
            '        distance = length(p(time), p(0));',
            '    }',
            '    else {',
            '        distance = p(time)[0];',
            '    }',
            '    return radiansToDegrees(distance / r);',
            '}',
            '',
            'if (reversed) result -= wheel( wheelRadius, trajectory, moBlurPrecision );',
            'else result += wheel( wheelRadius, trajectory, moBlurPrecision );',
            '',
            'result;'
        ].join('\n');
    });

    DuAE.endUndoGroup( i18n._("Wheel"));
}

Duik.CmdLib['Automation']["Move away"] = "Duik.Automation.moveAway()";
/**
 * Adds a control to move the layers away from their parent.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.moveAway = function(layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Move away"), false);

    DuAEComp.setUniqueLayerNames(undefined, layers.first().containingComp );
    
    layers.do(function(layer)
    {
        // add control
        var effect = layer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
        effect.name = DuAELayer.newUniqueEffectName( i18n._("Move away"), layer);
        // add expression
        layer.transform.position.expression = [ DuAEExpression.Id.MOVE_AWAY,
            'var result = value;',
            'if (thisLayer.hasParent && (value[0] != 0 || value[1] != 0))',
            '{',
            '	thisWorldPos = thisLayer.toWorld(thisLayer.anchorPoint);',
            '	parentWorldPos = thisLayer.parent.toWorld(thisLayer.parent.anchorPoint);',
            '	depl = effect("' + effect.name + '")(1).value;',
            '	dist = length(parentWorldPos ,thisWorldPos )',
            '	coef = (dist+depl)/dist',
            '	newWorldPos = (thisWorldPos-parentWorldPos)*coef+parentWorldPos',
            '	result = thisLayer.parent.fromWorld(newWorldPos)',
            '}',
            'result;'
        ].join('\n');
    });
    
    DuAE.endUndoGroup( i18n._("Adds a control effect to move the selected layers away from their parents."));

}

/**
 * Assigns random values to the properties at the current time.<br/>
 * This method creates keyframes if the properties are animated.
 * @param {float} [xMin] The minimum X Value
 * @param {float} [xMax] The maximum X Value
 * @param {float} [yMin] The minimum Y Value
 * @param {float} [yMax] The maximum Y Value
 * @param {float} [zMin] The minimum Z Value
 * @param {float} [zMax] The maximum Z Value
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [separate=true] If true, sets a different value for all axis. If false, use the same value for all axis, ignore Y and Z values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.randomizeValues = function(xMin, xMax, yMin, yMax, zMin, zMax, offset, separate, gaussian, props) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    var x = (typeof xMin !== 'undefined' && typeof xMax !== 'undefined' && !isNaN(xMin) && !isNaN(xMax));
	var y = (typeof yMin !== 'undefined'&& typeof yMax !== 'undefined' && !isNaN(yMin) && !isNaN(yMax));
	var z = (typeof zMin !== 'undefined' && typeof zMax !== 'undefined' && !isNaN(zMin) && !isNaN(zMax));

    offset = def(offset, true);
    separate = def(separate, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    props.do(function(propInfo) {
        propInfo = new DuAEProperty(propInfo);
        if (propInfo.isGroup()) return;
        var prop = propInfo.getProperty();
        var dim = propInfo.dimensions();
        var xVal = 0;
        var yVal = 0;
        var zVal = 0;

        // Random

        if (x) xVal = rnd(xMin, xMax);

        if (dim > 1 && y) yVal = rnd(yMin, yMax);
        
        if (dim > 2 && z) zVal = rnd(zMin, zMax);

        // Set new value
        var val;
        if (dim == 1) val = xVal;
        else if (separate) {
            val = [xVal, yVal];
            if (dim > 2) val.push(zVal);
            while (dim > val.length) val.push(0);
        }
        else {
            val = [xVal];
            while (dim > val.length) val.push(xVal);
        }

        if (offset) val = val + prop.value;
        var comp = propInfo.comp;
        prop.numKeys > 0 ? prop.setValueAtTime( comp.time, val) : prop.setValue(val);
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Shuffles the layer start times (moves them in time).
 * @param {int} min The minimum value, in frames.
 * @param {int} max The maximum value, in frames.
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.randomizeLayerTimes = function(min, max, offset, gaussian, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    offset = def(offset, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    layers.do(function(layer) {
        var comp = layer.containingComp;
        var startTime = rnd(min, max) * comp.frameDuration;
        if (offset) layer.startTime = layer.startTime + startTime;
        else layer.startTime = startTime - (layer.inPoint - layer.startTime);
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Shuffles the layer indices (their position in the layer stack).
 * @param {int} min The minimum value, in frames.
 * @param {int} max The maximum value, in frames.
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.randomizeLayerIndices = function(min, max, offset, gaussian, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    offset = def(offset, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    layers.do(function(layer) {
        var comp = layer.containingComp;
        var index = parseInt(rnd(min,max));
        if (offset) index = layer.index + index;
        if (index == layer.index) return;
        if (index >= comp.numLayers) layer.moveToEnd();
		else if (index < 2) layer.moveToBeginning();
		else layer.moveBefore(comp.layer(index));
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Shuffles the layer in points.
 * @param {int} min The minimum value, in frames.
 * @param {int} max The maximum value, in frames.
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.randomizeLayerInPoints = function(min, max, offset, gaussian, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    offset = def(offset, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    layers.do(function(layer) {
        var comp = layer.containingComp;
        var inPoint = rnd(min, max) * comp.frameDuration;
        // We need to reset the out point, because Ae...
        var out = layer.outPoint;
        if (offset) inPoint = layer.inPoint + inPoint;
        if (inPoint >= layer.outPoint) inPoint = layer.outPoint - comp.frameDuration;
        layer.inPoint = inPoint;
        layer.outPoint = out;
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Shuffles the layer out points.
 * @param {int} min The minimum value, in frames.
 * @param {int} max The maximum value, in frames.
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.randomizeLayerOutPoints = function(min, max, offset, gaussian, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    offset = def(offset, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    layers.do(function(layer) {
        var comp = layer.containingComp;
        var outPoint = rnd(min, max) * comp.frameDuration;
        if (offset) outPoint = layer.outPoint + outPoint;
        if (outPoint <= layer.inPoint) outPoint = layer.inPoint + comp.frameDuration;
        layer.outPoint = outPoint;
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Shuffles the key times (moves them in time).
 * @param {int} min The minimum value, in frames.
 * @param {int} max The maximum value, in frames.
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.randomizeKeyTimes = function (min, max, offset, gaussian, props) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    offset = def(offset, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    //array to list keys to be removed
	var krKeys = [];
    //array  to list keys to be added
    var newKeys = [];

    props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;

        var krK = [];
        var newK = [];

        var comp = prop.comp;

        //loop through selected keyframes
        var selectedKeys = prop.selectedKeys();
        for (var j = 0 ; j < selectedKeys.length; j++)
        {
            var key = selectedKeys[j];
            var t = rnd(min,max)*comp.frameDuration;
            // SET VALUE
            var oldKey = prop.keyAtIndex(key);
            krK.push(prop.keyTime(key));
            if (offset) oldKey._time += t;
            else oldKey._time = t;
            newK.push(oldKey);
        }
        krKeys.push(krK);
        newKeys.push(newK);
    });

    // Delete and set keyframes
    props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;

        for (var j = 0 ; j < krKeys[props.current].length ; j++)
		{
			prop.removeKey(prop.nearestKeyIndex(krKeys[props.current][j]));
		}

        for (var j = 0; j < newKeys[props.current].length; j++)
        {
            prop.setKey(newKeys[props.current][j], 0);
        }
    });

    // Re-Select
    props.do(function(prop) {
        prop = new DuAEProperty(prop);

        for (var j = 0; j < newKeys[props.current].length; j++)
        {
            prop.setSelectedAtKey( newKeys[props.current][j] );
        }
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

/**
 * Assigns random values to the values of the selected keyframes.
 * @param {float} [xMin] The minimum X Value
 * @param {float} [xMax] The maximum X Value
 * @param {float} [yMin] The minimum Y Value
 * @param {float} [yMax] The maximum Y Value
 * @param {float} [zMin] The minimum Z Value
 * @param {float} [zMax] The maximum Z Value
 * @param {Boolean} [offset=true] If true, offsets the current values. If false, sets absolute values.
 * @param {Boolean} [separate=true] If true, sets a different value for all axis. If false, use the same value for all axis, ignore Y and Z values.
 * @param {Boolean} [gaussian=true] If true, uses random values with a gaussian distribution instead of true random values.
 * @param {PropertyBase[]|DuAEProperty[]|DuList.<PropertyBase>|PropertyBase|DuAEProperty} [props] The properties, the selected properties if omitted (or the selected layers).
 */
Duik.Automation.randomizeKeyValues = function (xMin, xMax, yMin, yMax, zMin, zMax, offset, separate, gaussian, props) {
    props = def(props, DuAEComp.getSelectedProps());
    props = new DuList(props);
    if (props.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Randomize"), false);
    DuAEProject.setProgressMode(true);

    var x = (typeof xMin !== 'undefined' && typeof xMax !== 'undefined' && !isNaN(xMin) && !isNaN(xMax));
	var y = (typeof yMin !== 'undefined'&& typeof yMax !== 'undefined' && !isNaN(yMin) && !isNaN(yMax));
	var z = (typeof zMin !== 'undefined' && typeof zMax !== 'undefined' && !isNaN(zMin) && !isNaN(zMax));

    offset = def(offset, true);
    separate = def(separate, true);
    gaussian = def(gaussian, true);

    var rnd;
    if (gaussian) rnd = DuMath.gaussRandom;
    else rnd = DuMath.random;

    props.do(function(prop) {
        prop = new DuAEProperty(prop);
        if (prop.isGroup()) return;
        //Get containing comp and dimensions
        var comp = prop.comp;
        var dim = prop.dimensions();
        //loop through selected keyframes
        var selectedKeys = prop.selectedKeys();
        for (var j = 0 ; j < selectedKeys.length; j++)
        {
            var key = selectedKeys[j];
            var xval = 0;
            var yval = 0;
            var zval = 0;
            //X
            if (x) xVal = rnd(xMin,xMax);
            //Y
            if (dim > 1 && y) yVal = rnd(yMin,yMax);
            //Z
            if (dim > 2 && z) zVal = rnd(zMin,zMax);

            var val;
            if (dim == 1) val = xVal;
            else if (separate) {
                val = [xVal, yVal];
                if (dim > 2) val.push(zVal);
                while (dim > val.length) val.push(0);
            }
            else {
                val = [xVal];
                while (dim > val.length) val.push(xVal);
            }
            //SET VALUE
            if (offset) val += prop.keyValue(key);
            prop.setValueAtKey(val,key);
        }
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Randomize"));
}

Duik.CmdLib['Automation']["Motion trail"] = "Duik.Automation.motionTrail()";
/**
 * Draws a trail following the selected layers.
 * @param {Boolean} [createNewLayer = false] Option to create a new layer for each trail.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.motionTrail = function( createNewLayer, layers) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    
    // Get comp
    var comp;
    if (layers.length() == 0) comp = DuAEProject.getActiveComp();
    else comp = layers.at(0).containingComp;
    if (!comp) return;

    DuAE.beginUndoGroup( i18n._("Motion trail"), false);
    DuAEProject.setProgressMode(true);

    DuAEComp.setUniqueLayerNames(undefined, layers.first().containingComp );

    createNewLayer = def(createNewLayer, false);

    // Get existing trail layer
    var trailLayer;
    if (!createNewLayer) {
        var trailLayers = Duik.Layer.get( Duik.Layer.Type.MOTION_TRAIL, false, comp );
        if (trailLayers.length == 0) createNewLayer = true;
        else trailLayer = trailLayers[0];
    }

    if (createNewLayer) {
        trailLayer = comp.layers.addShape();
        Duik.Layer.setType(Duik.Layer.Type.MOTION_TRAIL, trailLayer);
        trailLayer.name = DuAEComp.newUniqueLayerName( i18n._("Motion trails"), comp );
    }

    var pe = Duik.PseudoEffect.MOTION_TRAIL;
    var p = pe.props;

    function createTrail(layer) {
        var effect = pe.apply( trailLayer, i18n._("Motion trail") );

        // Create shape
        var trailGroup = trailLayer("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        trailGroup.name = effect.name;

        var trailPath = trailGroup("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
        trailPath = trailPath.property("ADBE Vector Shape");
        trailPath.expression = [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect("' + effect.name + '");',
            '//parameters',
            'var trailLayer = getEffectLayer(fx, ' + p['Motion source'].index + ');',
            'var inFrame = fx(' + p['Start (frames)'].index + ').value;',
            'var outFrame = fx(' + p['End (frames)'].index + ').value;',
            'var trailStrokeWidth = fx(' + p['Width'].index + ').value;',
            'var useAutoWidth = fx(' + p['Advanced: auto-width'].index + ').value;',
            'var pathOffset = fx(' + p['Path offset'].index + ').value;',
            'var taperStartLength = fx(' + p['Taper']['Start length'].index + ').value;',
            'var taperEndLength = fx(' + p['Taper']['End length'].index + ').value;',
            'var taperEaseStart = fx(' + p['Taper']['Start ease'].index + ').value;',
            'var taperEaseEnd = fx(' + p['Taper']['End ease'].index + ').value;',
            'var trailMode = fx(' + p['Mode'].index + ').value;',
            'var sampleMethod = fx(' + p['Sampling']['Method'].index + ').value;',
            'var samples = fx(' + p['Sampling']['Samples'].index + ').value;',
            '',
            DuAEExpression.Library.get([
                'bezierInterpolation',
                'getEffectLayer',
                'getCompScale'
            ]),
            '',
            'if (trailLayer != null && fx.active) {',
            '',
            '	//adjust parameters',
            '	taperStartLength /= 100;',
            '	taperEndLength /= 100;',
            '	taperEaseStart /= 100;',
            '	taperEaseEnd /= 100;',
            '',
            '	//will store the path points and the values for the taper',
            '	var trailPoints = [];',
            '	var taperValues = [];',
            '',
            '	//compute time range',
            '	var currentFrame = timeToFrames(time);',
            '	if (inFrame > outFrame) inFrame = -inFrame;',
            '	else if (inFrame == outFrame) inFrame = -1;',
            '	var autoSampleLimit = 1 / (samples * 5);',
            '	var startFrame = currentFrame + inFrame;',
            '	var endFrame = currentFrame + outFrame;',
            '	var sTime = framesToTime(startFrame);',
            '	var eTime = framesToTime(endFrame);',
            '',
            '	// for each frame starting from the end',
            '	for (var i = endFrame; i >= startFrame; i--) {',
            '',
            '		var t = framesToTime(i);',
            '		var pT = framesToTime(i - 1);',
            '		var nT = framesToTime(i + 1);',
            '		var pos = trailLayer.toComp(trailLayer.anchorPoint, t);',
            '		if (pos.length == 3) pos.pop();',
            '		var prevPos = trailLayer.toComp(trailLayer.anchorPoint, pT);',
            '		if (prevPos.length == 3) prevPos.pop();',
            '		var nextPos = trailLayer.toComp(trailLayer.anchorPoint, nT);',
            '		if (nextPos.length == 3) nextPos.pop();',
            '',
            '		if (pos == prevPos) continue;',
            '',
            '		//compute samples',
            '		if (sampleMethod == 1) {',
            '			try {',
            '				var vec = normalize(nextPos - pos);',
            '				var prevVec = normalize(pos - prevPos);',
            '				var step = length(prevVec, vec);',
            '				var stepRatio = step / autoSampleLimit;',
            '				if (stepRatio > 1) samples = Math.floor(stepRatio);',
            '				else samples = 1;',
            '			} catch (e) {}',
            '		}',
            '',
            '		//build path and store taper values',
            '		var step = thisComp.frameDuration / samples;',
            '		for (var sub = t + thisComp.frameDuration - step; sub >= t; sub -= step) {',
            '',
            '			var subPos = trailLayer.toComp(trailLayer.anchorPoint, sub);',
            '			if (subPos.length == 3) subPos.pop();',
            '',
            '			subPos = subPos - position;',
            '			trailPoints.push(subPos);',
            '',
            '			if (trailMode == 2) {',
            '				var w = trailStrokeWidth;',
            '',
            '				var duration = eTime - sTime;',
            '				var elapsed = sub - sTime;',
            '				var tRatio = elapsed / duration;',
            '',
            '				if (tRatio > 1 - taperStartLength) {',
            '					w = bezierInterpolation(sub, eTime - duration * taperStartLength, eTime, w, 0, [taperEaseStart, 0, 1 - taperEaseStart, 0]);',
            '				}',
            '',
            '				if (tRatio < taperEndLength) {',
            '					w = bezierInterpolation(tRatio, 0, taperEndLength, 0, w, [1 - taperEaseEnd, 1, taperEaseEnd, 1]);',
            '				}',
            '',
            '				if (useAutoWidth) {',
            '					var ratio = getCompScale(trailLayer, t);',
            '					w = w * ratio;',
            '				}',
            '',
            '				taperValues.push(w);',
            '			}',
            '		}',
            '',
            '	}',
            '',
            '	//offset',
            '	if (trailPoints.length > 1) {',
            '		//compute offset',
            '		var rightSidePoints = [];',
            '		var leftSidePoints = [];',
            '		for (var i = 1, num = trailPoints.length; i < num; i++) {',
            '			var w = [0, 0];',
            '			var o = [0, 0];',
            '',
            '			var vec = normalize(trailPoints[i - 1] - trailPoints[i]);',
            '			var normal = [-vec[1], vec[0]];',
            '',
            '			//width & taper',
            '			if (trailMode == 2) {',
            '				try {',
            '					w = normal * taperValues[i - 1] / 2;',
            '				} catch (e) {}',
            '			}',
            '',
            '			//offset',
            '			try {',
            '				o = normal * pathOffset;',
            '			} catch (e) {}',
            '',
            '			if (trailMode == 2) {',
            '				rightSidePoints[i - 1] = trailPoints[i - 1] + w + o;',
            '				leftSidePoints[i - 1] = trailPoints[i - 1] - w + o;',
            '			} else {',
            '				trailPoints[i - 1] = trailPoints[i - 1] + o;',
            '			}',
            '		}',
            '		if (trailMode == 2) trailPoints = rightSidePoints.concat(leftSidePoints.reverse());',
            '		else trailPoints.pop();',
            '	}',
            '',
            '	if (trailPoints.length > 1) createPath(trailPoints, [], [], useAutoWidth);',
            '	else value;',
            '} else value;'
        ].join('\n');

        var trailStroke = trailGroup("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
        trailStroke('ADBE Vector Stroke Color').expression= [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect( "' + effect.name + '" );',
            'fx(' + p['Color'].index + ').value;'
        ].join('\n');

        trailStroke('ADBE Vector Stroke Opacity').expression = [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect( "' + effect.name + '" );',
            'var trailOpacity = fx(' + p['Opacity'].index + ').value;',
            'var trailMode = fx(' + p['Mode'].index + ').value;',
            'if ( trailMode == 2 ) 0;',
            'else trailOpacity;'
        ].join('\n');

        trailStroke('ADBE Vector Stroke Width').expression = [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect( "' + effect.name + '" );',
            'fx(' + p['Width'].index + ').value;'
            ].join('\n');

        // Taper for Ae >= 17.1
        if (DuAE.version.version >= 17.0) {
            var taper = trailStroke('ADBE Vector Stroke Taper');
            taper('ADBE Vector Taper Start Length').expression = [ DuAEExpression.Id.MOTION_TRAIL,
                'var fx = effect(  "' + effect.name + '" );',
                'fx(' + p['Taper']['Start length'].index + ').value;'
            ].join('\n');
            taper('ADBE Vector Taper End Length').expression = [ DuAEExpression.Id.MOTION_TRAIL,
                'var fx = effect(  "' + effect.name + '" );',
                'fx(' + p['Taper']['End length'].index + ').value;'
            ].join('\n');
            taper('ADBE Vector Taper Start Ease').expression = [ DuAEExpression.Id.MOTION_TRAIL,
                'var fx = effect(  "' + effect.name + '" );',
                'fx(' + p['Taper']['Start ease'].index + ').value;'
            ].join('\n');
            taper('ADBE Vector Taper End Ease').expression = [ DuAEExpression.Id.MOTION_TRAIL,
                'var fx = effect(  "' + effect.name + '" );',
                'fx(' + p['Taper']['End ease'].index + ').value;'
            ].join('\n');
        }
        
        var trailFill = trailGroup("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");

        trailFill('ADBE Vector Fill Color').expression = [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect( "' + effect.name + '" );',
            'fx(' + p['Color'].index + ').value;'
        ].join('\n');

        trailFill('ADBE Vector Fill Opacity').expression = [ DuAEExpression.Id.MOTION_TRAIL,
            'var fx = effect( "' + effect.name + '" );',
            'var trailOpacity = fx(' + p['Opacity'].index + ').value;',
            'var trailMode = fx(' + p['Mode'].index + ').value;',
            'if ( trailMode == 1 ) 0;',
            'else trailOpacity;'
        ].join('\n');

        // set layer
        if (typeof layer !== 'undefined') effect( p['Motion source'].index ).setValue(layer.index);
    }

    // For each layer
    layers.do(function(layer) {
        createTrail(layer);
    });

    // If there's no layer, an empty trail
    if (layers.length() == 0) {
        createTrail();
    }

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Motion trail"));
}

Duik.CmdLib['Automation']["Time remap"] = "Duik.Automation.timeRemap()";
/**
 * Activates the time remapping on the layers, adjusts the keyframes and adds a loop effect.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.timeRemap = function( layers ) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Time remap"), false);
    DuAEProject.setProgressMode(true);

    DuAEComp.setUniqueLayerNames(undefined, layers.first().containingComp );

    layers.do(function(layer) {
        if (!layer.canSetTimeRemapEnabled) return;
        
        var comp = layer.containingComp;
		var lastValueTime = layer.outPoint - comp.frameDuration;

		if (!layer.timeRemapEnabled) layer.timeRemapEnabled = true;

		if (layer.inPoint < lastValueTime)
		{
			layer.timeRemap.setValueAtTime(lastValueTime,layer.timeRemap.valueAtTime(lastValueTime,true));
			layer.timeRemap.removeKey(3);
			layer.timeRemap.setValueAtTime(lastValueTime + comp.frameDuration, layer.timeRemap.valueAtTime(layer.inPoint, true));
			if ( layer.inPoint > layer.timeRemap.keyTime(1))
			{
				layer.timeRemap.setValueAtTime(layer.inPoint, layer.timeRemap.valueAtTime(layer.inPoint, true));
				layer.timeRemap.removeKey(1);
			}
		}
		else
		{
			layer.timeRemap.removeKey(2);
		}

		Duik.Automation.looper(layer.timeRemap);
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Time remap"));
}

Duik.CmdLib['Automation']["Paint rig"] = "Duik.Automation.paintRig()";
/**
 * Rigs paint effects and brush strokes to animate them more easily.
 * @param {AVLayer|AVLayer[]|DuList.<AVLayer>} [layers=DuAEComp.getSelectedLayers()] The layers
 */
Duik.Automation.paintRig = function( layers ) {
    layers = def(layers, DuAEComp.getSelectedLayers());
    layers = new DuList(layers);
    if (layers.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Paint Rig"), false);
    DuAEProject.setProgressMode(true);

    DuAEComp.setUniqueLayerNames(undefined, layers.first().containingComp );

    var pe = Duik.PseudoEffect.PAINT_RIG;
    var p = pe.props;

    layers.do(function(layer) {
        //if there's no paint effect
        var paintEffect = layer("ADBE Effect Parade")("ADBE Paint");
        if (paintEffect == null) return;

        //add effect
        var effect = pe.apply(layer);
        
        //need to get the paint effect again after addProperty, invalid Object blah blah blah.......
        var paintEffect = layer("Effects")("ADBE Paint");

        //the first diameter and color
        var defaultDiam = 0;
        var defaultCol = [0,0,0,0];

        //for each stroke
        var n = paintEffect.property(2).numProperties;
        for (var j=1; j<=n; j++)
        {
            var stroke = paintEffect.property(2).property(j);
            var propStart = new DuAEProperty( stroke.property(4).property('ADBE Paint Begin') );
            var propEnd = new DuAEProperty( stroke.property(4).property('ADBE Paint End') );
            var propCol = new DuAEProperty( stroke.property(4).property('ADBE Paint Color') );
            var propDiam = new DuAEProperty( stroke.property(4).property('ADBE Paint Diameter') );

            if (defaultDiam == 0)
            {
                defaultDiam = propDiam.value();
                effect( p['Diameter']['Diameter A'].index ).setValue(defaultDiam);
                effect( p['Diameter']['Diameter B'].index ).setValue(defaultDiam);
            }
            if (defaultCol[3] == 0)
            {
                defaultCol = propCol.value();
                effect( p['Color']['Color A'].index ).setValue(defaultCol);
                effect( p['Color']['Color A'].index ).setValue(defaultCol);
            }

            var startExp = DuAEExpression.Id.PAINT_RIG + '\n' +
                'var ctrl = effect("' + effect.name + '")(' + p['Start'].index + ').value;\n' +
                'var total = thisProperty.propertyGroup().propertyGroup().propertyGroup().numProperties;\n' +
                'var ind = total + 1 - thisProperty.propertyGroup().propertyGroup().propertyIndex\n' +
                'result = ctrl - ((100/total)*(ind-1));\n' +
                'result = result * total;\n' +
                'result;';
            propStart.setExpression( startExp, false );

            var endExp = DuAEExpression.Id.PAINT_RIG + '\n' +
                'var ctrl = effect("' + effect.name + '")(' + p['End'].index + ');\n' +
                'var total = thisProperty.propertyGroup().propertyGroup().propertyGroup().numProperties;\n' +
                'var ind = total + 1 - thisProperty.propertyGroup().propertyGroup().propertyIndex;\n' +
                'result = ctrl - ((100/total)*(ind-1));\n' +
                'result = result * total;\n' +
                'result;';
            propEnd.setExpression( endExp, false );

            
            var diamExp = DuAEExpression.Id.PAINT_RIG + '\n' +
                'var fx = effect("' + effect.name + '");\n' +
                'var ctrlA = fx(' + p['Diameter']['Diameter A'].index + ').value;\n' +
                'var ctrlB = fx(' + p['Diameter']['Diameter B'].index + ').value;\n' +
                'var reverse = fx(' + p['Interpolation']['Reverse'].index + ').value;\n' +
                'var interpolation =fx(' + p['Interpolation']['Ease'].index + ').value;\n' +
                'var mode = fx(' + p['Interpolation']['Mode'].index + ').value;\n' +
                'var total = thisProperty.propertyGroup().propertyGroup().propertyGroup().numProperties;\n' +
                'var ind = total + 1 - thisProperty.propertyGroup().propertyGroup().propertyIndex;\n' +
                'if (reverse)\n' +
                '{\n' +
                'var t = ctrlA;\n' +
                'ctrlA = ctrlB;\n' +
                'ctrlB = t;\n' +
                '}\n' +
                'var result = ctrlA;\n' +
                'if (mode == 2)\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 2) result = ease(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 3) result = easeIn(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 4) result = easeOut(ind,1,total,ctrlA,ctrlB);\n' +
                '}\n' +
                'else if (mode == 3)\n' +
                '{\n' +
                'if (ind < total /2)\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 2) result = ease(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 3) result = easeIn(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 4) result = easeOut(ind,1,total/2,ctrlA,ctrlB);\n' +
                '}\n' +
                'else\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 2) result = ease(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 3) result = easeIn(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 4) result = easeOut(ind,total/2,total,ctrlB,ctrlA);\n' +
                '}\n' +
                '}\n' +
                'result;';
            propDiam.setExpression( diamExp, false );

            
            var colExp = DuAEExpression.Id.PAINT_RIG + '\n' +
                'var fx = effect("' + effect.name + '");\n' +
                'var ctrlA = fx(' + p['Color']['Color A'].index + ').value;\n' +
                'var ctrlB = fx(' + p['Color']['Color B'].index + ').value;\n' +
                'var reverse = fx(' + p['Interpolation']['Reverse'].index + ').value;\n' +
                'var interpolation =fx(' + p['Interpolation']['Ease'].index + ').value;\n' +
                'var mode = fx(' + p['Interpolation']['Mode'].index + ').value;\n' +
                'var total = thisProperty.propertyGroup().propertyGroup().propertyGroup().numProperties;\n' +
                'var ind = total + 1 - thisProperty.propertyGroup().propertyGroup().propertyIndex;\n' +
                'if (reverse)\n' +
                '{\n' +
                'var t = ctrlA;\n' +
                'ctrlA = ctrlB;\n' +
                'ctrlB = t;\n' +
                '}\n' +
                'var result = ctrlA;\n' +
                'if (mode == 2)\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 2) result = ease(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 3) result = easeIn(ind,1,total,ctrlA,ctrlB);\n' +
                'else if (interpolation == 4) result = easeOut(ind,1,total,ctrlA,ctrlB);\n' +
                '}\n' +
                'else if (mode == 3)\n' +
                '{\n' +
                'if (ind < total /2)\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 2) result = ease(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 3) result = easeIn(ind,1,total/2,ctrlA,ctrlB);\n' +
                'else if (interpolation == 4) result = easeOut(ind,1,total/2,ctrlA,ctrlB);\n' +
                '}\n' +
                'else\n' +
                '{\n' +
                'if (interpolation == 1) result = linear(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 2) result = ease(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 3) result = easeIn(ind,total/2,total,ctrlB,ctrlA);\n' +
                'else if (interpolation == 4) result = easeOut(ind,total/2,total,ctrlB,ctrlA);\n' +
                '}\n' +
                '}\n' +
                'result;';
            propCol.setExpression( colExp , false );

        }
    });

    DuAEProject.setProgressMode(false);
    DuAE.endUndoGroup( i18n._("Paint Rig"));
}

Duik.CmdLib['Automation']["Walk"] = "Duik.Automation.walk()";
Duik.CmdLib['Automation']["Run"] = "Duik.Automation.walk()";
/**
 * Animates the selected character using a procedural walk or run cycle.
 * @param {Layer[]|DuList.<Layer>} [controllers] The controllers to setup. If omitted, will get the selected controllers, or all the controllers of the current comp.
 */
Duik.Automation.walk = function( controllers ) {
    var ctrls = Duik.Automation.getWalkCtrls(controllers)
    if (ctrls == null) return;

    Duik.Automation.rigWalk( ctrls );
}

// low-level undocumented method
// Gets an object containing controllers to be used with Duik.Automation.rigWalk
Duik.Automation.getWalkCtrls = function( controllers ) {
    controllers = def( controllers, Duik.Controller.get() );
    controllers = new DuList(controllers);
    if (controllers.length() == 0) controllers = new DuList( Duik.Controller.get(false) );
    if (controllers.length() == 0) return {};

    // What we expect
    var ctrls = {};

    // Sort
    controllers.do(function(ctrl) {
        var type = DuAETag.getValue(ctrl, DuAETag.Key.DUIK_CONTROLLER_TYPE, DuAETag.Type.INT);

        if (type == Duik.Controller.Type.HEAD) { ctrls.head = ctrl; return; }
        if (type == Duik.Controller.Type.SHOULDERS) { ctrls.neck = ctrl; return; }
        if (type == Duik.Controller.Type.TORSO) { ctrls.torso = ctrl; return; }
        if (type == Duik.Controller.Type.VERTEBRAE) { ctrls.spine = ctrl; return; }
        if (type == Duik.Controller.Type.HIPS) { ctrls.hips = ctrl; return; }
        if (type == Duik.Controller.Type.BODY) { ctrls.body = ctrl; return; }

        var side = Duik.Layer.side(ctrl);

        if (type == Duik.Controller.Type.FOOT ||
            type == Duik.Controller.Type.CLAWS ||
            type == Duik.Controller.Type.HOOF ||
            type == Duik.Controller.Type.PINCER  ) {
                if (side == OCO.Side.LEFT) { ctrls.lFoot = ctrl; return; }
                if (side == OCO.Side.RIGHT) { ctrls.rFoot = ctrl; return; }
                if (!ctrls.lFoot) { ctrls.lFoot = ctrl; return; }
                if (!ctrls.rFoot) { ctrls.rFoot = ctrl; return; }
            }

        if (type == Duik.Controller.Type.HAND ||
            type == Duik.Controller.Type.CLAWS ||
            type == Duik.Controller.Type.HOOF ||
            type == Duik.Controller.Type.PINCER  ) {
                if (side == OCO.Side.LEFT) { ctrls.lHand = ctrl; return; }
                if (side == OCO.Side.RIGHT) { ctrls.rHand = ctrl; return; }
                if (!ctrls.lHand) { ctrls.lHand = ctrl; return; }
                if (!ctrls.rHand) { ctrls.rHand = ctrl; return; }
            }
    });
    return ctrls;
}

/**
 * Animates the given controllers with a wolk/run cycle.
 * @param {Object} ctrls The controllers to setup. An object containing these layers:<br />
 * <code>ctrls.head</code> The head controller<br />
 * <code>ctrls.neck</code> The neck controller<br />
 * <code>ctrls.torso</code> The torso controller<br />
 * <code>ctrls.spine</code> The spine controller<br />
 * <code>ctrls.hips</code> The hips controller<br />
 * <code>ctrls.body</code> The body controller<br />
 * <code>ctrls.rHand</code> The right hand controller<br />
 * <code>ctrls.lHand</code> The left hand controller<br />
 * <code>ctrls.rFoot</code> The right foot controller<br />
 * <code>ctrls.lFoot</code> The left foot controller<br />
 * Note that some of these may be undefined/null.
 */
Duik.Automation.rigWalk = function( ctrls ) {

    DuAE.beginUndoGroup( i18n._("Walk/Run cycle"), false);

    var comp = null;
    var characterName = '';
    if (ctrls.head) { comp = ctrls.head.containingComp; characterName = Duik.Layer.groupName( ctrls.head ); }
	else if (ctrls.neck) { comp = ctrls.neck.containingComp; characterName = Duik.Layer.groupName( ctrls.neck ); }
	else if (ctrls.torso) { comp = ctrls.torso.containingComp; characterName = Duik.Layer.groupName( ctrls.torso ); }
	else if (ctrls.spine) { comp = ctrls.spine.containingComp; characterName = Duik.Layer.groupName( ctrls.spine ); }
	else if (ctrls.body) { comp = ctrls.body.containingComp; characterName = Duik.Layer.groupName( ctrls.body ); }
	else if (ctrls.hips) { comp = ctrls.hips.containingComp; characterName = Duik.Layer.groupName( ctrls.hips ); }
	else if (ctrls.rHand) { comp = ctrls.rHand.containingComp; characterName = Duik.Layer.groupName( ctrls.rHand ); }
	else if (ctrls.lHand) { comp = ctrls.lHand.containingComp; characterName = Duik.Layer.groupName( ctrls.lHand ); }
	else if (ctrls.rFoot) { comp = ctrls.rFoot.containingComp; characterName = Duik.Layer.groupName( ctrls.rFoot ); }
	else if (ctrls.lFoot) { comp = ctrls.lFoot.containingComp; characterName = Duik.Layer.groupName( ctrls.lFoot ); }

    if (!comp) comp = DuAEProject.getActiveComp();
	if (!comp) return;

    var mainController = Duik.Controller.create(comp, Duik.Controller.Type.WALK_CYCLE );
    Duik.Layer.setGroupName( characterName, mainController );
    var mainControllerName = mainController.name;

    //add effect
	var effect = DuAELayer.applyPreset(mainController, preset_walk_cycle);
	var effectName = effect.name;

    //set up
    var hips = 0;
    var foot = 0;
    var neck = 0;
    var hand = 0;
    var faceRight = true;
    var exp0 = DuAEExpression.Id.WALK_RUN_CYCLE + '\nvalue + ';
    var exp1 = 'thisComp.layer("' + mainControllerName + '").effect("' + effectName + '")("';
    var exp2 = '").value;';

    if (ctrls.body) {
        var pos = ctrls.body.transform.position;
        if (pos.dimensionsSeparated) ctrls.body.transform.property('ADBE Position_1').expression = exp0 + exp1 + 'Body Y Position' + exp2;
        else {
            pos.expression = DuAEExpression.Id.WALK_RUN_CYCLE + '\nvalue + [0,' + exp1 + 'Body Y Position").value];';
        }
        hips = DuAELayer.getWorldPos( ctrls.body );
    }

    if (ctrls.hips) {
        ctrls.hips.transform.rotation.expression = exp0 + exp1 + 'Hips rotation' + exp2;
        hips = DuAELayer.getWorldPos( ctrls.hips );
        neck = DuAELayer.getWorldPos( ctrls.hips );
    }

    if (ctrls.spine) {
        ctrls.spine.transform.rotation.expression = exp0 + exp1 + 'Spine rotation' + exp2;
        if (hips == 0) hips = DuAELayer.getWorldPos( ctrls.spine );
        neck = DuAELayer.getWorldPos( ctrls.spine );
    }

    if (ctrls.torso) {
        ctrls.torso.transform.rotation.expression = exp0 + exp1 + 'Torso rotation' + exp2;
        if (hips == 0) hips = DuAELayer.getWorldPos( ctrls.torso );
        neck = DuAELayer.getWorldPos( ctrls.torso );
    }

    if (ctrls.neck) {
        ctrls.neck.transform.rotation.expression = exp0 + exp1 + 'Neck rotation' + exp2;
        if (hips == 0) hips = DuAELayer.getWorldPos( ctrls.neck );
        neck = DuAELayer.getWorldPos( ctrls.neck );
    }

    if (ctrls.head) {
        ctrls.head.transform.rotation.expression = exp0 + exp1 + 'Head rotation' + exp2;
        if (hips == 0) hips = DuAELayer.getWorldPos( ctrls.head );
        if (neck == 0) neck = DuAELayer.getWorldPos( ctrls.head );
    }

    function rigLeg(layer, side) {
        // FOOT ROLL
        var pe = Duik.PseudoEffect.FOOT_ROLL;
        var frEffect = layer.effect( pe.matchName );
        if (!frEffect) {
            pe = Duik.PseudoEffect.DIGI_FOOT_ROLL;
            frEffect = layer.effect( pe.matchName );
        }
        if (frEffect) frEffect(pe.props['Foot roll'].index).expression = exp0 + exp1 + side + '.Foot roll' + exp2;
        // Position
        var pos = layer.transform.position;
        if (pos.dimensionsSeparated) {
            layer.transform.property('ADBE Position_0').expression = exp0 + exp1 + side + '.Foot X position' + exp2;
            layer.transform.property('ADBE Position_1').expression = exp0 + exp1 + side + '.Foot Y position' + exp2;
        }
        else {
            pos.expression = DuAEExpression.Id.WALK_RUN_CYCLE + '\nvalue + [' + exp1 + side + '.Foot X position").value, ' + exp1 + side + '.Foot Y position").value];';
        }
        // Rotation
        layer.transform.rotation.expression = exp0 + exp1 + side + '.Foot rotation' + exp2;

        if (foot == 0) foot = DuAELayer.getWorldPos( layer );

        // Detect the side
        var pe = Duik.PseudoEffect.TWO_LAYER_IK;
        var ikEffect = layer.effect(pe.matchName);
        if (ikEffect) {
            var side = ikEffect(pe.props['Side'].index).value;
            if (side > 0) faceRight = false;
        }
    }

    function rigArm(layer, side) {
        // FK
        var pe = Duik.PseudoEffect.TWO_LAYER_IK;
        var ikEffect = layer.effect(pe.matchName);
        var isIK = false;
        if (ikEffect) {
            ikEffect( pe.props['FK']['Upper'].index ).expression = exp0 + exp1 + side + '.Arm rotation' + exp2;
            ikEffect( pe.props['FK']['Lower'].index ).expression = exp0 + exp1 + side + '.Forearm rotation' + exp2;
            ikEffect( pe.props['FK']['End'].index ).expression = exp0 + exp1 + side + '.Hand rotation' + exp2;
            isIK = ikEffect( pe.props['IK / FK'].index ).value == 1;
        }
        // Shoulder
        pe = Duik.PseudoEffect.ONE_LAYER_IK;
        var ikEffect = layer.effect(pe.matchName);
        if (ikEffect) {
            ikEffect( pe.props['FK'].index ).expression = exp0 + exp1 + side + '.Shoulder rotation' + exp2;
        }

        // Set to FK
        if (isIK) Duik.Animation.switchIKFK(layer);

        if (hand == 0) hand = DuAELayer.getWorldPos( layer );
    }

    if (ctrls.lFoot) rigLeg(ctrls.lFoot, 'L');
    if (ctrls.rFoot) rigLeg(ctrls.rFoot, 'R');
    if (ctrls.lHand) rigArm(ctrls.lHand, 'L');
    if (ctrls.rHand) rigArm(ctrls.rHand, 'R');

    // compute leg size, and set
    var leg = 450;
    if (foot != 0 && hips != 0) leg = DuMath.length(hips, foot);
    else if (hand != 0 && neck != 0) leg = DuMath.length(neck, hand);
    else {
        if (foot == 0) foot = hand;
        if (hips == 0) hips = neck;
        leg = DuMath.length(hips, foot);
        if (leg == 0) leg = 450;
    }

    effect("Leg height (px)").setValue(leg);
    if (!faceRight) {
        effect("Walk speed").setValue(-100);
        effect("Run speed").setValue(-100);
    }

    DuAE.endUndoGroup( i18n._("Walk/Run cycle"));
}
