Duik.CmdLib['Animation']["Sequence keys"] = "Duik.Animation.sequenceKeys()";
/**
 * Sequences selected keyframes.
 * @param {int} [duration=24] The transition duration, in frames
 * @param {Bool} [reverse=false] Set to true to reverse the order.
 * @param {function} [interpolation=DuInterpolation.linear] An interpolation function, taking 4 arguments in the form <code>i(value, min, max, targetMin, targetMax)</code>
 */
Duik.Animation.sequenceKeys = function(duration, reverse, interpolation) {
    var props = DuAEComp.getSelectedProps();
    var propList = new DuList(props);
    if (propList.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Sequence"), false);

    var comp = propList.at(0).comp;

    // Get animations
    var selectedKeys = [];
    // To fix order, group by category
    var contentKeys = [];
    var maskKeys = [];
    var effectKeys = [];
    var transformKeys = [];
    var geoKeys = [];
    var matKeys = [];
    var styleKeys = [];

    var currentLayerIndex = propList.first().layer.index;

    propList.do(function(prop) {

        // New layer
        if (currentLayerIndex != prop.layer.index) {
            // Concat in the right order
            selectedKeys = selectedKeys.concat(contentKeys);
            selectedKeys = selectedKeys.concat(maskKeys);
            selectedKeys = selectedKeys.concat(effectKeys);
            selectedKeys = selectedKeys.concat(transformKeys);
            selectedKeys = selectedKeys.concat(geoKeys);
            selectedKeys = selectedKeys.concat(matKeys);
            selectedKeys = selectedKeys.concat(styleKeys);

            contentKeys = [];
            maskKeys = [];
            effectKeys = [];
            transformKeys = [];
            geoKeys = [];
            matKeys = [];
            styleKeys = [];

            currentLayerIndex = prop.layer.index;
        }
        
        var keys = prop.selectedKeys();
        if (keys.length == 0) return;
        var p = {};
        p.prop = prop;
        p.anim = prop.animation(true);

        var root = prop.rootPropertyGroup();
        if (root.matchName == 'ADBE Root Vectors Group') contentKeys.push(p);
        else if (root.matchName == 'ADBE Mask Parade') maskKeys.push(p);
        else if (root.matchName == 'ADBE Effect Parade') effectKeys.push(p);
        else if (root.matchName == 'ADBE Transform Group') transformKeys.push(p);
        else if (root.matchName == 'ADBE Extrsn Options Group') geoKeys.push(p);
        else if (root.matchName == 'ADBE Material Options Group') matKeys.push(p);
        else if (root.matchName == 'ADBE Layer Styles') styleKeys.push(p);
        else selectedKeys.push(p);
    });

    // Concat in the right order
    selectedKeys = selectedKeys.concat(contentKeys);
    selectedKeys = selectedKeys.concat(maskKeys);
    selectedKeys = selectedKeys.concat(effectKeys);
    selectedKeys = selectedKeys.concat(transformKeys);
    selectedKeys = selectedKeys.concat(geoKeys);
    selectedKeys = selectedKeys.concat(matKeys);
    selectedKeys = selectedKeys.concat(styleKeys);

    var n = selectedKeys.length;
    var startTime = comp.time;
    duration = duration * comp.frameDuration;
    var endTime = startTime + duration;

    for (var i = 0; i < n; i++) {
        var prop = selectedKeys[i].prop;
        var anim = selectedKeys[i].anim;
        var s = reverse ? 0 : n-1;
        var e = reverse ? n-1 : 0;

        // New time
        var newTime = interpolation(i, s, e, startTime, endTime);
        var offset = newTime - anim.startTime;

        // remove keyframes
        for (var k = anim.keys.length -1; k >= 0; k--)
        {
            prop.removeKey( anim.keys[k] );
        }
        
        prop.setAnim(anim, offset);
    }

    DuAE.endUndoGroup( i18n._("Sequence"));
};

Duik.CmdLib['Animation']["X-Sheet"] = "Duik.Animation.xSheet()";
/**
 * Adjusts the exposure of the animation.
 * @param {Bool} [autoCompute=false] (Try to) auto-compute the best values..
 */
Duik.Animation.xSheet = function( autoCompute ) {
    var comp = DuAEProject.getActiveComp();
    if (!comp) return;

    autoCompute = def(autoCompute, false);

    var props = DuAEComp.getSelectedProps();
    props = new DuList(props);

    DuAE.beginUndoGroup( i18n._("X-Sheet"), false);

    DuAEComp.setUniqueLayerNames(undefined, comp);

    var ok = false;
    var pe = Duik.PseudoEffect.X_SHEET;
    var exp = "";

    if (props.length() > 0) {
        var effect = null;
        props.do(function(prop) {
            if (!prop.riggable()) return;
            var layer = prop.layer;

            // add effect
            if (effect == null) {
                effect = pe.apply(layer);
                exp = [ DuAEExpression.Id.X_SHEET,
                    'var fx = thisComp.layer("' + layer.name + '").effect("' + effect.name + '");',
                    'var mode = fx(' + pe.props['Mode'].index + ');',
                    'var frameDuration = fx(' + pe.props['Frame duration'].index + ').value;',
                    'var xSheet = fx(' + pe.props['X-sheet'].index + ');',
                    'var result = value;',
                    'function getValAtKey(prop)',
                    '{',
                    'if (prop.numKeys > 0)',
                    '{',
                    'var k = prop.nearestKey(time);',
                    'if (k.time > time && k.index > 1) k = prop.key(k.index-1);',
                    'return valueAtTime(k.time);',
                    '}',
                    'else return value;',
                    '}',
                    'if (mode == 1)',
                    '{',
                    'frameDuration = Math.round(frameDuration);',
                    'timef = timeToFrames(time);',
                    'result = valueAtTime(framesToTime( timef - timef%frameDuration ))',
                    '}',
                    'else if (mode == 2) result = getValAtKey(xSheet);',
                    'else if (mode == 3) result = getValAtKey(thisLayer.marker);',
                    'else result = getValAtKey(thisComp.marker);',
                    'result;'
                ].join('\n');
            }
            prop.setExpression(exp, false);
            ok = true;
        });
    }
    if (!ok) {
        var newName = DuAEComp.newUniqueLayerName( i18n._("X-Sheet"),comp);
        var layer = DuAEComp.addAdjustmentLayer(comp);
		layer.name = newName;
        Duik.Layer.setType(Duik.Layer.Type.X_SHEET, layer);

        effect = pe.apply(layer);
        var effectName = effect.name;

        var timeWarp = layer('ADBE Effect Parade').addProperty('ADBE Timewarp');
		timeWarp(1).setValue(1);
		timeWarp(2).setValue(2);
        timeWarp(4).expression = [ DuAEExpression.Id.X_SHEET,
            'var fx = effect("' + effectName + '")',
            'var mode = fx(' + pe.props['Mode'].index + ');',
            'var frameDuration = fx(' + pe.props['Frame duration'].index + ').value;',
            'var xSheet = fx(' + pe.props['X-sheet'].index + ');',
            'var result = timeToFrames(time);',
            'function getValAtKey(prop)',
            '{',
            'if (prop.numKeys > 0)',
            '{',
            'var k = prop.nearestKey(time);',
            'if (k.time > time && k.index > 1) k = prop.key(k.index-1);',
            'return timeToFrames(k.time);',
            '}',
            'else return timeToFrames(time);',
            '}',
            'if (mode == 1)',
            '{',
            'frameDuration = Math.round(frameDuration);',
            'timef = timeToFrames(time);',
            'result = timef - timef%frameDuration;',
            '}',
            'else if (mode == 2) result = getValAtKey(xSheet);',
            'else if (mode == 3) result = getValAtKey(thisLayer.marker);',
            'else result = getValAtKey(thisComp.marker);',
            'result;'
        ].join('\n');
    }

    if (autoCompute && props.length() > 0) {
        //detect limit
        var averageSpeed = DuAEProperty.getAverageSpeed(props);
        if (averageSpeed > 0)
        {
            var precision = averageSpeed*2.5;
            var frames = comp.duration / comp.frameDuration;
            //set Keyframes
            var step = 0;
            effect(pe.props['X-sheet'].index).addKey(0);
            for (var frame = 0 ; frame < frames ; frame++)
            {
                var time = frame * comp.frameDuration;

                var maxSpeed = 0;
                props.do(function(prop) {
                    var speedTest = prop.speedAtTime(time);
                    if (speedTest > maxSpeed) maxSpeed = speedTest;
                });

                step += maxSpeed;

                if (step >= precision && averageSpeed > 0)
                {
                    step = 0;
                    effect(pe.props['X-sheet'].index).addKey(time);
                }
            }
            effect(pe.props['Mode'].index).setValue(2);
        }
    }

    DuAE.endUndoGroup( i18n._("X-Sheet"));
};

Duik.CmdLib['Animation']["Snap IK"] = "Duik.Animation.snapIK()";
/**
 * Snaps the IK to the FK values.
 * @param {Layer[]|DuList.<Layer>} [ctrls] The controllers to snap.
 */
Duik.Animation.snapIK = function( ctrls ) {
    ctrls = def( ctrls, Duik.Controller.get());
    ctrls = new DuList(ctrls);
    if (ctrls.length() == 0) ctrls = new DuList( Duik.Controller.get(false) );
    if (ctrls.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Snap IK"), false);

    // Find IKs
    var pe = Duik.PseudoEffect.TWO_LAYER_IK;
    var p = pe.props;
    ctrls.do(function(ctrl) {
        var effect = ctrl.effect( pe.matchName );
        // Handle the two layer IK first, if any
        if (effect) {
            // Already IK
            if ( effect(p['IK / FK'].index).value == 1) return;

            var comp = ctrl.containingComp;

            // Get the layers
            var lowerIndex = effect( p['Data']['Layers']['Lower'].index ).value;
            var upperIndex = effect( p['Data']['Layers']['Upper'].index ).value;
            // can't do
            if (!lowerIndex || !upperIndex) return;

            // Position of the controller
            var goalIndex = effect( p['Data']['Layers']['Goal'].index ).value;
            if (goalIndex) {
                var goal = comp.layer(goalIndex);
                var pos = DuAELayer.getWorldPos( goal );
                // Set the position of the controller
                var parent = ctrl.parent;
                ctrl.parent = null;
                var posProp = ctrl.transform.position;
                if (posProp.dimensionsSeparated) {
                    var xpos = new DuAEProperty(ctrl.transform.property('ADBE Position_0'));
                    xpos.setValue(pos[0]);
                    var ypos = new DuAEProperty(ctrl.transform.property('ADBE Position_1'));
                    ypos.setValue(pos[1]);
                }
                else {
                    posProp = new DuAEProperty(posProp);
                    posProp.setValue(pos);
                }
                ctrl.parent = parent;
                //fix goal rotation
                var rot = goal.transform.rotation.value;
                var goalParent = goal.parent;
                while(goalParent) {
                    rot += goalParent.transform.rotation.value;
                    goalParent = goalParent.parent;
                }
                var rotProp = new DuAEProperty( ctrl.transform.rotation );
                rotProp.setValue(rot);
            }
            else {
                var lower = comp.layer(lowerIndex);
                var pos = effect( p['Data']['Stretch data']['FK Goal relative position'].index ).value;
                var parent = ctrl.parent;
                ctrl.parent = lower;
                var posProp = ctrl.transform.position;
                if (posProp.dimensionsSeparated) {
                    var xpos = new DuAEProperty(ctrl.transform.property('ADBE Position_0'));
                    xpos.setValue(pos[0]);
                    var ypos = new DuAEProperty(ctrl.transform.property('ADBE Position_1'));
                    ypos.setValue(pos[1]);
                }
                else {
                    posProp = new DuAEProperty(posProp);
                    posProp.setValue(pos);
                }
                ctrl.parent = parent;
            }

            // Adjust side
            var lowerFK = effect(p['FK']['Lower'].index).value;
            var sideFX = new DuAEProperty( effect( p['Side'].index ) );
            if (lowerFK < 0) sideFX.setValue(100);
            else sideFX.setValue(-100);
        }
    });

    DuAE.endUndoGroup( i18n._("Snap IK"));
};

Duik.CmdLib['Animation']["Snap FK"] = "Duik.Animation.snapFK()";
/**
 * Snaps the FK to the IK values.
 * @param {Layer[]|DuList.<Layer>} [ctrls] The controllers to snap.
 */
Duik.Animation.snapFK = function( ctrls ) {
    ctrls = def( ctrls, Duik.Controller.get());
    ctrls = new DuList(ctrls);
    if (ctrls.length() == 0) ctrls = new DuList( Duik.Controller.get(false) );
    if (ctrls.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("Snap FK"), false);

    // Find a 2-layer IK
    var pe = Duik.PseudoEffect.TWO_LAYER_IK;
    var p = pe.props;
    ctrls.do(function(ctrl) {
        var effect = ctrl.effect( pe.matchName );
        if (!effect) return;
        // Already FK
        var ikfkProp = effect(p['IK / FK'].index);
        if ( ikfkProp.value == 0) return;

        var comp = ctrl.containingComp;

        var ikRot = effect(p['Data']['Angles']['Upper angle'].index).value;

        // Temporarilly set FK to get the offset on the upper part
        var removeKey = false;
        if (ikfkProp.numKeys > 0) {
            removeKey = true;
            if (ikfkProp.keyTime( ikfkProp.nearestKeyIndex(comp.time) ) == comp.time) removeKey = false;
            ikfkProp.setValueAtTime( comp.time, 0);
        }
        else ikfkProp.setValue(0);

        var fkRot = effect(p['Data']['Angles']['Upper angle'].index).value;

        if (removeKey) ikfkProp.removeKey( ikfkProp.nearestKeyIndex(comp.time) );
        else ikfkProp.setValue(1);

        var newRot = fkRot - ikRot;

        // Get the IK values, and set them to IK
        var upperProp = new DuAEProperty( effect( p['FK']['Upper'].index ) );
        var lowerProp = new DuAEProperty( effect( p['FK']['Lower'].index ) );
        var endProp = new DuAEProperty( effect( p['FK']['End'].index ) );
        upperProp.setValue( upperProp.value() - newRot );
        lowerProp.setValue( effect(p['Data']['Angles']['Lower angle'].index ).value );
        endProp.setValue( effect(p['Data']['Angles']['Goal angle'].index ).value );
    });

    DuAE.endUndoGroup( i18n._("Snap FK"));
};

Duik.CmdLib['Animation']["Switch IK/FK"] = "Duik.Animation.switchIKFK()";
/**
 * Switches between IK and FK.
 * @param {Layer[]|DuList.<Layer>} [ctrls] The controllers to switch.
 * @param {bool} [addKeyframes=true] Whether to add keyframes on FK and IK properties to keep the switch at the current frame.
 */
Duik.Animation.switchIKFK = function( ctrls, addKeyframes ) {
    addKeyframes = def(addKeyframes, true);
    ctrls = def( ctrls, Duik.Controller.get());
    ctrls = new DuList(ctrls);
    if (ctrls.length() == 0) ctrls = new DuList( Duik.Controller.get(false) );
    if (ctrls.length() == 0) return;

    DuAE.beginUndoGroup( i18n._("IK/FK Switch"), false);

    // the IK effects
    var pe2 = Duik.PseudoEffect.TWO_LAYER_IK;
    var pe1 = Duik.PseudoEffect.ONE_LAYER_IK;
    var p2 = pe2.props;
    var p1 = pe1.props;
    ctrls.do(function(ctrl) {
        // Check if we're IK or FK
        var effect = ctrl.effect(pe2.matchName);
        var ik;
        if (effect) ik = effect( p2['IK / FK'].index ).value;
        else {
            effect = ctrl.effect(pe1.matchName);
            if (effect) ik = effect( p1['IK'].index ).value;
            else return;
        } 
        
        if (ik == 1) Duik.Animation.snapFK(ctrl);
        else Duik.Animation.snapIK(ctrl);

        // Switch all
        var comp = ctrl.containingComp;
        var effects = ctrl.property('ADBE Effect Parade');

        // Start with 2-layer IK
        var two = false;
        for (var i = 1; i <= effects.numProperties; i++) {
            var effect = effects(i);
            if (effect.matchName != pe2.matchName) continue;
            var ikfkProp = new DuAEProperty( effect( p2['IK / FK'].index ));
            if (ikfkProp.value() != ik ) continue;
            two = true;
            ikfkProp.setValue( 1-ik );

            if (addKeyframes) {
                // If there's no keyframe before time, we need one
                if (ikfkProp.numKeys() == 0) ikfkProp.setValueAtTime( ik, 0 );
                else if (ikfkProp.keyTime(1) >= comp.time ) ikfkProp.setValueAtTime(ik, 0 );
                // Add the current key
                ikfkProp.setValueAtTime( 1-ik, comp.time );

                if (ik == 0) {
                    var sideFX = effect( p2['Side'].index );
                    sideFX.setValueAtTime( comp.time, sideFX.value );

                    var rot = ctrl.transform.rotation;
                    rot.setValueAtTime(comp.time, rot.value);

                    var pos = ctrl.transform.position;
                    if (pos.dimensionsSeparated) {
                        var xpos = ctrl.transform.property('ADBE Position_0');
                        var ypos = ctrl.transform.property('ADBE Position_1');
                        xpos.setValueAtTime(comp.time, xpos.value);
                        ypos.setValueAtTime(comp.time, ypos.value);
                    }
                    else {
                        pos.setValueAtTime(comp.time, pos.value);
                    }
                }
                else {
                    effect( p2['FK']['Upper'].index ).setValueAtTime(comp.time,effect( p2['FK']['Upper'].index ).value );
                    effect( p2['FK']['Lower'].index ).setValueAtTime(comp.time, effect( p2['FK']['Lower'].index ).value );
                    effect( p2['FK']['End'].index ).setValueAtTime(comp.time, effect( p2['FK']['End'].index ).value );
                }
            }
        }

        // And adjust 1-layer IK
        var moved = false;
        for (var i = 1; i <= effects.numProperties; i++) {
            var effect = effects(i);
            if (effect.matchName != pe1.matchName) continue;
            var ikfkProp = new DuAEProperty( effect( p1['IK'].index ) );
            if ( ikfkProp.value() != ik ) continue;
            var layerIndex = effect( p1['Data']['Layer'].index ).value;
            if (!layerIndex) continue;
            var layer = comp.layer(layerIndex);
            // Snap it !
            // Keep the original rotation
            var fkRot = layer.transform.rotation.value;

            if (addKeyframes) ikfkProp.setValue( 1-ik );
            else ikfkProp.setValueAtTime(1-ik, comp.time );

            // Get the new rotation
            var ikRot = layer.transform.rotation.value;

            // We can't move the controller anymore,
            // So adjust the FK value instead.
            if (two || moved || ik == 1) {
                var fkProp = new DuAEProperty( effect( p1['FK'].index ) );
                if (addKeyframes) fkProp.setValueAtTime( fkProp.value() - ikRot + fkRot, comp.time );
                else fkProp.setValue( fkProp.value() - ikRot + fkRot );
                
            }
            else if (ik == 0) {
                // Use a null to get the new coordinates
                var no = DuAEComp.addNull( comp, 20, layer );
                var n = DuAEComp.addNull( comp, 20, ctrl );
                n.parent = no;
                no.transform.rotation.setValue( fkRot - ikRot );
                n.parent = ctrl.parent;
                var pos = ctrl.transform.position;
                var newPos = n.transform.position.value;
                if (pos.dimensionsSeparated) {
                    var xpos = new DuAEProperty( ctrl.transform.property('ADBE Position_0') );
                    var ypos = new DuAEProperty( ctrl.transform.property('ADBE Position_1') );
                    if (addKeyframes) {
                        xpos.setValueAtTime(newPos[0], comp.time);
                        ypos.setValueAtTime(newPos[1], comp.time);
                    }
                    else {
                        xpos.setValue(newPos[0]);
                        ypos.setValue(newPos[1]);
                    }
                }
                else {
                    pos = new DuAEProperty(pos);
                    if (addKeyframes) pos.setValueAtTime(newPos, comp.time);
                    else pos.setValue( newPos );
                }
                no.remove();
                n.remove();
                moved = true;
            }
        }
    });

    DuAE.endUndoGroup( i18n._("IK/FK Switch"));
};

Duik.CmdLib['Animation']["Clean Keyframes"] = "Duik.Animation.cleanKeyframes()";
/**
 * Removes all unneeded keyframes
 * @param {Property|DuAEProperty|Property[]|DuAEProperty[]|DuList} [props=DuAEComp.getSelectedProps()] The properties 
 */
Duik.Animation.cleanKeyframes = function( props ) {
    if (!isdef(props))
        props = DuAEComp.getSelectedProps();

    props = new DuList(props);
    if (props.length() == 0) return;

    DuAE.beginUndoGroup(i18n._("Clean keyframes"), false);

    props.do(function (prop)
    {
        prop.cleanKeyframes();
    });

    DuAE.endUndoGroup(i18n._("Clean keyframes"));
};
// ====== camera.jsx======

/**
 * Camera toolkit
 * @namespace
 * @category Duik
 */
Duik.Camera = {}

/**
 * Some Camera presets
 * @enum {File}
 * @readonly
 */
Duik.Camera.Presets =
{
    FRAME: duframe.toFile()
}

/**
 * The list of camera functions
 * @namespace
 */
Duik.CmdLib['Camera'] = {};

Duik.CmdLib['Camera']["Framing guides"] = "Duik.Camera.frame()";
/**
 * Adds framing guides to the composition
 * @param {CompItem} [comp] The composition. The active composition if omitted.
 * @return {ShapeLayer} The frame layer
 */
Duik.Camera.frame = function( comp )
{
    comp = def(comp, DuAEProject.getActiveComp());
    if (!comp) return null;

    DuAE.beginUndoGroup( i18n._("Framing guides"), false );

    //a shape layer
	var frame = comp.layers.addShape();
	frame.name = "Frame";
	DuAELayer.applyPreset(frame, Duik.Camera.Presets.FRAME);

	frame.guideLayer = true;

    DuAE.endUndoGroup( i18n._("Framing guides") );
}

Duik.CmdLib['Camera']["Scale Z-link"] = "Duik.Camera.scaleZLink()";
/**
 * Adds an inverse constraint of the scale to the depth (Z position) of the 3D layers, so that their visual size doesn't change with their depth.<br />
 * Works as a toggle: first run activates the effect, next run removes it from the selected layers.
 * @param {Layer[]|Layer|DuList.<Layer>} [layers] The layers to constrain. The selected layers if omitted.$
 * @return {int} Error code. 1: OK; 0: No camera in the comp, -1: No (selected) layers.
 */
Duik.Camera.scaleZLink = function( layers )
{
    layers = def(layers, DuAEComp.getSelectedLayers() );
    layers = new DuList(layers);
    if( layers.isEmpty() ) return -1;

    // Get the camera (in the layers if possible)
    var camera = DuAEComp.camera( layers );
    if (!camera) return 0;

    // Go!
    DuAE.beginUndoGroup( i18n._("Scale Z-Link"), false );

    // If the camera is locked, unlock it temporarilly
    var camLocked = camera.locked;
    camera.locked = false;

    layers.do( function(layer )
    {
        var currentDistance = DuAELayer.getDistance(layer,camera);
        if (currentDistance == 0) currentDistance = 1;
        var currentScale = layer.transform.scale.value;
		var alreadyLinked = false;

        var expr = layer.transform.scale.expression;
        if (expr.indexOf( DuAEExpression.Id.SCALE_Z_LINK ) === 0) alreadyLinked = true;

        if(alreadyLinked)
		{
			var scale = layer.transform.scale.value;
			layer.transform.scale.expression = '';

			var prop = layer.Effects.property('Scale Z-Link');
			if (prop != null) prop.remove();
			layer.transform.scale.setValue(scale);

			DuAETag.removeGroup(layer, 'SZL');
		}
		else
		{
			if (!layer.threeDLayer) layer.threeDLayer = true;
			if (!layer.threeDLayer) return;
			if (!layer.Effects) return;

			var effect = layer.Effects.addProperty("ADBE Slider Control");
			effect.name = 'Scale Z-Link';

			effect(1).setValue(currentScale[0]);

			layer.transform.scale.expression = [ DuAEExpression.Id.SCALE_Z_LINK,
				'var sca = effect("' + effect.name + '")(1);',
				'var C = thisComp.layer("' + camera.name + '").position;',
				'var O = thisLayer.toWorld(thisLayer.anchorPoint);',
				'var oDist = ' + currentDistance + ';',
                'var result = value;',
				'if (sca != 0) {',
				'   var factor = oDist / sca;',
				'   var dist = length(C,O);',
				'   result = dist/factor;',
				'   result = [result,result,result];',
				'} else result = [0,0,0];',
                'result;'
            ].join('\n');

            DuAETag.addGroup( layer, 'SZL' );
		}
    });


    camera.locked = camLocked;

    DuAE.endUndoGroup( i18n._("Scale Z-Link") );

    return 1;
}

Duik.CmdLib['Camera']["Camera rig"] = "Duik.Camera.rig()";
/**
 * Rigs a camera to make it easier to animate
 * @param {CameraLayer} [camera] The camera to rig. If omitted, will try to find it in selected layers or the active comp.
 * @param {Boolean} [separateDimensions] Whether to separate the position dimensions on the controllers. If the option is not set, Duik will check if the current camera has its dimensions separated first
 * @return {ShapeLayer[]} An array of controllers: [target, cam, main], which may be empty if no camera was found or if it was a one-node camera.
 */
Duik.Camera.rig = function( camera, separateDimensions )
{
    camera = def(camera, DuAEComp.camera());
    if (!camera) return [];

    // Check if it's a two-node camera
    try
    {
        camera.pointOfInterest.expression = '';
    }
    catch(e)
    {
        return [];
    }

    DuAE.beginUndoGroup( i18n._("Camera Rig"), false);

    camera.locked = false;

	separateDimensions = def(separateDimensions, camera.transform.position.dimensionsSeparated);

	// Position must not be separated
	if (camera.transform.position.dimensionsSeparated)
		camera.transform.position.dimensionsSeparated = false;

    var comp = camera.containingComp;

    //create target
	var targetCtrl = Duik.Controller.create(comp, Duik.Controller.Type.POSITION );
    Duik.Controller.setCharacterName( i18n._("Camera"), targetCtrl );
    Duik.Controller.setLimbName( i18n._("Target"), targetCtrl );
	targetCtrl.threeDLayer = true;
	targetCtrl.position.setValue(camera.transform.pointOfInterest.value);
	targetCtrl.position.dimensionsSeparated = separateDimensions;

    //create cam
	var camCtrl = Duik.Controller.create(comp, Duik.Controller.Type.POSITION );
	Duik.Controller.setCharacterName( i18n._("Camera"), camCtrl );
    Duik.Controller.setLimbName( i18n._("Cam"), camCtrl ); /// TRANSLATORS: Short for 'Camera'
	camCtrl.threeDLayer = true;
	camCtrl.position.setValue(camera.transform.position.value);
	camCtrl.position.dimensionsSeparated = separateDimensions;

    //create main
	var mainCtrl = Duik.Controller.create(comp, Duik.Controller.Type.CAMERA);
	Duik.Controller.setCharacterName( i18n._("Camera"), mainCtrl );
    Duik.Controller.setLimbName( camera.name, mainCtrl );
	mainCtrl.threeDLayer = true;
	mainCtrl.position.setValue(camera.transform.position.value);
	mainCtrl.position.dimensionsSeparated = separateDimensions;

    camCtrl.parent = mainCtrl;
	targetCtrl.parent = mainCtrl;

    //expressions in the camera layer
	camera.position.expression = DuAEExpression.Id.CAMERA_RIG + '\nthisComp.layer("' + camCtrl.name + '").toWorld(thisComp.layer("' + camCtrl.name + '").transform.anchorPoint.value);';
	camera.pointOfInterest.expression =  DuAEExpression.Id.CAMERA_RIG + '\nthisComp.layer("' + targetCtrl.name + '").toWorld(thisComp.layer("' + targetCtrl.name + '").transform.anchorPoint.value);';
	camera.orientation.expression =  DuAEExpression.Id.CAMERA_RIG + '\nthisComp.layer("' + camCtrl.name + '").transform.orientation.value;';
	camera.xRotation.expression =  DuAEExpression.Id.CAMERA_RIG + '\nthisComp.layer("' + camCtrl.name + '").transform.xRotation.value';
	camera.yRotation.expression =  DuAEExpression.Id.CAMERA_RIG + '\nthisComp.layer("' + camCtrl.name + '").transform.yRotation.value';
	if (DuAE.version.version >= 16) camera.rotation.expression =  DuAEExpression.Id.CAMERA_RIG + '\n' + 'value + thisComp.layer("' + camCtrl.name + '").transform.zRotation.value';
	else camera.rotation.expression =  DuAEExpression.Id.CAMERA_RIG + '\n' + 'value + thisComp.layer("' + camCtrl.name + '").transform.rotation.value';

	//camera behaviour
	var behaviourPE = Duik.PseudoEffect.CAMERA_BEHAVIOUR;
	var behaviourEffect = behaviourPE.apply( mainCtrl );
	var p = behaviourPE.props;

	// To be reused in different expressions:
	var fxLink = 'var fx = thisComp.layer("' + mainCtrl.name + '").effect("' + behaviourEffect.name + '");';
	// interpolation FX
	var iTypeFX = 'var iType = fx(' + p["Type of motion"].index + ').value;';
	var iRateFX = 'var iRate = fx(' + p["Easing / Acceleration rate"].index + ').value;';
	var bUseAdvancedFX = 'var bUseAdvanced = fx(' + p["Easy-Bezier options"]["Use advanced options"].index + ').value;';
	var bInIFX = 'var bInI = fx(' + p["Easy-Bezier options"]["Advanced"]["Ease in"].index + ').value / 100;';
	var bInVFX = 'var bInV = fx(' + p["Easy-Bezier options"]["Advanced"]["Velocity in"].index + ').value / 100;';
	var bOutIFX = 'var bOutI = fx(' + p["Easy-Bezier options"]["Advanced"]["Ease out"].index + ').value / 100;';
	var bOutVFX = 'var bOutV = fx(' + p["Easy-Bezier options"]["Advanced"]["Velocity out"].index + ').value / 100;';
	var bRatioFX = 'var bRatio = fx(' + p["Easy-Bezier options"]["Ease in/Ease out Ratio"].index + ').value / 100;';
	// behaviour FX
	var gFreqFX = 'var gFreq = fx(' + p["Random motion"]["Frequency"].index + ').value;';
	var gPosAmpFX = 'var gAmp = fx(' + p["Random motion"]["Position amplitude"].index + ').value;';
	var gRotAmpFX = 'var gAmp = fx(' + p["Random motion"]["Rotation amplitude"].index + ').value;';
	var sFreqFX = 'var sFreq = fx(' + p["Camera shake"]["Frequency"].index + ').value;';
	var sPosAmpFX = 'var sAmp = fx(' + p["Camera shake"]["Position amplitude"].index + ').value;';
	var sRotAmpFX = 'var sAmp = fx(' + p["Camera shake"]["Rotation amplitude"].index + ').value;';
	var typeFX = 'var type = fx(' + p["Type of camera"].index + ').value;';
	var seedFX = 'var seed = fx(' + p["Advanced"]["Random Seed"].index + ').value;';

	// Interpolation expression body
	var iExprBody = [
		'if (iType == 2) iRate = linearExtrapolation(iRate, 0, 30, 0, 2);',
		'else if (iType == 3) iRate = linearExtrapolation(iRate, 0, 30, 0, 10);',
		'else if (iType == 1) iRate = linear(iRate, 1, 30, -1, 1);',
		'',
		DuAEExpression.Library.get([
			'isStill',
			'continueOut',
			'continueIn',
			'bezierInterpolation',
			'gaussianInterpolation',
			'linearExtrapolation',
			'logInterpolation',
			'expInterpolation',
			'getPrevKey',
			'getNextKey'
		]),
		'function iAtTime( t )',
		'{',
		'   // Needed keyframes',
		'	var pKey = getPrevKey(t, thisProperty);',
		'	var nKey = getNextKey(t, thisProperty);',
		'	',
		'	if (!pKey || !nKey) return value;',
		'	',
		'	if (iType == 6) // None',
		'	{',
		'	  return valueAtTime(t);',
		'	}',
		'	else if (iType == 5) // Linear ',
		'	{',
		'	  return linear(',
		'			t,',
		'			pKey.time,',
		'			nKey.time,',
		'			pKey.value,',
		'			nKey.value',
		'		);',
		'	}',
		'	else if (iType == 4) // Bezier',
		'	{',
		'    if (bUseAdvanced)',
		'    {',
		'      return bezierInterpolation(',
		'        t,',
		'        pKey.time,',
		'        nKey.time,',
		'        pKey.value,',
		'        nKey.value,',
		'        [bInI, bInV, 1 - bOutI, 1 - bOutV]',
		'      );',
		'    }',
		'    else',
		'    {',
		'      var bIn = linear(iRate, 0, 10, 0.0, 1.0) * bRatio;',
		'      var bOut = linear(iRate, 0, 10, 0.0, 1.0) * (1-bRatio);',
		'      bOut = 1 - bOut;',
		'      ',
		'      return bezierInterpolation(',
		'        t,',
		'        pKey.time,',
		'        nKey.time,',
		'        pKey.value,',
		'        nKey.value,',
		'        [bIn, 0, bOut, 1]',
		'      );',
		'    }',
		'	}',
		'	else if (iType == 1) // Gaussian (start\'n\'stop)',
		'	{',
		'	  return gaussianInterpolation(',
		'	    t,',
		'	    pKey.time,',
		'      nKey.time,',
		'      pKey.value,',
		'      nKey.value,',
		'      iRate',
		'	  );',
		'	}',
		'	else if (iType == 3) // Logarithmic (stop)',
		'	{',
		'	  return logInterpolation(',
		'	    t,',
		'	    pKey.time,',
		'	    nKey.time,',
		'	    pKey.value,',
		'	    nKey.value,',
		'	    iRate',
		'	  );',
		'	}',
		'	else if (iType == 2) // Exponential (start)',
		'	{',
		'	    return expInterpolation(',
		'	        t,',
		'	        pKey.time,',
		'	        nKey.time,',
		'	        pKey.value,',
		'	        nKey.value,',
		'	        iRate',
		'	    );',
		'	}',
		'	',
		'	return -1;',
		'}',
		'',
		'function i() {',
		'	if (numKeys < 2) return value;',
		'	',
		'	var inExtrapolation = iType == 2;',
		'	var outExtrapolation = iType == 3;',
		'',
		'	// Needed keyframes',
		'	var pKey = getPrevKey(time, thisProperty);',
		'	var nKey = getNextKey(time, thisProperty);',
		'	',
		'	// Extrapolation during still parts',
		'	if ( isStill( time, 0 ) )',
		'	{',
		'	  var inVal = value;',
		'	  var outVal = value;',
		'	  // In Extrapolation',
		'	  if (inExtrapolation)',
		'	  {',
		'	    var inTime = time;',
		'	    var nextKey = getNextKey(time, thisProperty);',
		'	    ',
		'		if (iType == 6) inVal = continueIn(inTime, inDamping); // None',
		'		else if (iType == 5 && nextKey) // Linear ',
		'		{',
		'		    var firstVelocity = (nextKey.value - iAtTime(nextKey.time + 0.01)) * 100;',
		'  			var timeSpent = nextKey.time - time;',
		'  			var damp = Math.exp(timeSpent * inDamping);',
		'  			inVal = (timeSpent * firstVelocity)/damp + nextKey.value;',
		'		} else if (iType == 4 && nextKey) // Bezier',
		'		{',
		'			if (!bUseAdvanced) inVal = value;',
		'			else',
		'			{',
		'  				if (bInV == 0) inVal = value;',
		'  				else ',
		'  				{',
		'  					var firstVelocity = (iAtTime(nextKey.time + 0.01) - nextKey.value) * 100;',
		'    				var timeSpent = nextKey.time - time;',
		'    				var damp = Math.exp(timeSpent * inDamping);',
		'    				inVal = (-timeSpent * firstVelocity) / damp + nextKey.value;',
		'  				}',
		'			}',
		'		} else if (iType == 1) // Gaussian',
		'		{',
		'			inVal = value;',
		'		} else if (iType == 3) // Log',
		'		{',
		'			inVal = value;',
		'		} else if (iType == 2 && nextKey) // Exp ',
		'		{',
		'			var previousKey = nextKey;',
		'			if (previousKey.index < numKeys)',
		'			{',
		'				var nextKey = key(previousKey.index + 1);',
		'  				inVal = expInterpolation(',
		'  					time,',
		'  					previousKey.time,',
		'  					nextKey.time,',
		'  					previousKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		}',
		'	  }',
		'	  // Out Extrapolation',
		'	  if (outExtrapolation)',
		'	  {',
		'	    var outTime = time;',
		'	    var prevKey = getPrevKey(time, thisProperty);',
		'	    ',
		'		if (iType == 6) outVal = continueOut(outTime, outDamping); // None',
		'		else if (iType == 5 && prevKey) // Linear ',
		'		{',
		'			var lastVelocity = (prevKey.value - iAtTime(prevKey.time - 0.01)) * 100;',
		'			var timeSpent = time - prevKey.time;',
		'			var damp = Math.exp(timeSpent * outDamping);',
		'			outVal = prevKey.value + (timeSpent * lastVelocity)/damp;',
		'		} else if (iType == 4 && prevKey) // Bezier',
		'		{',
		'			if (!bUseAdvanced) outVal = value;',
		'			else ',
		'			{',
		'  				if (bOutV == 0) outVal = value;',
		'  				else',
		'  				{',
		'  					var lastVelocity = ( prevKey.value - iAtTime(prevKey.time - 0.01)) * 100;',
		'    				var timeSpent = time - prevKey.time;',
		'    				var damp = Math.exp(timeSpent * outDamping);',
		'    				outVal = prevKey.value + (timeSpent * lastVelocity)/damp;',
		'  				}',
		'			}',
		'		} else if (iType == 1) // Gaussian',
		'		{',
		'			outVal = value;',
		'		} else if (iType == 3 && prevKey) // Log',
		'		{',
		'			var nextKey = prevKey;',
		'			if (nextKey.index > 0)',
		'			{',
		'				prevKey = key(nextKey.index - 1);',
		'				outVal = logInterpolation(',
		'  					time,',
		'  					prevKey.time,',
		'  					nextKey.time,',
		'  					prevKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		} else if (iType == 2 && prevKey) // Exp ',
		'		{',
		'			var nextKey = prevKey;',
		'			if (nextKey.index > 0)',
		'			{',
		'				 prevKey = key(nextKey.index - 1);',
		'				 outVal = expInterpolation(',
		'  					time,',
		'  					prevKey.time,',
		'  					nextKey.time,',
		'  					prevKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		}',
		'	  }',
		'	  ',
		'	  if (!pKey) return inVal;',
		'	  if (!nKey) return outVal;',
		'	  ',
		'	  // Blend',
		'	  return ease( time, pKey.time, nKey.time, outVal, inVal);',
		'	}',
		'',
		'	return iAtTime(time);',
		'}'
	].join('\n');

	// Default interpolation expression
	var iExpr = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		iExprBody,
		'',
		'if (fx.enabled) result = i();',
		'result;'
	].join('\n');

	var mainPosExpr = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		gFreqFX,
		gPosAmpFX,
		sFreqFX,
		sPosAmpFX,
		typeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	// Adjust values',
		'	seedRandom(seed);',
		'	var complexity = 1;',
		'	gAmp = gAmp * thisComp.width / 100;',
		'	sAmp = sAmp * thisComp.width / 1000;',
		'	if (type == 2)',
		'	{',
		'	   gAmp = gAmp/2;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 3)',
		'	{',
		'	   gAmp = gAmp/4;',
		'	   complexity = 2;',
		'	}',
		'	else gAmp = 0;',
		'	// Compute Wiggle',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.5);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity , 0.5);',
		'	sw -= value;',
		'	// Adjust results',
		'	if (type == 4) sw[0] /= 2;',
		'	var r = sw + gw;',
		'	// Adjust Z',
		'	if (type == 2) r[2] /= 2;',
		'	else if (type == 3) r[2] = 0;',
		'	return r;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
	].join('\n');

	if (separateDimensions) {
		camCtrl.transform.property("ADBE Position_0").expression = iExpr;
		camCtrl.transform.property("ADBE Position_1").expression = iExpr;
		camCtrl.transform.property("ADBE Position_2").expression = iExpr;

		targetCtrl.transform.property("ADBE Position_0").expression = iExpr;
		targetCtrl.transform.property("ADBE Position_1").expression = iExpr;
		targetCtrl.transform.property("ADBE Position_2").expression = iExpr;

		mainCtrl.transform.property("ADBE Position_0").expression = mainPosExpr;
		mainCtrl.transform.property("ADBE Position_1").expression = mainPosExpr;
		mainCtrl.transform.property("ADBE Position_2").expression = mainPosExpr;
	}
	else {
		camCtrl.position.expression = iExpr;
		targetCtrl.position.expression = iExpr;
		mainCtrl.position.expression = mainPosExpr;
	}

	mainCtrl.orientation.expression = iExpr;

	camCtrl.orientation.expression = iExpr;
	camCtrl.xRotation.expression = iExpr;
	camCtrl.yRotation.expression = iExpr;
	
	targetCtrl.orientation.expression = iExpr;
	targetCtrl.xRotation.expression = iExpr;
	targetCtrl.yRotation.expression = iExpr;
	if (DuAE.version.version >= 16) targetCtrl.rotation.expression = iExpr;
	else targetCtrl.rotation.expression = iExpr;

	// X Rotation
	mainCtrl.xRotation.expression = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		gFreqFX,
		gRotAmpFX,
		sFreqFX,
		sRotAmpFX,
		typeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	// Adjust values',
		'	seedRandom(seed+1);',
		'	var complexity = 1;',
		'	gAmp = gAmp * thisComp.width / 5000;',
		'	sAmp = sAmp * thisComp.width / 50000;',
		'	if (type == 2)',
		'	{',
		'	   gAmp = gAmp/2;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 3)',
		'	{',
		'	   gAmp = gAmp*3/4;',
		'	   sAmp = sAmp/2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 4)',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = sAmp/2;',
		'	}',
		'	else if (type == 5)',
		'	{',
		'	   gAmp = gAmp/3;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	// Compute Wiggle',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity, 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
	].join('\n');
	// Y Rotation
	mainCtrl.yRotation.expression = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		gFreqFX,
		gRotAmpFX,
		sFreqFX,
		sRotAmpFX,
		typeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	// Adjust values',
		'	seedRandom(seed+2);',
		'	var complexity = 1;',
		'	gAmp = gAmp * thisComp.width / 5000;',
		'	sAmp = sAmp * thisComp.width / 50000;',
		'	if (type == 2)',
		'	{',
		'	   gAmp = gAmp/2;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 3)',
		'	{',
		'	   gAmp = gAmp*3/4;',
		'	   sAmp = sAmp/2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 4)',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else if (type == 5)',
		'	{',
		'	   gAmp = gAmp/3;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	// Compute Wiggle',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity , 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
	].join('\n');
	// Z Rotation (not the same controller!)
	var zExp = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		gFreqFX,
		gRotAmpFX,
		sFreqFX,
		sRotAmpFX,
		typeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	// Adjust values',
		'	seedRandom(seed+3);',
		'	var complexity = 1;',
		'	if (type == 2)',
		'	{',
		'	   gAmp = gAmp/5;',
		'	   sAmp = sAmp/5;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (type == 3)',
		'	{',
		'	   gAmp = gAmp/15;',
		'	   sAmp = sAmp/15;',
		'	   complexity = 2;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	// Compute Wiggle',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity , 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
	].join('\n');
	if (DuAE.version.version >= 16) camCtrl.rotation.expression = zExp;
	else camCtrl.rotation.expression = zExp;
	
	//lock camera
	camera.locked = true;
    
    DuAE.endUndoGroup( i18n._("Camera Rig"));

	return [targetCtrl,camCtrl,mainCtrl];
}

Duik.CmdLib['Camera']["2D Camera"] = "Duik.Camera.twoDCamera()";
/**
 * Creates a 2D Multiplane Camera
 * @param {Layer[]|Layer|DuList.<Layer>} [layers] Some layers to parent to the new camera.
 * @return {ShapeLayer[]} The camera layer and its levels (camera is the first layer in the Array).
 */
Duik.Camera.twoDCamera = function( layers )
{
    layers = def(layers, DuAEComp.getSelectedLayers() );
    layers = new DuList(layers);

    var numLayers = 3;

    DuAE.beginUndoGroup( i18n._("2D Camera"), false);

    // Get comp and sort layers
    var comp;
    if (layers.isEmpty()) comp = DuAEProject.getActiveComp();
    else
    {
        layers = DuAELayer.sortByIndex( layers );
        numLayers = layers.length;
        comp = layers[0].containingComp;
    }

    // Create camera control
    var camCtrl = Duik.Controller.create( comp, Duik.Controller.Type.CAMERA );
    Duik.Controller.setCharacterName( i18n._("2D Camera"), camCtrl );
    Duik.Controller.setLimbName( i18n._("Camera"), camCtrl );
    var camZero = Duik.Constraint.zero( camCtrl )[0];

    // Add effect
    var pe = Duik.PseudoEffect.TWO_D_CAMERA;
    var effect = pe.apply( camCtrl );

	// Prepare expressions
	var fxLink = 'var fx = thisComp.layer("' + camCtrl.name + '").effect("' + effect.name + '");';
	// Transform
	var trackFX = 'var track = fx(' + pe.props["Track left/right"].index + ').value;';
	var pedestalFX = 'var pedestal = fx(' + pe.props["Pedestal up/down"].index + ').value;';
	var rollFX = 'var roll = fx(' + pe.props["Roll"].index + ').value;';
	var zoomFX = 'var zoom = fx(' + pe.props["Zoom in/out"].index + ').value;';
	var dollyFX = 'var dolly = fx(' + pe.props["Dolly in/out"].index + ').value;';
	var panFX = 'var pan = fx(' + pe.props["Pan left/right"].index + ').value;';
	var tiltFX = 'var tilt = fx(' + pe.props["Tilt up/down"].index + ').value;';
	// Random motion
	var gFreqFX = 'var gFreq = fx(' + pe.props["Random motion"]["Frequency"].index + ').value;';
	var gAmpFX = 'var gAmp = fx(' + pe.props["Random motion"]["Amplitude"].index + ').value;';
	var sFreqFX = 'var sFreq = fx(' + pe.props["Camera shake"]["Frequency"].index + ').value;';
	var sAmpFX = 'var sAmp = fx(' + pe.props["Camera shake"]["Amplitude"].index + ').value;';
	var camTypeFX = 'var camType = fx(' + pe.props["Type of camera"].index + ').value;';
	var seedFX = 'var seed = fx(' + pe.props["Advanced"]["Random Seed"].index + ').value;';
	// Interpolation
	var iTypeFX = 'var iType = fx(' + pe.props["Type of motion"].index + ').value;';
	var iRateFX = 'var iRate = fx(' + pe.props["Easing / Acceleration rate"].index + ').value;';
	var bUseAdvancedFX = 'var bUseAdvanced = fx(' + pe.props["Easy-Bezier options"]["Use advanced options"].index + ').value;';
	var bInIFX = 'var bInI = fx(' + pe.props["Easy-Bezier options"]["Advanced"]["Ease in"].index + ').value / 100;';
	var bInVFX = 'var bInV = fx(' + pe.props["Easy-Bezier options"]["Advanced"]["Velocity in"].index + ').value / 100;';
	var bOutIFX = 'var bOutI = fx(' + pe.props["Easy-Bezier options"]["Advanced"]["Ease out"].index + ').value / 100;';
	var bOutVFX = 'var bOutV = fx(' + pe.props["Easy-Bezier options"]["Advanced"]["Velocity out"].index + ').value / 100;';
	var bRatioFX = 'var bRatio = fx(' + pe.props["Easy-Bezier options"]["Ease in/Ease out Ratio"].index + ').value / 100;';

	// Interpolation expression body
	var iExprBody = [
		'if (iType == 2) iRate = linearExtrapolation(iRate, 0, 30, 0, 2);',
		'else if (iType == 3) iRate = linearExtrapolation(iRate, 0, 30, 0, 10);',
		'else if (iType == 1) iRate = linear(iRate, 1, 30, -1, 1);',
		'',
		DuAEExpression.Library.get([
			'isStill',
			'continueOut',
			'continueIn',
			'bezierInterpolation',
			'gaussianInterpolation',
			'linearExtrapolation',
			'logInterpolation',
			'expInterpolation',
			'getPrevKey',
			'getNextKey'
		]),
		'function iAtTime( t )',
		'{',
		'   // Needed keyframes',
		'	var pKey = getPrevKey(t, thisProperty);',
		'	var nKey = getNextKey(t, thisProperty);',
		'	',
		'	if (!pKey || !nKey) return value;',
		'	',
		'	if (iType == 6) // None',
		'	{',
		'	  return valueAtTime(t);',
		'	}',
		'	else if (iType == 5) // Linear ',
		'	{',
		'	  return linear(',
		'			t,',
		'			pKey.time,',
		'			nKey.time,',
		'			pKey.value,',
		'			nKey.value',
		'		);',
		'	}',
		'	else if (iType == 4) // Bezier',
		'	{',
		'    if (bUseAdvanced)',
		'    {',
		'      return bezierInterpolation(',
		'        t,',
		'        pKey.time,',
		'        nKey.time,',
		'        pKey.value,',
		'        nKey.value,',
		'        [bInI, bInV, 1 - bOutI, 1 - bOutV]',
		'      );',
		'    }',
		'    else',
		'    {',
		'      var bIn = linear(iRate, 0, 10, 0.0, 1.0) * bRatio;',
		'      var bOut = linear(iRate, 0, 10, 0.0, 1.0) * (1-bRatio);',
		'      bOut = 1 - bOut;',
		'      ',
		'      return bezierInterpolation(',
		'        t,',
		'        pKey.time,',
		'        nKey.time,',
		'        pKey.value,',
		'        nKey.value,',
		'        [bIn, 0, bOut, 1]',
		'      );',
		'    }',
		'	}',
		'	else if (iType == 1) // Gaussian (start\'n\'stop)',
		'	{',
		'	  return gaussianInterpolation(',
		'	    t,',
		'	    pKey.time,',
		'      nKey.time,',
		'      pKey.value,',
		'      nKey.value,',
		'      iRate',
		'	  );',
		'	}',
		'	else if (iType == 3) // Logarithmic (stop)',
		'	{',
		'	  return logInterpolation(',
		'	    t,',
		'	    pKey.time,',
		'	    nKey.time,',
		'	    pKey.value,',
		'	    nKey.value,',
		'	    iRate',
		'	  );',
		'	}',
		'	else if (iType == 2) // Exponential (start)',
		'	{',
		'	    return expInterpolation(',
		'	        t,',
		'	        pKey.time,',
		'	        nKey.time,',
		'	        pKey.value,',
		'	        nKey.value,',
		'	        iRate',
		'	    );',
		'	}',
		'	',
		'	return -1;',
		'}',
		'',
		'function i() {',
		'	if (numKeys < 2) return value;',
		'	',
		'	var inExtrapolation = iType == 2;',
		'	var outExtrapolation = iType == 3;',
		'',
		'	// Needed keyframes',
		'	var pKey = getPrevKey(time, thisProperty);',
		'	var nKey = getNextKey(time, thisProperty);',
		'	',
		'	// Extrapolation during still parts',
		'	if ( isStill( time, 0 ) )',
		'	{',
		'	  var inVal = value;',
		'	  var outVal = value;',
		'	  // In Extrapolation',
		'	  if (inExtrapolation)',
		'	  {',
		'	    var inTime = time;',
		'	    var nextKey = getNextKey(time, thisProperty);',
		'	    ',
		'		if (iType == 6) inVal = continueIn(inTime, inDamping); // None',
		'		else if (iType == 5 && nextKey) // Linear ',
		'		{',
		'		    var firstVelocity = (nextKey.value - iAtTime(nextKey.time + 0.01)) * 100;',
		'  			var timeSpent = nextKey.time - time;',
		'  			var damp = Math.exp(timeSpent * inDamping);',
		'  			inVal = (timeSpent * firstVelocity)/damp + nextKey.value;',
		'		} else if (iType == 4 && nextKey) // Bezier',
		'		{',
		'			if (!bUseAdvanced) inVal = value;',
		'			else',
		'			{',
		'  				if (bInV == 0) inVal = value;',
		'  				else ',
		'  				{',
		'  					var firstVelocity = (iAtTime(nextKey.time + 0.01) - nextKey.value) * 100;',
		'    				var timeSpent = nextKey.time - time;',
		'    				var damp = Math.exp(timeSpent * inDamping);',
		'    				inVal = (-timeSpent * firstVelocity) / damp + nextKey.value;',
		'  				}',
		'			}',
		'		} else if (iType == 1) // Gaussian',
		'		{',
		'			inVal = value;',
		'		} else if (iType == 3) // Log',
		'		{',
		'			inVal = value;',
		'		} else if (iType == 2 && nextKey) // Exp ',
		'		{',
		'			var previousKey = nextKey;',
		'			if (previousKey.index < numKeys)',
		'			{',
		'				var nextKey = key(previousKey.index + 1);',
		'  				inVal = expInterpolation(',
		'  					time,',
		'  					previousKey.time,',
		'  					nextKey.time,',
		'  					previousKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		}',
		'	  }',
		'	  // Out Extrapolation',
		'	  if (outExtrapolation)',
		'	  {',
		'	    var outTime = time;',
		'	    var prevKey = getPrevKey(time, thisProperty);',
		'	    ',
		'		if (iType == 6) outVal = continueOut(outTime, outDamping); // None',
		'		else if (iType == 5 && prevKey) // Linear ',
		'		{',
		'			var lastVelocity = (prevKey.value - iAtTime(prevKey.time - 0.01)) * 100;',
		'			var timeSpent = time - prevKey.time;',
		'			var damp = Math.exp(timeSpent * outDamping);',
		'			outVal = prevKey.value + (timeSpent * lastVelocity)/damp;',
		'		} else if (iType == 4 && prevKey) // Bezier',
		'		{',
		'			if (!bUseAdvanced) outVal = value;',
		'			else ',
		'			{',
		'  				if (bOutV == 0) outVal = value;',
		'  				else',
		'  				{',
		'  					var lastVelocity = ( prevKey.value - iAtTime(prevKey.time - 0.01)) * 100;',
		'    				var timeSpent = time - prevKey.time;',
		'    				var damp = Math.exp(timeSpent * outDamping);',
		'    				outVal = prevKey.value + (timeSpent * lastVelocity)/damp;',
		'  				}',
		'			}',
		'		} else if (iType == 1) // Gaussian',
		'		{',
		'			outVal = value;',
		'		} else if (iType == 3 && prevKey) // Log',
		'		{',
		'			var nextKey = prevKey;',
		'			if (nextKey.index > 0)',
		'			{',
		'				prevKey = key(nextKey.index - 1);',
		'				outVal = logInterpolation(',
		'  					time,',
		'  					prevKey.time,',
		'  					nextKey.time,',
		'  					prevKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		} else if (iType == 2 && prevKey) // Exp ',
		'		{',
		'			var nextKey = prevKey;',
		'			if (nextKey.index > 0)',
		'			{',
		'				 prevKey = key(nextKey.index - 1);',
		'				 outVal = expInterpolation(',
		'  					time,',
		'  					prevKey.time,',
		'  					nextKey.time,',
		'  					prevKey.value,',
		'  					nextKey.value,',
		'  					iRate',
		'  				);',
		'			}',
		'		}',
		'	  }',
		'	  ',
		'	  if (!pKey) return inVal;',
		'	  if (!nKey) return outVal;',
		'	  ',
		'	  // Blend',
		'	  return ease( time, pKey.time, nKey.time, outVal, inVal);',
		'	}',
		'',
		'	return iAtTime(time);',
		'}'
	].join('\n');

	var iExpr = [ DuAEExpression.Id.CAMERA_RIG,
		fxLink,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		iExprBody,
		'',
		'if (fx.enabled) result = i();',
		'result;'
	].join('\n');

	var rollExpr = [ DuAEExpression.Id.TWO_D_CAMERA,
	    fxLink,
		rollFX,
		'roll;'
    ].join('\n');

	var panExpr = [ DuAEExpression.Id.TWO_D_CAMERA,
		fxLink,
		panFX,
		tiltFX,
		'[ pan, tilt ] + [ thisComp.width/2, thisComp.height/2 ];'
    ].join('\n');

    // Rig camera
    // Tilt
	camZero.transform.rotation.expression = rollExpr;
	//zoom & truck in/out
	camZero.transform.scale.expression = [ DuAEExpression.Id.TWO_D_CAMERA,
        fxLink,
		zoomFX,
		dollyFX,
        'value + [zoom,zoom] + [dolly,dolly];'
    ].join('\n');
	//pan
	camZero.transform.position.expression = panExpr;
	//track
	camCtrl.transform.position.expression = [ DuAEExpression.Id.TWO_D_CAMERA,
		fxLink,
		gFreqFX,
		gAmpFX,
		sFreqFX,
		sAmpFX,
		camTypeFX,
		seedFX,
		trackFX,
		pedestalFX,
		'seedRandom(seed+3);',
		'complexity = 1;',
		'gAmp = gAmp * thisComp.width / 100;',
		'sAmp = sAmp * thisComp.width / 1000;',
		'if (camType == 2)',
		'{',
		'   gAmp = gAmp/2;',
		'   gFreq = gFreq*2;',
		'   complexity = 3;',
		'}',
		'else if (camType == 3)',
		'{',
		'   gAmp = gAmp/4;',
		'   complexity = 2;',
		'}',
		'else gAmp = 0;',
		'gw = wiggle(gFreq,gAmp, complexity , 0.5);',
		'sw = wiggle(sFreq,sAmp, complexity , 0.5);',
		'if (camType == 4) sw = [sw[0]/2,sw[1]];',
		'result = sw + gw - value + [track, pedestal];',
		'result;',
    ].join('\n');

    //behaviors
	effect( pe.props["Track left/right"].index ).expression = iExpr;
	effect( pe.props["Pedestal up/down"].index ).expression = iExpr;
	effect( pe.props["Dolly in/out"].index ).expression = iExpr;

    effect( pe.props["Pan left/right"].index ).expression = [ DuAEExpression.Id.TWO_D_CAMERA,
		fxLink,
		gFreqFX,
		gAmpFX,
		sFreqFX,
		sAmpFX,
		camTypeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	seedRandom(seed);',
		'	var complexity = 1;',
		'	gAmp = gAmp * thisComp.width / 100;',
		'	sAmp = sAmp * thisComp.width / 1000;',
		'	if (camType == 2)',
		'	{',
		'	   gAmp = gAmp/2;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (camType == 3)',
		'	{',
		'	   gAmp = gAmp*3/4;',
		'	   sAmp = sAmp/2;',
		'	   complexity = 3;',
		'	}',
		'	else if (camType == 4)',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else if (camType == 5)',
		'	{',
		'	   gAmp = gAmp/3;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity , 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
    ].join('\n');

	effect( pe.props["Tilt up/down"].index ).expression = [ DuAEExpression.Id.TWO_D_CAMERA,
		fxLink,
		gFreqFX,
		gAmpFX,
		sFreqFX,
		sAmpFX,
		camTypeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	seedRandom(seed+1);',
		'	var complexity = 1;',
		'	gAmp = gAmp * thisComp.width / 100;',
		'	sAmp = sAmp * thisComp.width / 1000;',
		'	if (camType == 2)',
		'	{',
		'	   gAmp = gAmp/2;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (camType == 3)',
		'	{',
		'	   gAmp = gAmp*3/4;',
		'	   sAmp = sAmp/2;',
		' 	  complexity = 3;',
		'	}',
		'	else if (camType == 4)',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = sAmp/2;',
		'	}',
		'	else if (camType == 5)',
		'	{',
		'	   gAmp = gAmp/3;',
		'	   sAmp = sAmp/4;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity, 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
    ].join('\n');

	effect( pe.props["Roll"].index ).expression = [ DuAEExpression.Id.TWO_D_CAMERA,
		fxLink,
		gFreqFX,
		gAmpFX,
		sFreqFX,
		sAmpFX,
		camTypeFX,
		seedFX,
		iTypeFX,
		iRateFX,
		bUseAdvancedFX,
		bInIFX,
		bOutIFX,
		bInVFX,
		bOutVFX,
		bRatioFX,
		'',
		'var result = value;',
		'',
		'function camRandomMotion()',
		'{',
		'	seedRandom(seed+2);',
		'	var complexity = 1;',
		'	if (camType == 2)',
		'	{',
		'	   gAmp = gAmp/5;',
		'	   sAmp = sAmp/5;',
		'	   gFreq = gFreq*2;',
		'	   complexity = 3;',
		'	}',
		'	else if (camType == 3)',
		'	{',
		'	   gAmp = gAmp/15;',
		'	   sAmp = sAmp/15;',
		'	   complexity = 2;',
		'	}',
		'	else',
		'	{',
		'	   gAmp = 0;',
		'	   sAmp = 0;',
		'	}',
		'	var gw = wiggle(gFreq,gAmp, complexity , 0.7);',
		'	gw -= value;',
		'	var sw = wiggle(sFreq,sAmp, complexity , 0.7);',
		'	sw -= value;',
		'	return sw + gw;',
		'}',
		'',
		iExprBody,
		'',
		'if (fx.enabled)',
		'{',
		'	result = camRandomMotion() + i();',
		'}',
		'result;'
    ].join('\n');

    // Create levels
	var ctrls = [camCtrl];
    for (var i = 1; i <= numLayers; i++)
    {
        var ctrl = DuAEComp.addNull( comp );

        var name = 'Level ' + DuNumber.toString(i, 2);
        if (layers.length > 0)
        {
            var l = layers[layers.length-i];
            name = name + ' ~ ' + l.name;
            l.parent = ctrl;
        }

		Duik.Layer.setAttributes( ctrl,
			Duik.Layer.Type.CONTROLLER,
			name,
			OCO.Side.NONE,
			OCO.Location.NONE,
			i18n._("2D Camera")
			);

        ctrl.shy = true;
        ctrl.moveAfter(camCtrl);

        // Add slider and default value
        var slider = ctrl.Effects.addProperty('ADBE Slider Control');
        slider.name = i18n._("Camera influence");

		var half = Math.floor(numLayers / 2);
        if ( i <= half )
		{
			var step = 100 / (half+1);
			slider(1).setValue( step*i );
		}
        else
		{
			var step = 50;
			slider(1).setValue( 100 + step * (i-half-1) );
		}

        //truck
        ctrl.transform.anchorPoint.expression = DuAEExpression.Id.TWO_D_CAMERA + '\nvar camPosition = thisComp.layer("' + camCtrl.name + '").transform.position.value;\nvalueAtTime(0) - camPosition * effect("' + slider.name + '")(1) / 100';

        //tilt
        ctrl.transform.rotation.expression = rollExpr;

        //zoom & truck in/out
        ctrl.transform.scale.expression = [ DuAEExpression.Id.TWO_D_CAMERA + '\n',
            fxLink,
			zoomFX,
			dollyFX,
            'var infl = effect("' + slider.name + '")(1);',
            'value + [zoom,zoom] + [dolly,dolly] * infl/100;'
		].join('\n');

        //pan
        ctrl.transform.position.expression = panExpr;

		ctrls.push(ctrl);
    }

    DuAEComp.unselectLayers();
    camCtrl.selected = true;

    DuAE.endUndoGroup( i18n._("2D Camera"));

    // Return
	return ctrls;
}
